-- ===== preserved implementation content from historical 0001_arvena_p0_schema.sql =====

-- ARVENA P0 schema v1.0.1
-- Binding source: ARVENA Architecture Correction Pack v1.0.1
create extension if not exists pgcrypto;
create schema if not exists app;

create or replace function app.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create or replace function app.bump_version() returns trigger language plpgsql as $$ begin if new is distinct from old then new.version=old.version+1; end if; return new; end $$;

-- Global configuration
create table if not exists public.currency_definitions(
  currency_code text primary key check(currency_code ~ '^[A-Z]{3}$'),
  minor_unit_exponent integer not null check(minor_unit_exponent between 0 and 6),
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists public.plan_versions(
  id uuid primary key default gen_random_uuid(), plan_key text not null check(plan_key in ('FREE','PRO','ULTRA')),
  version integer not null, effective_from timestamptz not null default now(), effective_to timestamptz, active boolean not null default true,
  unique(plan_key,version)
);
create table if not exists public.plan_entitlements(
  id uuid primary key default gen_random_uuid(), plan_version_id uuid not null references public.plan_versions(id),
  feature_key text not null, value_json jsonb not null, unique(plan_version_id,feature_key)
);
create table if not exists public.industry_templates(
  id uuid primary key default gen_random_uuid(), template_key text not null unique, name text not null, created_at timestamptz not null default now()
);
create table if not exists public.industry_template_versions(
  id uuid primary key default gen_random_uuid(), template_id uuid not null references public.industry_templates(id), version integer not null,
  terminology jsonb not null default '{}'::jsonb, state_mappings jsonb not null default '{}'::jsonb, checklist_defaults jsonb not null default '[]'::jsonb,
  recommended_modules jsonb not null default '[]'::jsonb, activated_at timestamptz, immutable boolean not null default true,
  unique(template_id,version)
);
create table if not exists public.system_role_templates(
  id uuid primary key default gen_random_uuid(), system_key text not null check(system_key in ('OWNER','ADMIN','SALES','WORKER','SUPERVISOR','FINANCE')),
  version integer not null default 1, name text not null, permissions jsonb not null default '[]'::jsonb, unique(system_key,version)
);

-- Identity / tenant
create table if not exists public.user_profiles(
  user_id uuid primary key references auth.users(id) on delete cascade,
  display_name text, phone text, locale text, timezone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create trigger trg_user_profiles_updated before update on public.user_profiles for each row execute function app.set_updated_at();

create table if not exists public.organizations(
  id uuid primary key default gen_random_uuid(), name text not null, slug text not null, country_code text not null check(country_code ~ '^[A-Z]{2}$'),
  currency_code text not null references public.currency_definitions(currency_code), timezone text not null, locale text not null default 'en',
  industry_template_version_id uuid references public.industry_template_versions(id), status text not null default 'ACTIVE' check(status in ('ACTIVE','SUSPENDED','ARCHIVED')),
  logo_media_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(id)
);
create unique index if not exists organizations_active_slug_uq on public.organizations(lower(slug)) where status <> 'ARCHIVED';
create trigger trg_organizations_updated before update on public.organizations for each row execute function app.set_updated_at();

create table if not exists public.organization_settings(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null,
  business_address jsonb not null default '{}'::jsonb, numbering jsonb not null default '{}'::jsonb, localization jsonb not null default '{}'::jsonb,
  workflow jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id), unique(organization_id,id), foreign key(organization_id) references public.organizations(id) on delete restrict
);
create trigger trg_org_settings_updated before update on public.organization_settings for each row execute function app.set_updated_at();
create trigger trg_org_settings_version before update on public.organization_settings for each row execute function app.bump_version();

create table if not exists public.organization_modules(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, module_key text not null, enabled boolean not null default true, config jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,module_key), unique(organization_id,id),
  foreign key(organization_id) references public.organizations(id) on delete restrict
);
create trigger trg_org_modules_updated before update on public.organization_modules for each row execute function app.set_updated_at();

create table if not exists public.roles(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, name text not null, system_key text check(system_key in ('OWNER','ADMIN','SALES','WORKER','SUPERVISOR','FINANCE')),
  is_system_role boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,name), unique(organization_id,system_key), foreign key(organization_id) references public.organizations(id) on delete restrict
);
create trigger trg_roles_updated before update on public.roles for each row execute function app.set_updated_at();

create table if not exists public.role_permissions(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, role_id uuid not null, permission_key text not null, allowed boolean not null default true,
  created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,role_id,permission_key),
  foreign key(organization_id,role_id) references public.roles(organization_id,id) on delete cascade
);

create table if not exists public.organization_invitations(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, email text not null, normalized_email text generated always as (lower(trim(email))) stored,
  intended_role_id uuid not null, inviter_member_id uuid, token_hash text, expires_at timestamptz not null, status text not null default 'PENDING' check(status in ('PENDING','ACCEPTED','EXPIRED','CANCELLED')),
  invited_at timestamptz not null default now(), accepted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id,id), foreign key(organization_id,intended_role_id) references public.roles(organization_id,id)
);
create unique index if not exists org_invite_pending_uq on public.organization_invitations(organization_id,normalized_email) where status='PENDING';
create trigger trg_org_invitations_updated before update on public.organization_invitations for each row execute function app.set_updated_at();

create table if not exists public.organization_members(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, user_id uuid not null references auth.users(id) on delete restrict, role_id uuid not null,
  status text not null default 'ACTIVE' check(status in ('INVITED','ACTIVE','DISABLED','ARCHIVED')), invited_at timestamptz, joined_at timestamptz, disabled_at timestamptz,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id,id), unique(organization_id,user_id), foreign key(organization_id,role_id) references public.roles(organization_id,id) on delete restrict,
  foreign key(organization_id) references public.organizations(id) on delete restrict
);
create trigger trg_org_members_updated before update on public.organization_members for each row execute function app.set_updated_at();
create trigger trg_org_members_version before update on public.organization_members for each row execute function app.bump_version();
alter table public.organization_invitations add constraint org_invite_inviter_fk foreign key(organization_id,inviter_member_id) references public.organization_members(organization_id,id) deferrable initially deferred;

create table if not exists public.member_permission_overrides(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, permission_key text not null, effect text not null check(effect in ('ALLOW','DENY')),
  reason text not null, actor_member_id uuid not null, expires_at timestamptz, created_at timestamptz not null default now(), archived_at timestamptz,
  unique(organization_id,id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id),
  foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);
create unique index if not exists member_permission_override_active_uq on public.member_permission_overrides(organization_id,member_id,permission_key) where archived_at is null;

create table if not exists public.member_skills(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, skill_key text not null, name text not null, active boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),
  foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create unique index if not exists member_skill_active_uq on public.member_skills(organization_id,member_id,skill_key) where active;

create table if not exists public.member_availability(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, weekday smallint not null check(weekday between 1 and 7),
  start_local_time time not null, end_local_time time not null, timezone text not null, effective_from date, effective_to date,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  check(end_local_time>start_local_time), check(effective_to is null or effective_from is null or effective_to>=effective_from), unique(organization_id,id),
  foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.member_leave(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, starts_at timestamptz not null, ends_at timestamptz not null,
  reason text, status text not null default 'APPROVED' check(status in ('PENDING','APPROVED','CANCELLED')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  check(ends_at>starts_at), unique(organization_id,id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.member_devices(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, device_id text not null, metadata jsonb not null default '{}'::jsonb,
  last_seen_at timestamptz, revoked_at timestamptz, created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,member_id,device_id),
  foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.member_team_scope(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, supervisor_member_id uuid not null, member_id uuid not null, created_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,supervisor_member_id,member_id),
  foreign key(organization_id,supervisor_member_id) references public.organization_members(organization_id,id),
  foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);

-- Subscription / entitlements
create table if not exists public.subscriptions(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, plan_version_id uuid not null references public.plan_versions(id),
  status text not null default 'ACTIVE' check(status in ('TRIALING','ACTIVE','PAST_DUE','CANCELLED')), period_start timestamptz not null, period_end timestamptz not null,
  provider_reference text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id),
  foreign key(organization_id) references public.organizations(id), check(period_end>period_start)
);
create unique index if not exists subscription_current_uq on public.subscriptions(organization_id) where status in ('TRIALING','ACTIVE','PAST_DUE');
create table if not exists public.organization_entitlement_overrides(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, feature_key text not null, value_json jsonb not null, reason text not null,
  approved_by uuid not null, valid_from timestamptz not null, valid_to timestamptz, created_at timestamptz not null default now(), unique(organization_id,id),
  foreign key(organization_id,approved_by) references public.organization_members(organization_id,id), check(valid_to is null or valid_to>valid_from)
);
create table if not exists public.usage_ledger(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, period_start timestamptz not null, period_end timestamptz not null, metric_key text not null,
  delta bigint not null, source_type text not null, source_id text not null, idempotency_key text not null, occurred_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,metric_key,source_type,source_id,idempotency_key), foreign key(organization_id) references public.organizations(id)
);
create table if not exists public.usage_counters(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, period_start timestamptz not null, period_end timestamptz not null, metric_key text not null,
  value bigint not null default 0 check(value>=0), reserved bigint not null default 0 check(reserved>=0), version integer not null default 1, updated_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,period_start,period_end,metric_key), foreign key(organization_id) references public.organizations(id), check(period_end>period_start)
);

-- CRM
create table if not exists public.customers(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, type text not null check(type in ('PERSON','COMPANY')), name text not null,
  raw_phone text, normalized_phone text, whatsapp_phone text, alternate_phone text, email text, source text, assigned_sales_id uuid, status text not null default 'ACTIVE' check(status in ('ACTIVE','ARCHIVED')),
  duplicate_of_customer_id uuid, duplicate_override_reason text, duplicate_override_by uuid, metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid, updated_by uuid, archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id) references public.organizations(id),
  foreign key(organization_id,assigned_sales_id) references public.organization_members(organization_id,id),
  foreign key(organization_id,duplicate_of_customer_id) references public.customers(organization_id,id),
  foreign key(organization_id,duplicate_override_by) references public.organization_members(organization_id,id),
  foreign key(organization_id,created_by) references public.organization_members(organization_id,id), foreign key(organization_id,updated_by) references public.organization_members(organization_id,id),
  check((duplicate_of_customer_id is null and duplicate_override_reason is null and duplicate_override_by is null) or (duplicate_of_customer_id is not null and duplicate_override_reason is not null and duplicate_override_by is not null))
);
create index if not exists customers_phone_idx on public.customers(organization_id,normalized_phone) where archived_at is null;
create index if not exists customers_name_idx on public.customers(organization_id,lower(name)) where archived_at is null;
create trigger trg_customers_updated before update on public.customers for each row execute function app.set_updated_at();
create trigger trg_customers_version before update on public.customers for each row execute function app.bump_version();

create table if not exists public.customer_addresses(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, label text, line1 text not null, line2 text, city text, region text,
  postal_code text, country_code text not null check(country_code ~ '^[A-Z]{2}$'), formatted_address text, latitude numeric(9,6), longitude numeric(9,6), provider_metadata jsonb,
  is_primary boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id),
  check(latitude is null or latitude between -90 and 90), check(longitude is null or longitude between -180 and 180)
);
create unique index if not exists customer_primary_address_uq on public.customer_addresses(organization_id,customer_id) where is_primary and archived_at is null;

create table if not exists public.tags(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, name text not null, normalized_name text generated always as (lower(trim(name))) stored,
  created_at timestamptz not null default now(), archived_at timestamptz, unique(organization_id,id), foreign key(organization_id) references public.organizations(id)
);
create unique index if not exists tags_active_name_uq on public.tags(organization_id,normalized_name) where archived_at is null;
create table if not exists public.customer_tags(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, tag_id uuid not null, created_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,customer_id,tag_id), foreign key(organization_id,customer_id) references public.customers(organization_id,id),
  foreign key(organization_id,tag_id) references public.tags(organization_id,id)
);
create table if not exists public.customer_contact_preferences(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, channel text not null, status text not null default 'UNKNOWN' check(status in ('UNKNOWN','OPTED_IN','OPTED_OUT')),
  source text, status_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,customer_id,channel), foreign key(organization_id,customer_id) references public.customers(organization_id,id)
);

create table if not exists public.service_catalog(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, item_type text not null default 'SERVICE', name text not null, description text, unit text,
  unit_price_minor bigint check(unit_price_minor>=0), currency_code text references public.currency_definitions(currency_code), tax_behavior text check(tax_behavior in ('EXCLUSIVE','INCLUSIVE','EXEMPT')),
  active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id) references public.organizations(id)
);

create table if not exists public.leads(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, title text not null, description text, service_catalog_id uuid,
  status text not null default 'NEW' check(status in ('NEW','CONTACTED','QUALIFIED','QUOTE','NEGOTIATION','WON','LOST')), temperature text not null default 'WARM' check(temperature in ('COLD','WARM','HOT')),
  source text, assigned_sales_id uuid, estimated_value_minor bigint check(estimated_value_minor is null or estimated_value_minor>=0), currency_code text references public.currency_definitions(currency_code),
  next_follow_up_at timestamptz, won_at timestamptz, lost_at timestamptz, lost_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id),
  foreign key(organization_id,service_catalog_id) references public.service_catalog(organization_id,id), foreign key(organization_id,assigned_sales_id) references public.organization_members(organization_id,id),
  check((status='WON' and won_at is not null) or status<>'WON'), check((status='LOST' and lost_at is not null and lost_reason is not null) or status<>'LOST')
);
create index if not exists leads_org_status_idx on public.leads(organization_id,status,updated_at desc);
create table if not exists public.lead_status_history(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, lead_id uuid not null, from_status text, to_status text not null, changed_by uuid not null,
  reason text, idempotency_key text not null, changed_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,lead_id,idempotency_key),
  foreign key(organization_id,lead_id) references public.leads(organization_id,id), foreign key(organization_id,changed_by) references public.organization_members(organization_id,id)
);

create table if not exists public.quotes(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, quote_number text, customer_id uuid not null, lead_id uuid, owner_member_id uuid,
  status text not null default 'DRAFT' check(status in ('DRAFT','ISSUED','ACCEPTED','REJECTED','EXPIRED')), currency_code text not null references public.currency_definitions(currency_code), currency_exponent smallint,
  subtotal_minor bigint not null default 0 check(subtotal_minor>=0), discount_minor bigint not null default 0 check(discount_minor>=0), tax_minor bigint not null default 0 check(tax_minor>=0), total_minor bigint not null default 0 check(total_minor>=0),
  document_discount_minor bigint not null default 0 check(document_discount_minor>=0), expires_at timestamptz, issued_at timestamptz, accepted_at timestamptz, customer_snapshot jsonb, organization_snapshot jsonb,
  terms_snapshot text, calculator_version text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), unique(organization_id,quote_number), foreign key(organization_id,customer_id) references public.customers(organization_id,id),
  foreign key(organization_id,lead_id) references public.leads(organization_id,id), foreign key(organization_id,owner_member_id) references public.organization_members(organization_id,id),
  check(total_minor=subtotal_minor-discount_minor+tax_minor)
);
create table if not exists public.quote_items(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, quote_id uuid not null, service_catalog_id uuid, name_snapshot text not null, description_snapshot text, unit_snapshot text,
  quantity numeric(18,6) not null check(quantity>=0), unit_price_minor bigint not null check(unit_price_minor>=0), line_discount_minor bigint not null default 0 check(line_discount_minor>=0),
  allocated_document_discount_minor bigint not null default 0 check(allocated_document_discount_minor>=0), tax_rate_ppm integer not null default 0 check(tax_rate_ppm between 0 and 1000000),
  tax_behavior text not null default 'EXEMPT' check(tax_behavior in ('EXCLUSIVE','INCLUSIVE','EXEMPT')), gross_minor bigint not null default 0 check(gross_minor>=0), discount_minor bigint not null default 0 check(discount_minor>=0), net_minor bigint not null default 0 check(net_minor>=0), tax_minor bigint not null default 0 check(tax_minor>=0), total_minor bigint not null default 0 check(total_minor>=0), sort_order integer not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,quote_id,sort_order),
  foreign key(organization_id,quote_id) references public.quotes(organization_id,id) on delete cascade, foreign key(organization_id,service_catalog_id) references public.service_catalog(organization_id,id)
);

create table if not exists public.follow_ups(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, lead_id uuid, quote_id uuid, job_id uuid, invoice_id uuid,
  assigned_to uuid not null, reason text not null, due_at timestamptz not null, timezone text not null, status text not null default 'PENDING' check(status in ('PENDING','DONE','CANCELLED')),
  completed_at timestamptz, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id), foreign key(organization_id,lead_id) references public.leads(organization_id,id),
  foreign key(organization_id,quote_id) references public.quotes(organization_id,id), foreign key(organization_id,assigned_to) references public.organization_members(organization_id,id),
  check(num_nonnulls(lead_id,quote_id,job_id,invoice_id)<=1), check((status='DONE' and completed_at is not null) or status<>'DONE')
);
create table if not exists public.follow_up_history(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, follow_up_id uuid not null, old_due_at timestamptz, new_due_at timestamptz, old_state text, new_state text,
  reason text, actor_member_id uuid not null, idempotency_key text not null, created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,follow_up_id,idempotency_key),
  foreign key(organization_id,follow_up_id) references public.follow_ups(organization_id,id), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);

-- Work and scheduling
create table if not exists public.document_sequences(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, document_type text not null check(document_type in ('JOB','QUOTE','INVOICE')), period_key text not null, next_value bigint not null default 1 check(next_value>0),
  unique(organization_id,id), unique(organization_id,document_type,period_key), foreign key(organization_id) references public.organizations(id)
);
create table if not exists public.jobs(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_number text, customer_id uuid not null, lead_id uuid, quote_id uuid, title text not null, description text,
  status text not null default 'DRAFT' check(status in ('DRAFT','CONFIRMED','SCHEDULED','IN_PROGRESS','ON_HOLD','COMPLETED','CANCELLED')), priority text not null default 'NORMAL' check(priority in ('LOW','NORMAL','HIGH','URGENT')),
  primary_address_id uuid, currency_code text references public.currency_definitions(currency_code), estimated_amount_minor bigint check(estimated_amount_minor is null or estimated_amount_minor>=0),
  scheduled_start timestamptz, scheduled_end timestamptz, completed_at timestamptz, cancelled_at timestamptz, cancellation_reason text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), unique(organization_id,job_number), unique(organization_id,quote_id), foreign key(organization_id,customer_id) references public.customers(organization_id,id),
  foreign key(organization_id,lead_id) references public.leads(organization_id,id), foreign key(organization_id,quote_id) references public.quotes(organization_id,id),
  foreign key(organization_id,primary_address_id) references public.customer_addresses(organization_id,id)
);
alter table public.follow_ups add constraint followups_job_fk foreign key(organization_id,job_id) references public.jobs(organization_id,id);
create table if not exists public.job_items(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_id uuid not null, service_catalog_id uuid, name_snapshot text not null, quantity numeric(18,6) not null default 1 check(quantity>=0),
  unit_price_minor bigint check(unit_price_minor is null or unit_price_minor>=0), notes text, created_at timestamptz not null default now(), unique(organization_id,id),
  foreign key(organization_id,job_id) references public.jobs(organization_id,id) on delete cascade, foreign key(organization_id,service_catalog_id) references public.service_catalog(organization_id,id)
);
create table if not exists public.visits(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_id uuid not null, visit_type text not null default 'SERVICE', status text not null default 'SCHEDULED' check(status in ('SCHEDULED','EN_ROUTE','ARRIVED','IN_PROGRESS','COMPLETED','CANCELLED','NO_SHOW')),
  scheduled_start timestamptz not null, scheduled_end timestamptz not null, scheduled_local_start timestamp, scheduled_local_end timestamp, timezone text not null,
  actual_departed_at timestamptz, actual_arrived_at timestamptz, actual_started_at timestamptz, actual_completed_at timestamptz, address_snapshot jsonb not null default '{}'::jsonb,
  completion_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,job_id) references public.jobs(organization_id,id), check(scheduled_end>scheduled_start)
);
create index if not exists visits_org_schedule_idx on public.visits(organization_id,scheduled_start,status);
create table if not exists public.visit_assignments(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, visit_id uuid not null, member_id uuid not null, assignment_role text not null default 'WORKER', assigned_at timestamptz not null default now(), removed_at timestamptz,
  unique(organization_id,id), foreign key(organization_id,visit_id) references public.visits(organization_id,id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create unique index if not exists visit_assignment_active_uq on public.visit_assignments(organization_id,visit_id,member_id) where removed_at is null;
create table if not exists public.schedule_conflict_overrides(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, visit_id uuid not null, conflicting_visit_id uuid not null, visit_version integer not null, actor_member_id uuid not null, reason text not null, created_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,visit_id,conflicting_visit_id,visit_version), foreign key(organization_id,visit_id) references public.visits(organization_id,id),
  foreign key(organization_id,conflicting_visit_id) references public.visits(organization_id,id), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id), check(visit_id<>conflicting_visit_id)
);

create table if not exists public.checklist_templates(
  id uuid primary key default gen_random_uuid(), organization_id uuid, industry_template_version_id uuid references public.industry_template_versions(id), name text not null, version integer not null default 1, active boolean not null default true,
  created_at timestamptz not null default now(), unique(id), unique(organization_id,id), check((organization_id is null) <> (industry_template_version_id is null)),
  foreign key(organization_id) references public.organizations(id)
);
create table if not exists public.checklist_template_items(
  id uuid primary key default gen_random_uuid(), organization_id uuid, checklist_template_id uuid not null references public.checklist_templates(id), item_key text not null, input_type text not null check(input_type in ('CHECKBOX','NUMBER','TEXT','YES_NO','PHOTO')),
  label text not null, required boolean not null default false, config jsonb not null default '{}'::jsonb, sort_order integer not null, created_at timestamptz not null default now(),
  unique(checklist_template_id,item_key), unique(checklist_template_id,sort_order)
);
create table if not exists public.job_checklists(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_id uuid not null, visit_id uuid, template_snapshot jsonb not null, status text not null default 'PENDING' check(status in ('PENDING','IN_PROGRESS','COMPLETE')),
  required boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,job_id) references public.jobs(organization_id,id), foreign key(organization_id,visit_id) references public.visits(organization_id,id)
);
create table if not exists public.checklist_responses(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_checklist_id uuid not null, template_item_key text not null, value jsonb not null,
  completed_by uuid not null, completed_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id,id), unique(organization_id,job_checklist_id,template_item_key), foreign key(organization_id,job_checklist_id) references public.job_checklists(organization_id,id),
  foreign key(organization_id,completed_by) references public.organization_members(organization_id,id)
);

create table if not exists public.media(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, parent_type text not null check(parent_type in ('CUSTOMER','JOB','VISIT','ASSET','IMPORT','EXPORT')), parent_id uuid not null,
  category text not null, storage_key text not null, mime_type text not null, checksum text not null, size_bytes bigint not null check(size_bytes>=0), upload_status text not null default 'UPLOADING' check(upload_status in ('UPLOADING','UPLOADED','FAILED')),
  quota_reserved_bytes bigint not null default 0 check(quota_reserved_bytes>=0), attempts integer not null default 0 check(attempts>=0), uploaded_by uuid not null, error_code text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz,
  unique(organization_id,id), unique(storage_key), foreign key(organization_id,uploaded_by) references public.organization_members(organization_id,id)
);
create table if not exists public.notes(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, entity_type text not null check(entity_type in ('CUSTOMER','LEAD','JOB','VISIT','INVOICE','ASSET')), entity_id uuid not null,
  body text not null, visibility text not null default 'OPERATIONAL' check(visibility in ('OPERATIONAL','WORKER','SALES','FINANCE','OWNER')), author_id uuid not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,author_id) references public.organization_members(organization_id,id)
);
create table if not exists public.assets(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, asset_type text not null, name text not null, brand text, model text, serial_number text,
  installed_at date, warranty_until date, status text not null default 'ACTIVE' check(status in ('ACTIVE','INACTIVE','ARCHIVED')), notes text, metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id)
);
create index if not exists assets_serial_idx on public.assets(organization_id,serial_number) where archived_at is null;
create table if not exists public.job_assets(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, job_id uuid not null, asset_id uuid not null, created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,job_id,asset_id),
  foreign key(organization_id,job_id) references public.jobs(organization_id,id), foreign key(organization_id,asset_id) references public.assets(organization_id,id)
);

-- Billing
create table if not exists public.tax_profiles(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, name text not null, rate_ppm integer not null check(rate_ppm between 0 and 1000000), behavior text not null check(behavior in ('EXCLUSIVE','INCLUSIVE','EXEMPT')),
  effective_from timestamptz not null default now(), effective_to timestamptz, active boolean not null default true, is_default boolean not null default false,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1, unique(organization_id,id), foreign key(organization_id) references public.organizations(id), check(effective_to is null or effective_to>effective_from)
);
create unique index if not exists tax_default_active_uq on public.tax_profiles(organization_id) where active and is_default and effective_to is null;
create table if not exists public.invoices(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, invoice_number text, customer_id uuid not null, job_id uuid, quote_id uuid, status text not null default 'DRAFT' check(status in ('DRAFT','ISSUED','PARTIALLY_PAID','PAID','OVERDUE','VOID')),
  currency_code text not null references public.currency_definitions(currency_code), currency_exponent smallint, subtotal_minor bigint not null default 0 check(subtotal_minor>=0), discount_minor bigint not null default 0 check(discount_minor>=0), tax_minor bigint not null default 0 check(tax_minor>=0), total_minor bigint not null default 0 check(total_minor>=0),
  paid_minor bigint not null default 0 check(paid_minor>=0), outstanding_minor bigint not null default 0 check(outstanding_minor>=0), document_discount_minor bigint not null default 0 check(document_discount_minor>=0),
  issued_at timestamptz, due_at timestamptz, paid_at timestamptz, customer_snapshot jsonb, organization_snapshot jsonb, terms_snapshot text, calculator_version text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz, version integer not null default 1,
  unique(organization_id,id), unique(organization_id,invoice_number), foreign key(organization_id,customer_id) references public.customers(organization_id,id), foreign key(organization_id,job_id) references public.jobs(organization_id,id), foreign key(organization_id,quote_id) references public.quotes(organization_id,id),
  check(total_minor=subtotal_minor-discount_minor+tax_minor), check(paid_minor<=total_minor), check(outstanding_minor=total_minor-paid_minor)
);
alter table public.follow_ups add constraint followups_invoice_fk foreign key(organization_id,invoice_id) references public.invoices(organization_id,id);
create table if not exists public.invoice_items(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, invoice_id uuid not null, name_snapshot text not null, description_snapshot text, quantity numeric(18,6) not null check(quantity>=0), unit_snapshot text,
  unit_price_minor bigint not null check(unit_price_minor>=0), line_discount_minor bigint not null default 0 check(line_discount_minor>=0), allocated_document_discount_minor bigint not null default 0 check(allocated_document_discount_minor>=0),
  tax_rate_ppm integer not null default 0 check(tax_rate_ppm between 0 and 1000000), tax_behavior text not null default 'EXEMPT' check(tax_behavior in ('EXCLUSIVE','INCLUSIVE','EXEMPT')),
  gross_minor bigint not null default 0 check(gross_minor>=0), discount_minor bigint not null default 0 check(discount_minor>=0), net_minor bigint not null default 0 check(net_minor>=0), tax_minor bigint not null default 0 check(tax_minor>=0), total_minor bigint not null default 0 check(total_minor>=0), sort_order integer not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,invoice_id,sort_order), foreign key(organization_id,invoice_id) references public.invoices(organization_id,id) on delete cascade
);
create table if not exists public.payments(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, invoice_id uuid not null, amount_minor bigint not null check(amount_minor>0), currency_code text not null references public.currency_definitions(currency_code),
  method text not null check(method in ('CASH','BANK_TRANSFER','QR','CARD','OTHER')), reference text, paid_at timestamptz not null, received_by uuid not null, notes text, status text not null default 'SETTLED' check(status in ('SETTLED','REVERSED')),
  idempotency_key text not null, created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,idempotency_key), foreign key(organization_id,invoice_id) references public.invoices(organization_id,id), foreign key(organization_id,received_by) references public.organization_members(organization_id,id)
);
create table if not exists public.payment_reversals(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, payment_id uuid not null, amount_minor bigint not null check(amount_minor>0), reason text not null, actor_member_id uuid not null,
  idempotency_key text not null, created_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,payment_id), unique(organization_id,idempotency_key),
  foreign key(organization_id,payment_id) references public.payments(organization_id,id), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.document_state_history(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, entity_type text not null check(entity_type in ('QUOTE','JOB','VISIT','INVOICE')), entity_id uuid not null, from_state text, to_state text not null,
  actor_member_id uuid, reason text, entity_version integer, idempotency_key text not null, occurred_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,entity_type,entity_id,idempotency_key),
  foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);

-- Recurring / events / reliability
create table if not exists public.recurring_rules(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, customer_id uuid not null, service_catalog_id uuid, asset_id uuid, recurrence_type text not null check(recurrence_type in ('DAILY','WEEKLY','MONTHLY','YEARLY','CUSTOM_DAYS')),
  interval_value integer not null default 1 check(interval_value>0), weekday_config jsonb not null default '[]'::jsonb, local_time time not null, timezone text not null, starts_on date not null, ends_on date,
  next_occurrence_at timestamptz, active boolean not null default true, template_data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), version integer not null default 1,
  unique(organization_id,id), foreign key(organization_id,customer_id) references public.customers(organization_id,id), foreign key(organization_id,service_catalog_id) references public.service_catalog(organization_id,id), foreign key(organization_id,asset_id) references public.assets(organization_id,id), check(ends_on is null or ends_on>=starts_on)
);
create table if not exists public.recurring_occurrences(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, recurring_rule_id uuid not null, intended_local_date date not null, intended_local_time time not null, timezone text not null,
  resolved_occurrence_at timestamptz not null, resolved_offset_minutes integer not null, dst_resolution text not null default 'EXACT' check(dst_resolution in ('EXACT','DST_GAP_SHIFTED','DST_OVERLAP_EARLIER_OFFSET')),
  rule_version integer not null, rule_snapshot jsonb not null, status text not null default 'PENDING' check(status in ('PENDING','GENERATING','GENERATED','SKIPPED','CANCELLED','FAILED_RETRYABLE','FAILED_FINAL')),
  generated_job_id uuid, reason text, attempts integer not null default 0, next_attempt_at timestamptz, lease_owner text, lease_expires_at timestamptz, last_error_code text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,generated_job_id),
  foreign key(organization_id,recurring_rule_id) references public.recurring_rules(organization_id,id), foreign key(organization_id,generated_job_id) references public.jobs(organization_id,id)
);
create unique index if not exists recurring_occurrence_identity_uq on public.recurring_occurrences(organization_id,recurring_rule_id,intended_local_date,intended_local_time,rule_version);

create table if not exists public.activities(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, entity_type text not null, entity_id uuid not null, actor_id uuid, event_type text not null, summary text not null, metadata jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(),
  unique(organization_id,id), foreign key(organization_id,actor_id) references public.organization_members(organization_id,id)
);
create table if not exists public.audit_logs(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, actor_id uuid, action text not null, entity_type text not null, entity_id uuid not null, before_json jsonb, after_json jsonb, request_id text, trace_id text,
  ip_address inet, user_agent text, occurred_at timestamptz not null default now(), unique(organization_id,id), foreign key(organization_id,actor_id) references public.organization_members(organization_id,id)
);
create table if not exists public.idempotency_receipts(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, actor_member_id uuid, producer text not null default 'client', scope text not null, idempotency_key text not null, request_hash text not null,
  state text not null default 'APPLIED' check(state in ('APPLIED','FAILED')), result_reference jsonb, response_hash text, expires_at timestamptz, created_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,producer,scope,idempotency_key), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.client_action_receipts(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, device_id text not null, client_action_id uuid not null, sequence bigint not null, entity_type text not null, entity_id uuid not null, action text not null,
  expected_version integer, payload_version integer not null, payload_hash text not null, local_occurred_at timestamptz, dependencies jsonb not null default '[]'::jsonb,
  result text not null check(result in ('APPLIED','DUPLICATE','CONFLICT','REJECTED','RETRYABLE')), response jsonb, error_code text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,member_id,device_id,client_action_id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create index if not exists client_action_receipts_sequence_idx on public.client_action_receipts(organization_id,member_id,device_id,sequence,created_at);
create table if not exists public.client_device_sequences(
  organization_id uuid not null, member_id uuid not null, device_id text not null, last_accepted_sequence bigint not null default 0, updated_at timestamptz not null default now(),
  primary key(organization_id,member_id,device_id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id) on delete cascade
);
create table if not exists public.client_action_sequence_slots(
  organization_id uuid not null, member_id uuid not null, device_id text not null, sequence bigint not null check(sequence>0), client_action_id uuid not null, payload_hash text not null, created_at timestamptz not null default now(),
  primary key(organization_id,member_id,device_id,sequence), unique(organization_id,member_id,device_id,client_action_id), foreign key(organization_id,member_id) references public.organization_members(organization_id,id) on delete cascade
);
create table if not exists public.client_action_attempts(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, device_id text not null, client_action_id uuid, sequence bigint, payload_hash text, outcome text not null check(outcome in ('APPLIED','DUPLICATE','CONFLICT','REJECTED','RETRYABLE')), error_code text, raw_action jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(),
  foreign key(organization_id,member_id) references public.organization_members(organization_id,id) on delete cascade
);
create index if not exists client_action_attempts_lookup_idx on public.client_action_attempts(organization_id,member_id,device_id,sequence,created_at);
create table if not exists public.event_outbox(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, event_id uuid not null default gen_random_uuid(), event_type text not null, payload_version integer not null default 1,
  entity_type text not null, entity_id uuid not null, actor_id uuid, payload jsonb not null default '{}'::jsonb, dedupe_key text, trace_id text, causation_id uuid, correlation_id uuid,
  status text not null default 'PENDING' check(status in ('PENDING','CLAIMED','SUCCEEDED','FAILED_RETRYABLE','FAILED_FINAL','CANCELLED')), attempts integer not null default 0, available_at timestamptz not null default now(), lease_owner text, lease_expires_at timestamptz, last_error_code text, last_error text,
  created_at timestamptz not null default now(), completed_at timestamptz, unique(organization_id,id), unique(event_id), foreign key(organization_id,actor_id) references public.organization_members(organization_id,id)
);
create unique index if not exists outbox_dedupe_uq on public.event_outbox(organization_id,event_type,dedupe_key) where dedupe_key is not null;
create table if not exists public.queue_jobs(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, topic text not null, outbox_event_id uuid, task_reference text, payload jsonb not null default '{}'::jsonb, payload_version integer not null default 1, task_dedupe_key text not null,
  status text not null default 'PENDING' check(status in ('PENDING','CLAIMED','SUCCEEDED','FAILED_RETRYABLE','FAILED_FINAL','CANCELLED')), attempts integer not null default 0, next_attempt_at timestamptz not null default now(), lease_owner text, lease_expires_at timestamptz, last_error_code text, last_error text, completed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,task_dedupe_key), foreign key(organization_id,outbox_event_id) references public.event_outbox(organization_id,id)
);
create table if not exists public.notifications(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, recipient_member_id uuid not null, type text not null, title text not null, body text not null, read_at timestamptz, entity_type text, entity_id uuid, created_at timestamptz not null default now(),
  unique(organization_id,id), foreign key(organization_id,recipient_member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.notification_deliveries(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, notification_id uuid not null, channel text not null, logical_destination text not null, state text not null default 'PENDING' check(state in ('PENDING','SENT','FAILED_RETRYABLE','FAILED_FINAL','CANCELLED')),
  attempts integer not null default 0, provider_reference text, scheduled_at timestamptz, sent_at timestamptz, failed_at timestamptz, last_error_code text, created_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,notification_id,channel,logical_destination), foreign key(organization_id,notification_id) references public.notifications(organization_id,id)
);
create table if not exists public.notification_preferences(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, member_id uuid not null, notification_type text not null, channel text not null, enabled boolean not null default true, quiet_start time, quiet_end time, timezone text,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,member_id,notification_type,channel), foreign key(organization_id,member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.import_jobs(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, actor_member_id uuid not null, kind text not null check(kind in ('CUSTOMERS','ASSETS_BASIC')), source_media_id uuid,
  mapping jsonb not null default '{}'::jsonb, schema_version integer not null default 1, status text not null default 'UPLOADED' check(status in ('UPLOADED','MAPPED','VALIDATED','COMMITTING','COMPLETED','FAILED')),
  valid_count integer not null default 0, duplicate_count integer not null default 0, error_count integer not null default 0, committed_count integer not null default 0, command_key text not null,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,command_key), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);
create table if not exists public.import_rows(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, import_job_id uuid not null, source_row integer not null, normalized_payload jsonb not null, validation_errors jsonb not null default '[]'::jsonb,
  duplicate_customer_id uuid, duplicate_decision text check(duplicate_decision in ('USE_EXISTING','CREATE_OVERRIDE','SKIP')), target_record_id uuid, commit_state text not null default 'PENDING' check(commit_state in ('PENDING','COMMITTED','SKIPPED','ERROR')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,id), unique(organization_id,import_job_id,source_row),
  foreign key(organization_id,import_job_id) references public.import_jobs(organization_id,id), foreign key(organization_id,duplicate_customer_id) references public.customers(organization_id,id)
);
create table if not exists public.export_jobs(
  id uuid primary key default gen_random_uuid(), organization_id uuid not null, actor_member_id uuid not null, dataset text not null check(dataset in ('CUSTOMERS','JOBS','INVOICES','PAYMENTS')), filter jsonb not null default '{}'::jsonb, schema_version integer not null default 1,
  state text not null default 'PENDING' check(state in ('PENDING','READY','FAILED','EXPIRED')), result_media_id uuid, expires_at timestamptz, command_key text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique(organization_id,id), unique(organization_id,command_key), foreign key(organization_id,actor_member_id) references public.organization_members(organization_id,id)
);

-- Parent validator for polymorphic records and media.
create or replace function app.entity_belongs_to_org(p_org uuid,p_type text,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
begin
  case upper(p_type)
    when 'CUSTOMER' then return exists(select 1 from customers where organization_id=p_org and id=p_id);
    when 'LEAD' then return exists(select 1 from leads where organization_id=p_org and id=p_id);
    when 'QUOTE' then return exists(select 1 from quotes where organization_id=p_org and id=p_id);
    when 'JOB' then return exists(select 1 from jobs where organization_id=p_org and id=p_id);
    when 'VISIT' then return exists(select 1 from visits where organization_id=p_org and id=p_id);
    when 'INVOICE' then return exists(select 1 from invoices where organization_id=p_org and id=p_id);
    when 'ASSET' then return exists(select 1 from assets where organization_id=p_org and id=p_id);
    when 'IMPORT' then return exists(select 1 from import_jobs where organization_id=p_org and id=p_id);
    when 'EXPORT' then return exists(select 1 from export_jobs where organization_id=p_org and id=p_id);
    else return false;
  end case;
end $$;
create or replace function app.validate_polymorphic_target() returns trigger language plpgsql as $$ begin if not app.entity_belongs_to_org(new.organization_id,new.entity_type,new.entity_id) then raise exception 'ARV-TENANT-1003 invalid polymorphic target'; end if; return new; end $$;
create trigger trg_notes_target before insert or update of organization_id,entity_type,entity_id on public.notes for each row execute function app.validate_polymorphic_target();
create trigger trg_activities_target before insert or update of organization_id,entity_type,entity_id on public.activities for each row execute function app.validate_polymorphic_target();
create trigger trg_audit_target before insert or update of organization_id,entity_type,entity_id on public.audit_logs for each row execute function app.validate_polymorphic_target();
create or replace function app.validate_media_parent() returns trigger language plpgsql as $$ begin if not app.entity_belongs_to_org(new.organization_id,new.parent_type,new.parent_id) then raise exception 'ARV-TENANT-1003 invalid media parent'; end if; return new; end $$;
create trigger trg_media_parent before insert or update of organization_id,parent_type,parent_id on public.media for each row execute function app.validate_media_parent();

