-- Issued document/item immutability guards.
create or replace function app.guard_quote_immutability() returns trigger language plpgsql as $$ begin
  if old.status <> 'DRAFT' then
    if new.customer_id is distinct from old.customer_id or new.lead_id is distinct from old.lead_id or new.currency_code is distinct from old.currency_code or
       new.subtotal_minor is distinct from old.subtotal_minor or new.discount_minor is distinct from old.discount_minor or new.tax_minor is distinct from old.tax_minor or new.total_minor is distinct from old.total_minor or
       new.customer_snapshot is distinct from old.customer_snapshot or new.organization_snapshot is distinct from old.organization_snapshot or new.terms_snapshot is distinct from old.terms_snapshot or new.calculator_version is distinct from old.calculator_version
    then raise exception 'ARV-MONEY-3001 issued quote snapshot is immutable'; end if;
  end if; return new; end $$;
create trigger trg_quote_immutable before update on public.quotes for each row execute function app.guard_quote_immutability();
create or replace function app.guard_quote_item_mutation() returns trigger language plpgsql as $$ declare s text; begin
  select status into s from quotes where organization_id=coalesce(new.organization_id,old.organization_id) and id=coalesce(new.quote_id,old.quote_id);
  if s <> 'DRAFT' then raise exception 'ARV-MONEY-3001 issued quote items are immutable'; end if; return coalesce(new,old); end $$;
create trigger trg_quote_item_immutable before insert or update or delete on public.quote_items for each row execute function app.guard_quote_item_mutation();
create or replace function app.guard_invoice_immutability() returns trigger language plpgsql as $$ begin
  if old.status <> 'DRAFT' then
    if new.customer_id is distinct from old.customer_id or new.job_id is distinct from old.job_id or new.quote_id is distinct from old.quote_id or new.currency_code is distinct from old.currency_code or
       new.subtotal_minor is distinct from old.subtotal_minor or new.discount_minor is distinct from old.discount_minor or new.tax_minor is distinct from old.tax_minor or new.total_minor is distinct from old.total_minor or
       new.customer_snapshot is distinct from old.customer_snapshot or new.organization_snapshot is distinct from old.organization_snapshot or new.terms_snapshot is distinct from old.terms_snapshot or new.calculator_version is distinct from old.calculator_version
    then raise exception 'ARV-MONEY-3001 issued invoice snapshot is immutable'; end if;
  end if; return new; end $$;
create trigger trg_invoice_immutable before update on public.invoices for each row execute function app.guard_invoice_immutability();
create or replace function app.guard_invoice_item_mutation() returns trigger language plpgsql as $$ declare s text; begin
  select status into s from invoices where organization_id=coalesce(new.organization_id,old.organization_id) and id=coalesce(new.invoice_id,old.invoice_id);
  if s <> 'DRAFT' then raise exception 'ARV-MONEY-3001 issued invoice items are immutable'; end if; return coalesce(new,old); end $$;
create trigger trg_invoice_item_immutable before insert or update or delete on public.invoice_items for each row execute function app.guard_invoice_item_mutation();
create or replace function app.guard_payment_immutability() returns trigger language plpgsql as $$ begin
  if tg_op='DELETE' then raise exception 'ARV-MONEY-3002 payments cannot be deleted'; end if;
  if new.amount_minor<>old.amount_minor or new.currency_code<>old.currency_code or new.invoice_id<>old.invoice_id or new.paid_at<>old.paid_at or new.received_by<>old.received_by then raise exception 'ARV-MONEY-3002 settled payment is immutable'; end if;
  if old.status='REVERSED' and new.status<>'REVERSED' then raise exception 'ARV-MONEY-3002 reversed payment is terminal'; end if; return new;
end $$;
create trigger trg_payment_immutable before update or delete on public.payments for each row execute function app.guard_payment_immutability();

-- Final owner concurrency safety.
create or replace function app.guard_final_owner() returns trigger language plpgsql security definer set search_path=public,app as $$
declare old_key text; new_key text; active_owners int;
begin
  select system_key into old_key from roles where organization_id=old.organization_id and id=old.role_id;
  if tg_op='UPDATE' then select system_key into new_key from roles where organization_id=new.organization_id and id=new.role_id; end if;
  if old.status='ACTIVE' and old_key='OWNER' and (new.status<>'ACTIVE' or new_key<>'OWNER') then
    perform pg_advisory_xact_lock(hashtextextended(old.organization_id::text,0));
    select count(*) into active_owners from organization_members m join roles r on r.organization_id=m.organization_id and r.id=m.role_id
      where m.organization_id=old.organization_id and m.status='ACTIVE' and r.system_key='OWNER' and m.id<>old.id;
    if active_owners<1 then raise exception 'ARV-TENANT-1003 final active Owner cannot be removed, disabled or demoted'; end if;
  end if; return new;
end $$;
create trigger trg_final_owner before update on public.organization_members for each row execute function app.guard_final_owner();

