create or replace function app.current_member_id(p_org uuid) returns uuid language sql stable security definer set search_path=public,app as $$
  select m.id from organization_members m where m.organization_id=p_org and m.user_id=auth.uid() and m.status='ACTIVE' limit 1
$$;
create or replace function app.current_role_key(p_org uuid) returns text language sql stable security definer set search_path=public,app as $$
  select r.system_key from organization_members m join roles r on r.organization_id=m.organization_id and r.id=m.role_id
  where m.organization_id=p_org and m.user_id=auth.uid() and m.status='ACTIVE' limit 1
$$;
create or replace function app.has_permission(p_org uuid,p_key text) returns boolean language sql stable security definer set search_path=public,app as $$
  with me as (select id,role_id from organization_members where organization_id=p_org and user_id=auth.uid() and status='ACTIVE'),
  base as (select rp.allowed from role_permissions rp join me on me.role_id=rp.role_id where rp.organization_id=p_org and rp.permission_key=p_key),
  ov as (select effect from member_permission_overrides o join me on me.id=o.member_id where o.organization_id=p_org and o.permission_key=p_key and o.archived_at is null and (o.expires_at is null or o.expires_at>now()) limit 1)
  select case when (select effect from ov)='DENY' then false when (select effect from ov)='ALLOW' then true else coalesce((select allowed from base),false) end
$$;
create or replace function app.require_member(p_org uuid) returns uuid language plpgsql stable security definer set search_path=public,app as $$ declare m uuid; begin m:=app.current_member_id(p_org); if m is null then raise exception 'ARV-TENANT-1002 active membership required'; end if; return m; end $$;
create or replace function app.require_permission(p_org uuid,p_key text) returns uuid language plpgsql stable security definer set search_path=public,app as $$ declare m uuid; begin m:=app.require_member(p_org); if not app.has_permission(p_org,p_key) then raise exception 'ARV-PERM-1001 permission denied: %',p_key; end if; return m; end $$;

create or replace view public.effective_member_permissions with (security_invoker=true) as
select m.organization_id,m.id member_id,rp.permission_key,
  case when od.effect='DENY' then false when oa.effect='ALLOW' then true else rp.allowed end as allowed
from organization_members m join role_permissions rp on rp.organization_id=m.organization_id and rp.role_id=m.role_id
left join lateral(select effect from member_permission_overrides o where o.organization_id=m.organization_id and o.member_id=m.id and o.permission_key=rp.permission_key and o.archived_at is null and (o.expires_at is null or o.expires_at>now()) and effect='DENY' limit 1) od on true
left join lateral(select effect from member_permission_overrides o where o.organization_id=m.organization_id and o.member_id=m.id and o.permission_key=rp.permission_key and o.archived_at is null and (o.expires_at is null or o.expires_at>now()) and effect='ALLOW' limit 1) oa on true
where m.status='ACTIVE' and (case when od.effect='DENY' then false when oa.effect='ALLOW' then true else rp.allowed end)=true;

create or replace function app.idempotency_existing(p_org uuid,p_member uuid,p_scope text,p_key text,p_hash text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare r idempotency_receipts%rowtype; begin
  select * into r from idempotency_receipts where organization_id=p_org and producer='client' and scope=p_scope and idempotency_key=p_key;
  if found then if r.request_hash<>p_hash then raise exception 'ARV-CONFLICT-1001 idempotency key payload mismatch'; end if; return r.result_reference; end if;
  return null;
end $$;
create or replace function app.idempotency_commit(p_org uuid,p_member uuid,p_scope text,p_key text,p_hash text,p_result jsonb) returns void language plpgsql security definer set search_path=public,app as $$ begin
  insert into idempotency_receipts(organization_id,actor_member_id,producer,scope,idempotency_key,request_hash,result_reference) values(p_org,p_member,'client',p_scope,p_key,p_hash,p_result);
end $$;
create or replace function app.emit_event(p_org uuid,p_actor uuid,p_type text,p_entity_type text,p_entity_id uuid,p_payload jsonb default '{}'::jsonb,p_dedupe text default null) returns uuid language plpgsql security definer set search_path=public,app as $$ declare eid uuid:=gen_random_uuid(); begin
 insert into event_outbox(organization_id,event_id,event_type,entity_type,entity_id,actor_id,payload,dedupe_key) values(p_org,eid,p_type,p_entity_type,p_entity_id,p_actor,coalesce(p_payload,'{}'::jsonb),p_dedupe); return eid; end $$;
create or replace function app.activity(p_org uuid,p_actor uuid,p_entity_type text,p_entity_id uuid,p_event text,p_summary text,p_meta jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public,app as $$ begin
 insert into activities(organization_id,entity_type,entity_id,actor_id,event_type,summary,metadata) values(p_org,p_entity_type,p_entity_id,p_actor,p_event,p_summary,coalesce(p_meta,'{}'::jsonb)); end $$;
create or replace function app.audit(p_org uuid,p_actor uuid,p_action text,p_entity_type text,p_entity_id uuid,p_before jsonb,p_after jsonb) returns void language plpgsql security definer set search_path=public,app as $$ begin
 insert into audit_logs(organization_id,actor_id,action,entity_type,entity_id,before_json,after_json) values(p_org,p_actor,p_action,p_entity_type,p_entity_id,p_before,p_after); end $$;

create or replace function app.create_organization(p_name text,p_slug text,p_country text,p_currency text,p_timezone text,p_locale text default 'en',p_template_version uuid default null)
returns uuid language plpgsql security definer set search_path=public,app as $$
declare u uuid:=auth.uid(); org uuid:=gen_random_uuid(); role_row record; owner_role uuid; plan uuid; period_start timestamptz:=now(); period_end timestamptz:=now()+interval '1 month';
begin
 if u is null then raise exception 'ARV-AUTH-1001 authentication required'; end if;
 if not exists(select 1 from currency_definitions where currency_code=p_currency and active) then raise exception 'invalid currency'; end if;
 insert into organizations(id,name,slug,country_code,currency_code,timezone,locale,industry_template_version_id) values(org,trim(p_name),lower(trim(p_slug)),upper(p_country),upper(p_currency),p_timezone,p_locale,p_template_version);
 insert into organization_settings(organization_id,localization,workflow) values(org,jsonb_build_object('country_code',upper(p_country),'currency_code',upper(p_currency),'timezone',p_timezone,'locale',p_locale),'{}'::jsonb);
 insert into organization_modules(organization_id,module_key,enabled) values(org,'ASSETS',true),(org,'RECURRING',true);
 for role_row in select * from system_role_templates where version=1 loop
   insert into roles(organization_id,name,system_key,is_system_role) values(org,role_row.name,role_row.system_key,true) returning id into owner_role;
   insert into role_permissions(organization_id,role_id,permission_key,allowed) select org,owner_role,value,true from jsonb_array_elements_text(role_row.permissions);
   if role_row.system_key='OWNER' then
     insert into organization_members(organization_id,user_id,role_id,status,joined_at) values(org,u,owner_role,'ACTIVE',now());
   end if;
 end loop;
 select id into plan from plan_versions where plan_key='FREE' and active order by version desc limit 1;
 insert into subscriptions(organization_id,plan_version_id,status,period_start,period_end) values(org,plan,'ACTIVE',period_start,period_end);
 insert into usage_counters(organization_id,period_start,period_end,metric_key,value,reserved) values(org,period_start,period_end,'jobs_created',0,0),(org,period_start,period_end,'storage_bytes',0,0),(org,period_start,period_end,'team_members',1,0);
 insert into tax_profiles(organization_id,name,rate_ppm,behavior,is_default) values(org,'No tax',0,'EXEMPT',true);
 return org;
end $$;

create or replace function app.accept_invitation(p_invitation uuid) returns uuid language plpgsql security definer set search_path=public,app as $$
declare u uuid:=auth.uid(); em text; inv organization_invitations%rowtype; mid uuid;
begin
 if u is null then raise exception 'authentication required'; end if;
 select email into em from auth.users where id=u;
 select * into inv from organization_invitations where id=p_invitation for update;
 if not found or inv.status<>'PENDING' or inv.expires_at<=now() or lower(em)<>inv.normalized_email then raise exception 'ARV-TENANT-1002 invitation invalid'; end if;
 insert into organization_members(organization_id,user_id,role_id,status,invited_at,joined_at) values(inv.organization_id,u,inv.intended_role_id,'ACTIVE',inv.invited_at,now())
 on conflict(organization_id,user_id) do update set role_id=excluded.role_id,status='ACTIVE',joined_at=now() returning id into mid;
 update organization_invitations set status='ACCEPTED',accepted_at=now() where id=inv.id;
 return mid;
end $$;

create or replace function app.effective_entitlement(p_org uuid,p_key text) returns jsonb language sql stable security definer set search_path=public,app as $$
 with s as (select * from subscriptions where organization_id=p_org and status in ('TRIALING','ACTIVE','PAST_DUE') order by created_at desc limit 1),
 base as (select pe.value_json from plan_entitlements pe join s on s.plan_version_id=pe.plan_version_id where pe.feature_key=p_key),
 ov as (select value_json from organization_entitlement_overrides where organization_id=p_org and feature_key=p_key and valid_from<=now() and (valid_to is null or valid_to>now()) order by valid_from desc limit 1)
 select coalesce((select value_json from ov),(select value_json from base),'null'::jsonb)
$$;
create or replace function app.limit_value(p_org uuid,p_key text) returns bigint language sql stable security definer set search_path=public,app as $$ select (app.effective_entitlement(p_org,p_key)#>>'{}')::bigint $$;
create or replace function app.feature_enabled(p_org uuid,p_key text) returns boolean language sql stable security definer set search_path=public,app as $$ select coalesce((app.effective_entitlement(p_org,p_key)#>>'{}')::boolean,false) $$;

create or replace function app.current_usage(p_org uuid,p_metric text) returns bigint language sql stable security definer set search_path=public,app as $$
 select coalesce(value+reserved,0) from usage_counters where organization_id=p_org and metric_key=p_metric and period_start<=now() and period_end>now() order by period_start desc limit 1
$$;
create or replace function app.apply_usage(p_org uuid,p_metric text,p_delta bigint,p_source_type text,p_source_id text,p_key text) returns bigint language plpgsql security definer set search_path=public,app as $$
declare c usage_counters%rowtype; begin
 select * into c from usage_counters where organization_id=p_org and metric_key=p_metric and period_start<=now() and period_end>now() for update;
 if not found then raise exception 'usage period not found'; end if;
 if exists(select 1 from usage_ledger where organization_id=p_org and metric_key=p_metric and idempotency_key=p_key and source_type=p_source_type and source_id=p_source_id) then return c.value; end if;
 insert into usage_ledger(organization_id,period_start,period_end,metric_key,delta,source_type,source_id,idempotency_key) values(p_org,c.period_start,c.period_end,p_metric,p_delta,p_source_type,p_source_id,p_key);
 update usage_counters set value=value+p_delta,version=version+1,updated_at=now() where id=c.id returning value into c.value; if c.value<0 then raise exception 'usage cannot be negative'; end if; return c.value;
end $$;

create or replace function app.next_document_number(p_org uuid,p_type text) returns text language plpgsql security definer set search_path=public,app as $$
declare tz text; year_key text; v bigint; prefix text; begin
 select timezone into tz from organizations where id=p_org;
 year_key:=to_char(now() at time zone tz,'YYYY'); prefix:=case p_type when 'JOB' then 'JOB' when 'QUOTE' then 'QTE' when 'INVOICE' then 'INV' else 'DOC' end;
 insert into document_sequences(organization_id,document_type,period_key,next_value) values(p_org,p_type,year_key,2)
 on conflict(organization_id,document_type,period_key) do update set next_value=document_sequences.next_value+1 returning next_value-1 into v;
 return prefix||'-'||year_key||'-'||lpad(v::text,6,'0');
end $$;

-- Customer create with duplicate override contract.
create or replace function app.create_customer(p_org uuid,p_type text,p_name text,p_raw_phone text,p_normalized_phone text,p_whatsapp text,p_alt text,p_email text,p_source text,p_assigned_sales uuid,p_override_customer uuid,p_override_reason text,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'customer.create'); existing uuid; cid uuid; h text; replay jsonb; begin
 h:=encode(digest(jsonb_build_array(p_type,p_name,p_raw_phone,p_normalized_phone,p_whatsapp,p_alt,p_email,p_source,p_assigned_sales,p_override_customer,p_override_reason)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'customer.create',p_key,h); if replay is not null then return replay; end if;
 if p_normalized_phone is not null then select id into existing from customers where organization_id=p_org and normalized_phone=p_normalized_phone and archived_at is null order by created_at limit 1; end if;
 if existing is not null and p_override_customer is null then return jsonb_build_object('duplicate',true,'customer_id',existing); end if;
 if existing is not null then
   if not app.has_permission(p_org,'customer.duplicate_override') then raise exception 'ARV-PERM-1001 duplicate override permission required'; end if;
   if p_override_customer<>existing or coalesce(trim(p_override_reason),'')='' then raise exception 'duplicate override requires candidate and reason'; end if;
 end if;
 insert into customers(organization_id,type,name,raw_phone,normalized_phone,whatsapp_phone,alternate_phone,email,source,assigned_sales_id,duplicate_of_customer_id,duplicate_override_reason,duplicate_override_by,created_by)
 values(p_org,p_type,trim(p_name),p_raw_phone,p_normalized_phone,p_whatsapp,p_alt,p_email,p_source,p_assigned_sales,case when existing is not null then existing end,case when existing is not null then p_override_reason end,case when existing is not null then actor end,actor) returning id into cid;
 perform app.activity(p_org,actor,'CUSTOMER',cid,'customer.created','Customer created'); perform app.emit_event(p_org,actor,'customer.created','CUSTOMER',cid,'{}'::jsonb,p_key);
 if existing is not null then perform app.audit(p_org,actor,'customer.duplicate_override','CUSTOMER',cid,null,jsonb_build_object('duplicate_of',existing,'reason',p_override_reason)); end if;
 replay:=jsonb_build_object('duplicate',false,'customer_id',cid); perform app.idempotency_commit(p_org,actor,'customer.create',p_key,h,replay); return replay;
end $$;

create or replace function app.transition_lead(p_org uuid,p_lead uuid,p_to text,p_reason text,p_expected_version integer,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; l leads%rowtype; ok boolean:=false; h text; replay jsonb; begin
 actor:=app.require_permission(p_org,case when p_to='CONTACTED' and (select status from leads where organization_id=p_org and id=p_lead)='LOST' then 'lead.reopen' else 'lead.update' end);
 h:=encode(digest(jsonb_build_array(p_lead,p_to,p_reason,p_expected_version)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'lead.transition',p_key,h); if replay is not null then return replay; end if;
 select * into l from leads where organization_id=p_org and id=p_lead and archived_at is null for update; if not found then raise exception 'ARV-STATE-1001 lead not found'; end if; if l.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale lead version'; end if;
 ok:=case l.status when 'NEW' then p_to in ('CONTACTED','LOST') when 'CONTACTED' then p_to in ('QUALIFIED','LOST') when 'QUALIFIED' then p_to in ('QUOTE','LOST') when 'QUOTE' then p_to in ('NEGOTIATION','WON','LOST') when 'NEGOTIATION' then p_to in ('WON','LOST') when 'LOST' then p_to='CONTACTED' else false end;
 if not ok then raise exception 'ARV-STATE-1001 transition % -> % denied',l.status,p_to; end if;
 if p_to='LOST' and coalesce(trim(p_reason),'')='' then raise exception 'lost reason required'; end if; if l.status='LOST' and p_to='CONTACTED' and coalesce(trim(p_reason),'')='' then raise exception 'reopen reason required'; end if;
 update leads set status=p_to,won_at=case when p_to='WON' then now() else won_at end,lost_at=case when p_to='LOST' then now() when l.status='LOST' and p_to='CONTACTED' then null else lost_at end,lost_reason=case when p_to='LOST' then p_reason when l.status='LOST' and p_to='CONTACTED' then null else lost_reason end where organization_id=p_org and id=p_lead;
 insert into lead_status_history(organization_id,lead_id,from_status,to_status,changed_by,reason,idempotency_key) values(p_org,p_lead,l.status,p_to,actor,p_reason,p_key);
 perform app.activity(p_org,actor,'LEAD',p_lead,'lead.status_changed',l.status||' → '||p_to,jsonb_build_object('reason',p_reason)); perform app.emit_event(p_org,actor,case when p_to='WON' then 'lead.won' else 'lead.status_changed' end,'LEAD',p_lead,jsonb_build_object('from',l.status,'to',p_to),p_key);
 replay:=jsonb_build_object('lead_id',p_lead,'from',l.status,'to',p_to); perform app.idempotency_commit(p_org,actor,'lead.transition',p_key,h,replay); return replay;
end $$;

-- Exact money recomputation. PostgreSQL round(numeric) is half-away-from-zero.
create or replace function app.recompute_quote(p_org uuid,p_quote uuid) returns void language plpgsql security definer set search_path=public,app as $$
declare docdisc bigint; eligible bigint; allocated bigint; begin
 select document_discount_minor into docdisc from quotes where organization_id=p_org and id=p_quote;
 update quote_items set gross_minor=round(quantity*unit_price_minor)::bigint where organization_id=p_org and quote_id=p_quote;
 if exists(select 1 from quote_items where organization_id=p_org and quote_id=p_quote and line_discount_minor>gross_minor) then raise exception 'ARV-MONEY-3001 line discount exceeds gross'; end if;
 select coalesce(sum(gross_minor-line_discount_minor),0)::bigint into eligible from quote_items where organization_id=p_org and quote_id=p_quote;
 if docdisc>eligible then raise exception 'ARV-MONEY-3001 document discount exceeds eligible subtotal'; end if;
 with b as (
   select id,sort_order,case when eligible=0 then 0 else floor(docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible)::bigint end f,
     case when eligible=0 then 0::numeric else (docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible)-floor(docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible) end r
   from quote_items where organization_id=p_org and quote_id=p_quote
 ), s as (select coalesce(sum(f),0)::bigint sf from b), ranked as (select b.*,row_number() over(order by r desc,sort_order) rn,(select docdisc-sf from s) rem from b)
 update quote_items qi set allocated_document_discount_minor=ranked.f+case when ranked.rn<=ranked.rem then 1 else 0 end from ranked where qi.id=ranked.id;
 update quote_items set discount_minor=line_discount_minor+allocated_document_discount_minor,
   net_minor=case when tax_behavior='INCLUSIVE' and tax_rate_ppm>0 then round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*1000000/(1000000+tax_rate_ppm))::bigint else gross_minor-line_discount_minor-allocated_document_discount_minor end,
   tax_minor=case when tax_behavior='EXCLUSIVE' then round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*tax_rate_ppm/1000000)::bigint when tax_behavior='INCLUSIVE' and tax_rate_ppm>0 then (gross_minor-line_discount_minor-allocated_document_discount_minor)-round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*1000000/(1000000+tax_rate_ppm))::bigint else 0 end
 where organization_id=p_org and quote_id=p_quote;
 update quote_items set total_minor=case when tax_behavior='EXCLUSIVE' then net_minor+tax_minor else gross_minor-discount_minor end where organization_id=p_org and quote_id=p_quote;
 update quotes q set subtotal_minor=x.subtotal,discount_minor=x.discount,tax_minor=x.tax,total_minor=x.total,calculator_version='1.0.1'
 from (select coalesce(sum(gross_minor),0)::bigint subtotal,coalesce(sum(discount_minor),0)::bigint discount,coalesce(sum(tax_minor),0)::bigint tax,coalesce(sum(total_minor),0)::bigint total from quote_items where organization_id=p_org and quote_id=p_quote) x
 where q.organization_id=p_org and q.id=p_quote;
end $$;

create or replace function app.create_quote(p_org uuid,p_customer uuid,p_lead uuid,p_currency text,p_expires timestamptz,p_terms text,p_document_discount bigint,p_items jsonb,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'quote.create'); qid uuid:=gen_random_uuid(); item jsonb; h text; replay jsonb; begin
 h:=encode(digest(jsonb_build_array(p_customer,p_lead,p_currency,p_expires,p_terms,p_document_discount,p_items)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'quote.create',p_key,h); if replay is not null then return (replay->>'quote_id')::uuid; end if;
 insert into quotes(id,organization_id,customer_id,lead_id,owner_member_id,currency_code,expires_at,terms_snapshot,document_discount_minor) values(qid,p_org,p_customer,p_lead,actor,p_currency,p_expires,p_terms,coalesce(p_document_discount,0));
 for item in select * from jsonb_array_elements(p_items) loop
   insert into quote_items(organization_id,quote_id,name_snapshot,description_snapshot,unit_snapshot,quantity,unit_price_minor,line_discount_minor,tax_rate_ppm,tax_behavior,sort_order)
   values(p_org,qid,item->>'name',item->>'description',item->>'unit',coalesce((item->>'quantity')::numeric,1),coalesce((item->>'unit_price_minor')::bigint,0),coalesce((item->>'line_discount_minor')::bigint,0),coalesce((item->>'tax_rate_ppm')::int,0),coalesce(item->>'tax_behavior','EXEMPT'),coalesce((item->>'sort_order')::int,1));
 end loop; perform app.recompute_quote(p_org,qid); perform app.activity(p_org,actor,'QUOTE',qid,'quote.created','Quote draft created'); perform app.idempotency_commit(p_org,actor,'quote.create',p_key,h,jsonb_build_object('quote_id',qid)); return qid;
end $$;

create or replace function app.issue_quote(p_org uuid,p_quote uuid,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'quote.issue'); q quotes%rowtype; c customers%rowtype; o organizations%rowtype; exp int; num text; h text; replay jsonb; begin
 h:=encode(digest(jsonb_build_array(p_quote,p_expected_version)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'quote.issue',p_key,h); if replay is not null then return replay; end if;
 select * into q from quotes where organization_id=p_org and id=p_quote for update; if not found or q.status<>'DRAFT' or q.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 quote state/version conflict'; end if;
 if q.expires_at is null or q.expires_at<=now() or not exists(select 1 from quote_items where organization_id=p_org and quote_id=p_quote) then raise exception 'ARV-STATE-1001 quote requires future expiry and item'; end if;
 perform app.recompute_quote(p_org,p_quote); select * into q from quotes where organization_id=p_org and id=p_quote; select * into c from customers where organization_id=p_org and id=q.customer_id; select * into o from organizations where id=p_org; select minor_unit_exponent into exp from currency_definitions where currency_code=q.currency_code; num:=app.next_document_number(p_org,'QUOTE');
 update quotes set status='ISSUED',quote_number=num,currency_exponent=exp,issued_at=now(),customer_snapshot=jsonb_build_object('id',c.id,'name',c.name,'type',c.type,'phone',c.normalized_phone,'email',c.email),organization_snapshot=jsonb_build_object('name',o.name,'country_code',o.country_code,'timezone',o.timezone,'locale',o.locale),calculator_version='1.0.1' where organization_id=p_org and id=p_quote;
 insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,entity_version,idempotency_key) values(p_org,'QUOTE',p_quote,'DRAFT','ISSUED',actor,q.version,p_key);
 if q.lead_id is not null and exists(select 1 from leads where organization_id=p_org and id=q.lead_id and status='QUALIFIED') then
   update leads set status='QUOTE' where organization_id=p_org and id=q.lead_id; insert into lead_status_history(organization_id,lead_id,from_status,to_status,changed_by,idempotency_key) values(p_org,q.lead_id,'QUALIFIED','QUOTE',actor,p_key||':lead'); perform app.emit_event(p_org,actor,'lead.status_changed','LEAD',q.lead_id,jsonb_build_object('from','QUALIFIED','to','QUOTE'),p_key||':lead');
 end if;
 perform app.activity(p_org,actor,'QUOTE',p_quote,'quote.issued','Quote issued'); perform app.emit_event(p_org,actor,'quote.issued','QUOTE',p_quote,'{}',p_key); replay:=jsonb_build_object('quote_id',p_quote,'quote_number',num,'status','ISSUED'); perform app.idempotency_commit(p_org,actor,'quote.issue',p_key,h,replay); return replay;
end $$;

create or replace function app.update_quote_status(p_org uuid,p_quote uuid,p_to text,p_reason text,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; q quotes%rowtype; h text; replay jsonb; begin
 actor:=app.require_permission(p_org,case when p_to='ACCEPTED' then 'quote.accept' else 'quote.update_status' end); h:=encode(digest(jsonb_build_array(p_quote,p_to,p_reason,p_expected_version)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'quote.status',p_key,h); if replay is not null then return replay; end if;
 select * into q from quotes where organization_id=p_org and id=p_quote for update; if q.status<>'ISSUED' or q.version<>p_expected_version or p_to not in ('ACCEPTED','REJECTED','EXPIRED') then raise exception 'ARV-STATE-1001 quote transition denied'; end if;
 if p_to='ACCEPTED' and q.expires_at<=now() and coalesce(trim(p_reason),'')='' then raise exception 'expired acceptance override reason required'; end if; if p_to='EXPIRED' and q.expires_at>=now() then raise exception 'quote not expired'; end if;
 update quotes set status=p_to,accepted_at=case when p_to='ACCEPTED' then now() else accepted_at end where organization_id=p_org and id=p_quote;
 insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,reason,entity_version,idempotency_key) values(p_org,'QUOTE',p_quote,'ISSUED',p_to,actor,p_reason,q.version,p_key);
 perform app.activity(p_org,actor,'QUOTE',p_quote,'quote.'||lower(p_to),'Quote '||lower(p_to)); perform app.emit_event(p_org,actor,'quote.'||lower(p_to),'QUOTE',p_quote,'{}',p_key); replay:=jsonb_build_object('quote_id',p_quote,'status',p_to); perform app.idempotency_commit(p_org,actor,'quote.status',p_key,h,replay); return replay;
end $$;

create or replace function app.consume_job_limit(p_org uuid,p_key text,p_source text) returns void language plpgsql security definer set search_path=public,app as $$ begin
  -- Jobs are unlimited on FREE, PRO and ULTRA. Keep append-only usage accounting for analytics/observability,
  -- but never gate Job creation by a plan quota. Other cost-bearing resources remain entitlement-governed.
  perform app.apply_usage(p_org,'jobs_created',1,'JOB',p_source,p_key);
end $$;

create or replace function app.create_job(p_org uuid,p_customer uuid,p_lead uuid,p_title text,p_description text,p_priority text,p_address uuid,p_currency text,p_estimated bigint,p_items jsonb,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'job.create'); jid uuid:=gen_random_uuid(); item jsonb; h text; replay jsonb; begin
 h:=encode(digest(jsonb_build_array(p_customer,p_lead,p_title,p_description,p_priority,p_address,p_currency,p_estimated,p_items)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'job.create',p_key,h); if replay is not null then return (replay->>'job_id')::uuid; end if;
 perform app.consume_job_limit(p_org,p_key,jid::text); insert into jobs(id,organization_id,customer_id,lead_id,title,description,priority,primary_address_id,currency_code,estimated_amount_minor) values(jid,p_org,p_customer,p_lead,p_title,p_description,coalesce(p_priority,'NORMAL'),p_address,p_currency,p_estimated);
 for item in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop insert into job_items(organization_id,job_id,name_snapshot,quantity,unit_price_minor,notes) values(p_org,jid,item->>'name',coalesce((item->>'quantity')::numeric,1),(item->>'unit_price_minor')::bigint,item->>'notes'); end loop;
 perform app.activity(p_org,actor,'JOB',jid,'job.created','Job draft created'); perform app.emit_event(p_org,actor,'job.created','JOB',jid,'{}',p_key); perform app.idempotency_commit(p_org,actor,'job.create',p_key,h,jsonb_build_object('job_id',jid)); return jid;
end $$;

create or replace function app.convert_quote_to_job(p_org uuid,p_quote uuid,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'job.create'); q quotes%rowtype; jid uuid; h text; replay jsonb; item quote_items%rowtype; num text; begin
 h:=encode(digest(jsonb_build_array(p_quote)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'quote.convert_job',p_key,h); if replay is not null then return (replay->>'job_id')::uuid; end if;
 select * into q from quotes where organization_id=p_org and id=p_quote for update; if not found or q.status<>'ACCEPTED' then raise exception 'ARV-STATE-1001 accepted Quote required'; end if; select id into jid from jobs where organization_id=p_org and quote_id=p_quote; if jid is not null then perform app.idempotency_commit(p_org,actor,'quote.convert_job',p_key,h,jsonb_build_object('job_id',jid)); return jid; end if;
 jid:=gen_random_uuid(); perform app.consume_job_limit(p_org,p_key,jid::text); num:=app.next_document_number(p_org,'JOB'); insert into jobs(id,organization_id,job_number,customer_id,lead_id,quote_id,title,description,status,priority,currency_code,estimated_amount_minor) values(jid,p_org,num,q.customer_id,q.lead_id,q.id,'Job from '||coalesce(q.quote_number,'Quote'),null,'CONFIRMED','NORMAL',q.currency_code,q.total_minor);
 for item in select * from quote_items where organization_id=p_org and quote_id=p_quote order by sort_order loop insert into job_items(organization_id,job_id,service_catalog_id,name_snapshot,quantity,unit_price_minor,notes) values(p_org,jid,item.service_catalog_id,item.name_snapshot,item.quantity,item.unit_price_minor,item.description_snapshot); end loop;
 if q.lead_id is not null then update leads set status='WON',won_at=now() where organization_id=p_org and id=q.lead_id and status in ('QUOTE','NEGOTIATION'); if found then insert into lead_status_history(organization_id,lead_id,from_status,to_status,changed_by,idempotency_key) select p_org,q.lead_id,status,'WON',actor,p_key||':lead' from leads where organization_id=p_org and id=q.lead_id; end if; end if;
 perform app.activity(p_org,actor,'JOB',jid,'job.created','Job created from accepted Quote',jsonb_build_object('quote_id',p_quote)); perform app.emit_event(p_org,actor,'job.created','JOB',jid,jsonb_build_object('quote_id',p_quote),p_key); if q.lead_id is not null then perform app.emit_event(p_org,actor,'lead.won','LEAD',q.lead_id,jsonb_build_object('job_id',jid),p_key||':lead'); end if; perform app.idempotency_commit(p_org,actor,'quote.convert_job',p_key,h,jsonb_build_object('job_id',jid)); return jid;
end $$;

create or replace function app.confirm_job(p_org uuid,p_job uuid,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'job.confirm'); j jobs%rowtype; num text; begin select * into j from jobs where organization_id=p_org and id=p_job for update; if j.status<>'DRAFT' or j.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 job state/version conflict'; end if; num:=coalesce(j.job_number,app.next_document_number(p_org,'JOB')); update jobs set status='CONFIRMED',job_number=num where organization_id=p_org and id=p_job; insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,entity_version,idempotency_key) values(p_org,'JOB',p_job,'DRAFT','CONFIRMED',actor,j.version,p_key); perform app.activity(p_org,actor,'JOB',p_job,'job.confirmed','Job confirmed'); perform app.emit_event(p_org,actor,'job.confirmed','JOB',p_job,'{}',p_key); return jsonb_build_object('job_id',p_job,'job_number',num,'status','CONFIRMED'); end $$;

create or replace function app.schedule_visit(p_org uuid,p_job uuid,p_visit uuid,p_start timestamptz,p_end timestamptz,p_timezone text,p_address jsonb,p_assign_members uuid[],p_override boolean,p_reason text,p_expected_version int,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,case when p_visit is null then 'visit.schedule' else 'visit.reschedule' end); vid uuid:=coalesce(p_visit,gen_random_uuid()); v visits%rowtype; conflict record; member uuid; j jobs%rowtype; begin
 if p_end<=p_start then raise exception 'invalid visit interval'; end if; select * into j from jobs where organization_id=p_org and id=p_job for update; if not found or j.status in ('COMPLETED','CANCELLED') then raise exception 'ARV-STATE-1001 terminal job cannot schedule'; end if;
 if p_visit is not null then select * into v from visits where organization_id=p_org and id=p_visit for update; if not found or v.job_id<>p_job or v.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale visit'; end if; end if;
 for member in select unnest(coalesce(p_assign_members,array[]::uuid[])) loop
   if not exists(select 1 from organization_members where organization_id=p_org and id=member and status='ACTIVE') then raise exception 'ARV-TENANT-1003 invalid assignee'; end if;
   if exists(select 1 from member_leave where organization_id=p_org and member_id=member and status='APPROVED' and tstzrange(starts_at,ends_at,'[)') && tstzrange(p_start,p_end,'[)')) then raise exception 'ARV-VISIT-4001 assignee on leave'; end if;
   select vv.id into conflict from visits vv join visit_assignments va on va.organization_id=vv.organization_id and va.visit_id=vv.id and va.removed_at is null where vv.organization_id=p_org and va.member_id=member and vv.id<>vid and vv.status not in ('CANCELLED','NO_SHOW') and tstzrange(vv.scheduled_start,vv.scheduled_end,'[)') && tstzrange(p_start,p_end,'[)') limit 1;
   if conflict.id is not null and not p_override then raise exception 'ARV-VISIT-4001 schedule conflict'; end if;
   if conflict.id is not null then if not app.has_permission(p_org,'schedule.override') or coalesce(trim(p_reason),'')='' then raise exception 'ARV-PERM-1001 schedule override requires permission and reason'; end if; end if;
 end loop;
 if p_visit is null then insert into visits(id,organization_id,job_id,scheduled_start,scheduled_end,scheduled_local_start,scheduled_local_end,timezone,address_snapshot) values(vid,p_org,p_job,p_start,p_end,p_start at time zone p_timezone,p_end at time zone p_timezone,p_timezone,coalesce(p_address,'{}')); else update visits set scheduled_start=p_start,scheduled_end=p_end,scheduled_local_start=p_start at time zone p_timezone,scheduled_local_end=p_end at time zone p_timezone,timezone=p_timezone,address_snapshot=coalesce(p_address,address_snapshot) where organization_id=p_org and id=vid; end if;
 update visit_assignments set removed_at=now() where organization_id=p_org and visit_id=vid and removed_at is null and not(member_id=any(coalesce(p_assign_members,array[]::uuid[]))); for member in select unnest(coalesce(p_assign_members,array[]::uuid[])) loop insert into visit_assignments(organization_id,visit_id,member_id) values(p_org,vid,member) on conflict do nothing; end loop;
 if p_override then for member in select unnest(coalesce(p_assign_members,array[]::uuid[])) loop for conflict in select vv.id from visits vv join visit_assignments va on va.organization_id=vv.organization_id and va.visit_id=vv.id and va.removed_at is null where vv.organization_id=p_org and va.member_id=member and vv.id<>vid and vv.status not in ('CANCELLED','NO_SHOW') and tstzrange(vv.scheduled_start,vv.scheduled_end,'[)') && tstzrange(p_start,p_end,'[)') loop insert into schedule_conflict_overrides(organization_id,visit_id,conflicting_visit_id,visit_version,actor_member_id,reason) values(p_org,vid,conflict.id,coalesce(v.version,1),actor,p_reason) on conflict do nothing; end loop; end loop; end if;
 update jobs set scheduled_start=(select min(scheduled_start) from visits where organization_id=p_org and job_id=p_job and status not in ('CANCELLED','NO_SHOW')),scheduled_end=(select max(scheduled_end) from visits where organization_id=p_org and job_id=p_job and status not in ('CANCELLED','NO_SHOW')),status=case when status='CONFIRMED' then 'SCHEDULED' else status end where organization_id=p_org and id=p_job;
 perform app.activity(p_org,actor,'VISIT',vid,case when p_visit is null then 'visit.scheduled' else 'visit.rescheduled' end,'Visit scheduled'); perform app.emit_event(p_org,actor,'visit.scheduled','VISIT',vid,jsonb_build_object('job_id',p_job),p_key); return vid;
end $$;

create or replace function app.visit_action(p_org uuid,p_visit uuid,p_action text,p_expected_version int,p_reason text,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; v visits%rowtype; j jobs%rowtype; to_state text; perm text; nowts timestamptz:=now(); begin
 perm:=case p_action when 'DEPART' then 'visit.depart_assigned' when 'ARRIVE' then 'visit.arrive_assigned' when 'START' then 'visit.start_assigned' when 'FINISH' then 'visit.finish_assigned' when 'CANCEL' then 'visit.cancel' when 'NO_SHOW' then 'visit.no_show' else null end; if perm is null then raise exception 'unknown visit action'; end if; actor:=app.require_permission(p_org,perm);
 select * into v from visits where organization_id=p_org and id=p_visit for update; if not found or v.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale visit'; end if;
 if p_action in ('DEPART','ARRIVE','START','FINISH') and not exists(select 1 from visit_assignments where organization_id=p_org and visit_id=p_visit and member_id=actor and removed_at is null) and app.current_role_key(p_org)='WORKER' then raise exception 'ARV-PERM-1001 active assignment required'; end if;
 to_state:=case p_action when 'DEPART' then 'EN_ROUTE' when 'ARRIVE' then 'ARRIVED' when 'START' then 'IN_PROGRESS' when 'FINISH' then 'COMPLETED' when 'CANCEL' then 'CANCELLED' when 'NO_SHOW' then 'NO_SHOW' end;
 if not ((v.status='SCHEDULED' and to_state in ('EN_ROUTE','CANCELLED','NO_SHOW')) or (v.status='EN_ROUTE' and to_state in ('ARRIVED','CANCELLED')) or (v.status='ARRIVED' and to_state in ('IN_PROGRESS','CANCELLED')) or (v.status='IN_PROGRESS' and to_state='COMPLETED')) then raise exception 'ARV-STATE-1001 visit transition denied'; end if;
 if to_state='COMPLETED' then
   if exists(select 1 from job_checklists jc where jc.organization_id=p_org and jc.visit_id=p_visit and jc.required and exists(select 1 from jsonb_array_elements(jc.template_snapshot->'items') it where coalesce((it->>'required')::boolean,false) and not exists(select 1 from checklist_responses cr where cr.organization_id=p_org and cr.job_checklist_id=jc.id and cr.template_item_key=it->>'item_key'))) then raise exception 'ARV-VISIT-4001 required checklist incomplete'; end if;
   if exists(select 1 from job_checklists jc, jsonb_array_elements(jc.template_snapshot->'items') it where jc.organization_id=p_org and jc.visit_id=p_visit and coalesce((it->>'required')::boolean,false) and it->>'input_type'='PHOTO' and not exists(select 1 from media m where m.organization_id=p_org and m.parent_type='VISIT' and m.parent_id=p_visit and m.upload_status='UPLOADED' and m.category=coalesce(it->>'category','EVIDENCE'))) then raise exception 'ARV-VISIT-4001 required media not uploaded'; end if;
 end if;
 update visits set status=to_state,actual_departed_at=case when to_state='EN_ROUTE' then nowts else actual_departed_at end,actual_arrived_at=case when to_state='ARRIVED' then nowts else actual_arrived_at end,actual_started_at=case when to_state='IN_PROGRESS' then nowts else actual_started_at end,actual_completed_at=case when to_state='COMPLETED' then nowts else actual_completed_at end where organization_id=p_org and id=p_visit;
 select * into j from jobs where organization_id=p_org and id=v.job_id for update;
 if to_state='IN_PROGRESS' and j.status='SCHEDULED' then update jobs set status='IN_PROGRESS' where organization_id=p_org and id=j.id; perform app.emit_event(p_org,actor,'job.started','JOB',j.id,jsonb_build_object('visit_id',p_visit),p_key||':job'); end if;
 insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,reason,entity_version,idempotency_key) values(p_org,'VISIT',p_visit,v.status,to_state,actor,p_reason,v.version,p_key);
 perform app.activity(p_org,actor,'VISIT',p_visit,'visit.'||lower(to_state),'Visit '||lower(to_state)); perform app.emit_event(p_org,actor,'visit.'||case to_state when 'EN_ROUTE' then 'departed' when 'IN_PROGRESS' then 'started' else lower(to_state) end,'VISIT',p_visit,'{}',p_key); return jsonb_build_object('visit_id',p_visit,'status',to_state);
end $$;

create or replace function app.complete_job(p_org uuid,p_job uuid,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'job.complete'); j jobs%rowtype; begin select * into j from jobs where organization_id=p_org and id=p_job for update; if not found or j.version<>p_expected_version or j.status<>'IN_PROGRESS' then raise exception 'ARV-CONFLICT-1001 job state/version conflict'; end if; if exists(select 1 from visits where organization_id=p_org and job_id=p_job and status not in ('COMPLETED','CANCELLED','NO_SHOW')) then raise exception 'ARV-JOB-4001 all required Visits must be terminal/completed'; end if; if exists(select 1 from job_checklists where organization_id=p_org and job_id=p_job and required and status<>'COMPLETE') then raise exception 'ARV-JOB-4001 required checklist incomplete'; end if; update jobs set status='COMPLETED',completed_at=now() where organization_id=p_org and id=p_job; insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,entity_version,idempotency_key) values(p_org,'JOB',p_job,'IN_PROGRESS','COMPLETED',actor,j.version,p_key); perform app.activity(p_org,actor,'JOB',p_job,'job.completed','Job completed'); perform app.emit_event(p_org,actor,'job.completed','JOB',p_job,'{}',p_key); return jsonb_build_object('job_id',p_job,'status','COMPLETED'); end $$;

create or replace function app.recompute_invoice(p_org uuid,p_invoice uuid) returns void language plpgsql security definer set search_path=public,app as $$
declare docdisc bigint; eligible bigint; begin select document_discount_minor into docdisc from invoices where organization_id=p_org and id=p_invoice; update invoice_items set gross_minor=round(quantity*unit_price_minor)::bigint where organization_id=p_org and invoice_id=p_invoice; if exists(select 1 from invoice_items where organization_id=p_org and invoice_id=p_invoice and line_discount_minor>gross_minor) then raise exception 'ARV-MONEY-3001 line discount exceeds gross'; end if; select coalesce(sum(gross_minor-line_discount_minor),0)::bigint into eligible from invoice_items where organization_id=p_org and invoice_id=p_invoice; if docdisc>eligible then raise exception 'ARV-MONEY-3001 document discount exceeds eligible subtotal'; end if;
 with b as (select id,sort_order,case when eligible=0 then 0 else floor(docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible)::bigint end f,case when eligible=0 then 0::numeric else docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible-floor(docdisc::numeric*(gross_minor-line_discount_minor)::numeric/eligible) end r from invoice_items where organization_id=p_org and invoice_id=p_invoice),s as(select coalesce(sum(f),0)::bigint sf from b),ranked as(select b.*,row_number() over(order by r desc,sort_order) rn,(select docdisc-sf from s) rem from b) update invoice_items ii set allocated_document_discount_minor=ranked.f+case when ranked.rn<=ranked.rem then 1 else 0 end from ranked where ii.id=ranked.id;
 update invoice_items set discount_minor=line_discount_minor+allocated_document_discount_minor,net_minor=case when tax_behavior='INCLUSIVE' and tax_rate_ppm>0 then round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*1000000/(1000000+tax_rate_ppm))::bigint else gross_minor-line_discount_minor-allocated_document_discount_minor end,tax_minor=case when tax_behavior='EXCLUSIVE' then round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*tax_rate_ppm/1000000)::bigint when tax_behavior='INCLUSIVE' and tax_rate_ppm>0 then (gross_minor-line_discount_minor-allocated_document_discount_minor)-round((gross_minor-line_discount_minor-allocated_document_discount_minor)::numeric*1000000/(1000000+tax_rate_ppm))::bigint else 0 end where organization_id=p_org and invoice_id=p_invoice;
 update invoice_items set total_minor=case when tax_behavior='EXCLUSIVE' then net_minor+tax_minor else gross_minor-discount_minor end where organization_id=p_org and invoice_id=p_invoice;
 update invoices q set subtotal_minor=x.subtotal,discount_minor=x.discount,tax_minor=x.tax,total_minor=x.total,outstanding_minor=x.total-paid_minor,calculator_version='1.0.1' from(select coalesce(sum(gross_minor),0)::bigint subtotal,coalesce(sum(discount_minor),0)::bigint discount,coalesce(sum(tax_minor),0)::bigint tax,coalesce(sum(total_minor),0)::bigint total from invoice_items where organization_id=p_org and invoice_id=p_invoice)x where q.organization_id=p_org and q.id=p_invoice;
end $$;

create or replace function app.create_invoice(p_org uuid,p_customer uuid,p_job uuid,p_quote uuid,p_currency text,p_due timestamptz,p_terms text,p_document_discount bigint,p_items jsonb,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'invoice.create'); iid uuid:=gen_random_uuid(); item jsonb; h text; replay jsonb; begin h:=encode(digest(jsonb_build_array(p_customer,p_job,p_quote,p_currency,p_due,p_terms,p_document_discount,p_items)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'invoice.create',p_key,h); if replay is not null then return (replay->>'invoice_id')::uuid; end if; insert into invoices(id,organization_id,customer_id,job_id,quote_id,currency_code,due_at,terms_snapshot,document_discount_minor) values(iid,p_org,p_customer,p_job,p_quote,p_currency,p_due,p_terms,coalesce(p_document_discount,0)); for item in select * from jsonb_array_elements(p_items) loop insert into invoice_items(organization_id,invoice_id,name_snapshot,description_snapshot,quantity,unit_snapshot,unit_price_minor,line_discount_minor,tax_rate_ppm,tax_behavior,sort_order) values(p_org,iid,item->>'name',item->>'description',coalesce((item->>'quantity')::numeric,1),item->>'unit',coalesce((item->>'unit_price_minor')::bigint,0),coalesce((item->>'line_discount_minor')::bigint,0),coalesce((item->>'tax_rate_ppm')::int,0),coalesce(item->>'tax_behavior','EXEMPT'),coalesce((item->>'sort_order')::int,1)); end loop; perform app.recompute_invoice(p_org,iid); perform app.activity(p_org,actor,'INVOICE',iid,'invoice.created','Invoice draft created'); perform app.idempotency_commit(p_org,actor,'invoice.create',p_key,h,jsonb_build_object('invoice_id',iid)); return iid; end $$;

create or replace function app.issue_invoice(p_org uuid,p_invoice uuid,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'invoice.issue'); i invoices%rowtype; c customers%rowtype; o organizations%rowtype; exp int; num text; begin select * into i from invoices where organization_id=p_org and id=p_invoice for update; if not found or i.status<>'DRAFT' or i.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 invoice state/version conflict'; end if; if i.due_at is null or not exists(select 1 from invoice_items where organization_id=p_org and invoice_id=p_invoice) then raise exception 'ARV-STATE-1001 invoice requires due date and items'; end if; perform app.recompute_invoice(p_org,p_invoice); select * into i from invoices where organization_id=p_org and id=p_invoice; select * into c from customers where organization_id=p_org and id=i.customer_id; select * into o from organizations where id=p_org; select minor_unit_exponent into exp from currency_definitions where currency_code=i.currency_code; num:=app.next_document_number(p_org,'INVOICE'); update invoices set status='ISSUED',invoice_number=num,currency_exponent=exp,issued_at=now(),customer_snapshot=jsonb_build_object('id',c.id,'name',c.name,'type',c.type,'phone',c.normalized_phone,'email',c.email),organization_snapshot=jsonb_build_object('name',o.name,'country_code',o.country_code,'timezone',o.timezone,'locale',o.locale),outstanding_minor=total_minor,calculator_version='1.0.1' where organization_id=p_org and id=p_invoice; insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,entity_version,idempotency_key) values(p_org,'INVOICE',p_invoice,'DRAFT','ISSUED',actor,i.version,p_key); perform app.activity(p_org,actor,'INVOICE',p_invoice,'invoice.issued','Invoice issued'); perform app.emit_event(p_org,actor,'invoice.issued','INVOICE',p_invoice,'{}',p_key); return jsonb_build_object('invoice_id',p_invoice,'invoice_number',num,'status','ISSUED'); end $$;

create or replace function app.record_payment(p_org uuid,p_invoice uuid,p_amount bigint,p_currency text,p_method text,p_reference text,p_paid_at timestamptz,p_notes text,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'payment.record'); i invoices%rowtype; pid uuid; newpaid bigint; newstatus text; h text; replay jsonb; begin h:=encode(digest(jsonb_build_array(p_invoice,p_amount,p_currency,p_method,p_reference,p_paid_at,p_notes,p_expected_version)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'payment.record',p_key,h); if replay is not null then return replay; end if; select * into i from invoices where organization_id=p_org and id=p_invoice for update; if not found or i.version<>p_expected_version or i.status not in ('ISSUED','PARTIALLY_PAID','OVERDUE') then raise exception 'ARV-CONFLICT-1001 invoice state/version conflict'; end if; if p_amount<=0 or p_currency<>i.currency_code then raise exception 'ARV-MONEY-3002 invalid payment amount/currency'; end if; if p_amount>i.outstanding_minor then raise exception 'ARV-MONEY-3003 overpayment rejected'; end if; insert into payments(organization_id,invoice_id,amount_minor,currency_code,method,reference,paid_at,received_by,notes,idempotency_key) values(p_org,p_invoice,p_amount,p_currency,p_method,p_reference,p_paid_at,actor,p_notes,p_key) returning id into pid; newpaid:=i.paid_minor+p_amount; newstatus:=case when newpaid=i.total_minor then 'PAID' when i.due_at<now() then 'OVERDUE' else 'PARTIALLY_PAID' end; update invoices set paid_minor=newpaid,outstanding_minor=total_minor-newpaid,status=newstatus,paid_at=case when newstatus='PAID' then now() else null end where organization_id=p_org and id=p_invoice; perform app.activity(p_org,actor,'INVOICE',p_invoice,'payment.recorded','Payment recorded',jsonb_build_object('payment_id',pid,'amount_minor',p_amount)); perform app.audit(p_org,actor,'payment.recorded','INVOICE',p_invoice,jsonb_build_object('paid_minor',i.paid_minor),jsonb_build_object('paid_minor',newpaid)); perform app.emit_event(p_org,actor,'payment.recorded','INVOICE',p_invoice,jsonb_build_object('payment_id',pid,'amount_minor',p_amount),p_key); if newstatus='PAID' then perform app.emit_event(p_org,actor,'invoice.paid','INVOICE',p_invoice,'{}',p_key||':paid'); end if; replay:=jsonb_build_object('payment_id',pid,'invoice_id',p_invoice,'invoice_status',newstatus,'paid_minor',newpaid,'outstanding_minor',i.total_minor-newpaid); perform app.idempotency_commit(p_org,actor,'payment.record',p_key,h,replay); return replay; end $$;

create or replace function app.reverse_payment(p_org uuid,p_payment uuid,p_reason text,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'payment.reverse'); p payments%rowtype; i invoices%rowtype; net bigint; state text; rid uuid; begin select * into p from payments where organization_id=p_org and id=p_payment; if not found or p.status<>'SETTLED' then raise exception 'ARV-STATE-1001 settled payment required'; end if; if coalesce(trim(p_reason),'')='' then raise exception 'reversal reason required'; end if; select * into i from invoices where organization_id=p_org and id=p.invoice_id for update; select * into p from payments where organization_id=p_org and id=p_payment for update; if p.status<>'SETTLED' or exists(select 1 from payment_reversals where organization_id=p_org and payment_id=p_payment) then raise exception 'ARV-STATE-1001 payment already reversed'; end if; insert into payment_reversals(organization_id,payment_id,amount_minor,reason,actor_member_id,idempotency_key) values(p_org,p_payment,p.amount_minor,p_reason,actor,p_key) returning id into rid; update payments set status='REVERSED' where organization_id=p_org and id=p_payment; net:=greatest(0,i.paid_minor-p.amount_minor); state:=case when net=i.total_minor then 'PAID' when net>0 and i.due_at<now() then 'OVERDUE' when net>0 then 'PARTIALLY_PAID' when i.due_at<now() then 'OVERDUE' else 'ISSUED' end; update invoices set paid_minor=net,outstanding_minor=total_minor-net,status=state,paid_at=case when state='PAID' then paid_at else null end where organization_id=p_org and id=i.id; perform app.audit(p_org,actor,'payment.reversed','INVOICE',i.id,jsonb_build_object('paid_minor',i.paid_minor),jsonb_build_object('paid_minor',net,'reason',p_reason)); perform app.activity(p_org,actor,'INVOICE',i.id,'payment.reversed','Payment reversed',jsonb_build_object('payment_id',p_payment)); perform app.emit_event(p_org,actor,'payment.reversed','INVOICE',i.id,jsonb_build_object('payment_id',p_payment,'reversal_id',rid),p_key); return jsonb_build_object('reversal_id',rid,'invoice_status',state,'paid_minor',net,'outstanding_minor',i.total_minor-net); end $$;

create or replace function app.void_invoice(p_org uuid,p_invoice uuid,p_reason text,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'invoice.void'); i invoices%rowtype; begin select * into i from invoices where organization_id=p_org and id=p_invoice for update; if not found or i.version<>p_expected_version or i.status not in ('DRAFT','ISSUED') then raise exception 'ARV-STATE-1001 invoice cannot be voided'; end if; if coalesce(trim(p_reason),'')='' or i.paid_minor<>0 then raise exception 'ARV-MONEY-3002 void requires reason and zero net settled payment'; end if; update invoices set status='VOID' where organization_id=p_org and id=p_invoice; insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,reason,entity_version,idempotency_key) values(p_org,'INVOICE',p_invoice,i.status,'VOID',actor,p_reason,i.version,p_key); perform app.audit(p_org,actor,'invoice.voided','INVOICE',p_invoice,to_jsonb(i),jsonb_build_object('status','VOID','reason',p_reason)); perform app.emit_event(p_org,actor,'invoice.voided','INVOICE',p_invoice,'{}',p_key); return jsonb_build_object('invoice_id',p_invoice,'status','VOID'); end $$;

create or replace function app.followup_action(p_org uuid,p_followup uuid,p_action text,p_due timestamptz,p_reason text,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare perm text; actor uuid; f follow_ups%rowtype; newstate text; begin perm:=case p_action when 'DONE' then 'followup.complete' when 'CANCEL' then 'followup.cancel' when 'SNOOZE' then 'followup.update' else null end; actor:=app.require_permission(p_org,perm); select * into f from follow_ups where organization_id=p_org and id=p_followup for update; if not found or f.version<>p_expected_version or f.status<>'PENDING' then raise exception 'ARV-CONFLICT-1001 follow-up state/version conflict'; end if; if p_action='SNOOZE' then if p_due is null then raise exception 'new due time required'; end if; update follow_ups set due_at=p_due where organization_id=p_org and id=p_followup; newstate:='PENDING'; elsif p_action='DONE' then update follow_ups set status='DONE',completed_at=now() where organization_id=p_org and id=p_followup; newstate:='DONE'; else update follow_ups set status='CANCELLED' where organization_id=p_org and id=p_followup; newstate:='CANCELLED'; end if; insert into follow_up_history(organization_id,follow_up_id,old_due_at,new_due_at,old_state,new_state,reason,actor_member_id,idempotency_key) values(p_org,p_followup,f.due_at,case when p_action='SNOOZE' then p_due else f.due_at end,f.status,newstate,p_reason,actor,p_key); perform app.activity(p_org,actor,'CUSTOMER',f.customer_id,case p_action when 'SNOOZE' then 'followup.snoozed' when 'DONE' then 'followup.completed' else 'followup.cancelled' end,'Follow-up '||lower(p_action)); return jsonb_build_object('follow_up_id',p_followup,'status',newstate,'due_at',case when p_action='SNOOZE' then p_due else f.due_at end); end $$;

-- Media lifecycle. Object existence/checksum is revalidated by server storage route before finalize RPC.
create or replace function app.create_media(p_org uuid,p_parent_type text,p_parent_id uuid,p_category text,p_storage_key text,p_mime text,p_checksum text,p_size bigint,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'media.create'); mid uuid:=gen_random_uuid(); lim bigint; used bigint; begin if p_size>15728640 then raise exception 'ARV-MEDIA-5001 file exceeds 15 MB pre-upload limit'; end if; if p_mime not in ('image/jpeg','image/png','image/webp','text/csv','application/pdf') then raise exception 'ARV-MEDIA-5001 MIME not allowed'; end if; if not app.entity_belongs_to_org(p_org,p_parent_type,p_parent_id) then raise exception 'ARV-TENANT-1003 invalid media parent'; end if; lim:=app.limit_value(p_org,'limit.storage_bytes'); select coalesce(value+reserved,0) into used from usage_counters where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now() for update; if used+p_size>lim then raise exception 'ARV-USAGE-6001 storage limit reached'; end if; update usage_counters set reserved=reserved+p_size,version=version+1 where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now(); insert into media(id,organization_id,parent_type,parent_id,category,storage_key,mime_type,checksum,size_bytes,quota_reserved_bytes,uploaded_by) values(mid,p_org,p_parent_type,p_parent_id,p_category,p_storage_key,p_mime,p_checksum,p_size,p_size,actor); return mid; end $$;
create or replace function app.finalize_media(p_org uuid,p_media uuid,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'media.finalize'); m media%rowtype; begin select * into m from media where organization_id=p_org and id=p_media for update; if not found then raise exception 'media not found'; end if; if m.upload_status='UPLOADED' then return jsonb_build_object('media_id',m.id,'status','UPLOADED'); end if; if m.upload_status not in ('UPLOADING','FAILED') then raise exception 'invalid media state'; end if; update media set upload_status='UPLOADED',quota_reserved_bytes=0,error_code=null,attempts=attempts+1 where organization_id=p_org and id=p_media; update usage_counters set reserved=greatest(0,reserved-m.quota_reserved_bytes),version=version+1 where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now(); perform app.apply_usage(p_org,'storage_bytes',m.size_bytes,'MEDIA',m.id::text,p_key); perform app.activity(p_org,actor,m.parent_type,m.parent_id,'media.uploaded','Evidence uploaded',jsonb_build_object('media_id',m.id)); perform app.emit_event(p_org,actor,'media.uploaded',m.parent_type,m.parent_id,jsonb_build_object('media_id',m.id),p_key); return jsonb_build_object('media_id',m.id,'status','UPLOADED'); end $$;


-- Queue claim helper (at-least-once, SKIP LOCKED, 60s lease).
create or replace function app.claim_queue(p_topic text,p_worker text,p_limit int default 10) returns setof queue_jobs language plpgsql security definer set search_path=public,app as $$ begin return query with c as (select id from queue_jobs where topic=p_topic and (status in ('PENDING','FAILED_RETRYABLE') and next_attempt_at<=now() or status='CLAIMED' and lease_expires_at<now()) order by next_attempt_at,created_at for update skip locked limit greatest(1,least(p_limit,100))) update queue_jobs q set status='CLAIMED',lease_owner=p_worker,lease_expires_at=now()+interval '60 seconds',attempts=attempts+1,updated_at=now() from c where q.id=c.id returning q.*; end $$;


-- ===== preserved implementation content from historical 0003_arvena_p0_rls.sql =====

-- RLS and scoped authorization. Server RPC functions are SECURITY DEFINER; direct clients remain constrained.
set search_path=public,app;

create or replace function app.is_privileged_db_actor() returns boolean language sql stable as $$ select current_user in ('postgres','supabase_admin','service_role') $$;
create or replace function app.guard_direct_state_change() returns trigger language plpgsql as $$ begin
  if app.is_privileged_db_actor() then return new; end if;
  if new.status is distinct from old.status then raise exception 'ARV-STATE-1001 state changes require server command'; end if; return new;
end $$;
create trigger trg_lead_state_command before update on leads for each row execute function app.guard_direct_state_change();
create trigger trg_quote_state_command before update on quotes for each row execute function app.guard_direct_state_change();
create trigger trg_job_state_command before update on jobs for each row execute function app.guard_direct_state_change();
create trigger trg_visit_state_command before update on visits for each row execute function app.guard_direct_state_change();
create trigger trg_invoice_state_command before update on invoices for each row execute function app.guard_direct_state_change();
create trigger trg_followup_state_command before update on follow_ups for each row execute function app.guard_direct_state_change();
create or replace function app.guard_job_schedule_cache() returns trigger language plpgsql as $$ begin
 if app.is_privileged_db_actor() then return new; end if;
 if new.scheduled_start is distinct from old.scheduled_start or new.scheduled_end is distinct from old.scheduled_end then raise exception 'ARV-JOB-4001 Job schedule cache is server-derived from Visits'; end if; return new; end $$;
create trigger trg_job_schedule_cache before update on jobs for each row execute function app.guard_job_schedule_cache();

-- Scoped read helpers
create or replace function app.can_view_lead(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin
 if mid is null or not app.has_permission(p_org,'lead.view') then return false; end if;
 if rk in ('OWNER','ADMIN') then return true; end if;
 if rk='SALES' then return exists(select 1 from leads where organization_id=p_org and id=p_id and assigned_sales_id=mid); end if;
 if rk='SUPERVISOR' then return exists(select 1 from leads l where l.organization_id=p_org and l.id=p_id and (l.assigned_sales_id=mid or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=mid and s.member_id=l.assigned_sales_id))); end if;
 return false;
end $$;
create or replace function app.can_view_customer(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin
 if mid is null or not app.has_permission(p_org,'customer.view') then return false; end if;
 if rk in ('OWNER','ADMIN','FINANCE') then return true; end if;
 if rk='SALES' then return exists(select 1 from customers c where c.organization_id=p_org and c.id=p_id and (c.assigned_sales_id=mid or exists(select 1 from leads l where l.organization_id=p_org and l.customer_id=c.id and l.assigned_sales_id=mid))); end if;
 if rk='WORKER' then return exists(select 1 from jobs j join visits v on v.organization_id=j.organization_id and v.job_id=j.id join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null where j.organization_id=p_org and j.customer_id=p_id and a.member_id=mid); end if;
 if rk='SUPERVISOR' then return exists(select 1 from jobs j join visits v on v.organization_id=j.organization_id and v.job_id=j.id join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null where j.organization_id=p_org and j.customer_id=p_id and (a.member_id=mid or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=mid and s.member_id=a.member_id))); end if;
 return false;
end $$;
create or replace function app.can_view_quote(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin
 if mid is null or not app.has_permission(p_org,'quote.view') then return false; end if;
 if rk in ('OWNER','ADMIN') then return true; end if;
 if rk='SALES' then return exists(select 1 from quotes q where q.organization_id=p_org and q.id=p_id and (q.owner_member_id=mid or app.can_view_customer(p_org,q.customer_id))); end if;
 if rk='SUPERVISOR' then return exists(select 1 from quotes q where q.organization_id=p_org and q.id=p_id and app.can_view_customer(p_org,q.customer_id)); end if;
 return false;
end $$;
create or replace function app.can_view_job(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin
 if mid is null or not app.has_permission(p_org,'job.view') then return false; end if;
 if rk in ('OWNER','ADMIN') then return true; end if;
 if rk='SALES' then return exists(select 1 from jobs j where j.organization_id=p_org and j.id=p_id and (app.can_view_customer(p_org,j.customer_id) or (j.lead_id is not null and app.can_view_lead(p_org,j.lead_id)))); end if;
 if rk='WORKER' then return exists(select 1 from visits v join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null where v.organization_id=p_org and v.job_id=p_id and a.member_id=mid); end if;
 if rk='SUPERVISOR' then return exists(select 1 from visits v join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null where v.organization_id=p_org and v.job_id=p_id and (a.member_id=mid or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=mid and s.member_id=a.member_id))); end if;
 return false;
end $$;
create or replace function app.can_view_visit(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); jid uuid; begin
 if mid is null or not app.has_permission(p_org,'visit.view') then return false; end if;
 if rk in ('OWNER','ADMIN') then return exists(select 1 from visits where organization_id=p_org and id=p_id); end if;
 if rk='WORKER' then return exists(select 1 from visit_assignments where organization_id=p_org and visit_id=p_id and member_id=mid and removed_at is null); end if;
 if rk='SUPERVISOR' then return exists(select 1 from visit_assignments a where a.organization_id=p_org and a.visit_id=p_id and a.removed_at is null and (a.member_id=mid or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=mid and s.member_id=a.member_id))); end if;
 select job_id into jid from visits where organization_id=p_org and id=p_id; return jid is not null and app.can_view_job(p_org,jid);
end $$;
create or replace function app.can_view_invoice(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin
 if mid is null or not app.has_permission(p_org,'invoice.view') then return false; end if;
 if rk in ('OWNER','ADMIN','FINANCE') then return true; end if;
 if rk='SALES' then return exists(select 1 from invoices i where i.organization_id=p_org and i.id=p_id and app.can_view_customer(p_org,i.customer_id)); end if; return false;
end $$;
create or replace function app.can_view_asset(p_org uuid,p_id uuid) returns boolean language sql stable security definer set search_path=public,app as $$
 select app.has_permission(p_org,'asset.view') and exists(select 1 from assets a where a.organization_id=p_org and a.id=p_id and app.can_view_customer(p_org,a.customer_id))
$$;
create or replace function app.can_view_followup(p_org uuid,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare rk text:=app.current_role_key(p_org); mid uuid:=app.current_member_id(p_org); begin if mid is null or not app.has_permission(p_org,'followup.view') then return false; end if; if rk in ('OWNER','ADMIN') then return true; end if; if rk='SALES' then return exists(select 1 from follow_ups f where f.organization_id=p_org and f.id=p_id and f.assigned_to=mid); end if; if rk='SUPERVISOR' then return exists(select 1 from follow_ups f where f.organization_id=p_org and f.id=p_id and (f.assigned_to=mid or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=mid and s.member_id=f.assigned_to))); end if; return false; end $$;

create or replace function app.can_access_entity(p_org uuid,p_type text,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$ begin
 case upper(p_type)
 when 'CUSTOMER' then return app.can_view_customer(p_org,p_id);
 when 'LEAD' then return app.can_view_lead(p_org,p_id);
 when 'QUOTE' then return app.can_view_quote(p_org,p_id);
 when 'JOB' then return app.can_view_job(p_org,p_id);
 when 'VISIT' then return app.can_view_visit(p_org,p_id);
 when 'INVOICE' then return app.can_view_invoice(p_org,p_id);
 when 'ASSET' then return app.can_view_asset(p_org,p_id);
 else return false; end case; end $$;

-- Enable RLS on all tenant and identity tables exposed through Supabase.
do $$ declare t text; begin
 foreach t in array array[
 'user_profiles','organizations','organization_settings','organization_modules','organization_invitations','roles','role_permissions','organization_members','member_permission_overrides','member_skills','member_availability','member_leave','member_devices','member_team_scope','subscriptions','organization_entitlement_overrides','usage_ledger','usage_counters',
 'customers','customer_addresses','tags','customer_tags','customer_contact_preferences','service_catalog','leads','lead_status_history','follow_ups','follow_up_history','quotes','quote_items','document_sequences','jobs','job_items','visits','visit_assignments','schedule_conflict_overrides','job_checklists','checklist_responses','media','notes','assets','job_assets','tax_profiles','invoices','invoice_items','payments','payment_reversals','document_state_history','recurring_rules','recurring_occurrences','activities','audit_logs','idempotency_receipts','client_action_receipts','event_outbox','queue_jobs','notifications','notification_deliveries','notification_preferences','import_jobs','import_rows','export_jobs']
 loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

-- user profile self access
create policy user_profiles_self_select on user_profiles for select using(user_id=auth.uid());
create policy user_profiles_self_insert on user_profiles for insert with check(user_id=auth.uid());
create policy user_profiles_self_update on user_profiles for update using(user_id=auth.uid()) with check(user_id=auth.uid());

-- Organization + membership context
create policy organizations_member_select on organizations for select using(app.current_member_id(id) is not null);
create policy org_settings_member_select on organization_settings for select using(app.current_member_id(organization_id) is not null);
create policy org_settings_manage on organization_settings for update using(app.has_permission(organization_id,'organization.manage') or app.has_permission(organization_id,'settings.localization') or app.has_permission(organization_id,'settings.workflow')) with check(app.current_member_id(organization_id) is not null);
create policy org_modules_member_select on organization_modules for select using(app.current_member_id(organization_id) is not null);
create policy roles_member_select on roles for select using(app.current_member_id(organization_id) is not null);
create policy role_permissions_member_select on role_permissions for select using(app.current_member_id(organization_id) is not null);
create policy invitations_view on organization_invitations for select using(app.has_permission(organization_id,'member.view') or lower(email)=(select lower(email) from auth.users where id=auth.uid()));
create policy invitations_insert on organization_invitations for insert with check(app.has_permission(organization_id,'member.invite'));
create policy invitations_update on organization_invitations for update using(app.has_permission(organization_id,'member.invite')) with check(app.has_permission(organization_id,'member.invite'));
create policy members_select on organization_members for select using(app.current_member_id(organization_id) is not null and (app.has_permission(organization_id,'member.view') or user_id=auth.uid()));
create policy member_overrides_select on member_permission_overrides for select using(app.has_permission(organization_id,'role.view'));
create policy member_skills_select on member_skills for select using(app.current_member_id(organization_id) is not null);
create policy member_skills_manage on member_skills for all using(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id)) with check(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id));
create policy member_availability_select on member_availability for select using(app.current_member_id(organization_id) is not null);
create policy member_availability_manage on member_availability for all using(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id)) with check(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id));
create policy member_leave_select on member_leave for select using(app.current_member_id(organization_id) is not null);
create policy member_leave_manage on member_leave for all using(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id)) with check(app.has_permission(organization_id,'member.update') or member_id=app.current_member_id(organization_id));
create policy member_devices_self on member_devices for all using(member_id=app.current_member_id(organization_id)) with check(member_id=app.current_member_id(organization_id));
create policy member_team_scope_select on member_team_scope for select using(app.has_permission(organization_id,'member.view') or supervisor_member_id=app.current_member_id(organization_id));

create policy subscriptions_view on subscriptions for select using(app.current_member_id(organization_id) is not null);
create policy ent_overrides_view on organization_entitlement_overrides for select using(app.has_permission(organization_id,'billing.manage'));
create policy usage_counters_view on usage_counters for select using(app.current_member_id(organization_id) is not null);
create policy usage_ledger_view on usage_ledger for select using(app.has_permission(organization_id,'billing.manage'));

-- Customers
create policy customers_select on customers for select using(app.can_view_customer(organization_id,id));
create policy customers_insert on customers for insert with check(app.has_permission(organization_id,'customer.create') and (assigned_sales_id is null or exists(select 1 from organization_members m where m.organization_id=customers.organization_id and m.id=assigned_sales_id and m.status='ACTIVE')));
create policy customers_update on customers for update using(app.can_view_customer(organization_id,id) and app.has_permission(organization_id,'customer.update')) with check(app.has_permission(organization_id,'customer.update'));
create policy addresses_select on customer_addresses for select using(app.can_view_customer(organization_id,customer_id));
