set search_path=public,app;
alter table organization_members add column if not exists display_name text;
alter table organization_members add column if not exists email text;

-- Sync snapshots when a profile is edited by the user.
create or replace function app.sync_member_profile() returns trigger language plpgsql security definer set search_path=public,app as $$ begin update organization_members set display_name=new.display_name where user_id=new.user_id; return new; end $$;
create trigger trg_profile_member_sync after insert or update of display_name on user_profiles for each row execute function app.sync_member_profile();

-- Recreate onboarding functions to store member identity snapshots.
create or replace function app.create_organization(p_name text,p_slug text,p_country text,p_currency text,p_timezone text,p_locale text default 'en',p_template_version uuid default null)
returns uuid language plpgsql security definer set search_path=public,app as $$
declare u uuid:=auth.uid(); org uuid:=gen_random_uuid(); role_row record; rid uuid; owner_role uuid; plan uuid; period_start timestamptz:=now(); period_end timestamptz:=now()+interval '1 month'; uname text; uemail text;
begin
 if u is null then raise exception 'ARV-AUTH-1001 authentication required'; end if;
 select coalesce(up.display_name,au.raw_user_meta_data->>'display_name',split_part(au.email,'@',1)),au.email into uname,uemail from auth.users au left join user_profiles up on up.user_id=au.id where au.id=u;
 if not exists(select 1 from currency_definitions where currency_code=p_currency and active) then raise exception 'invalid currency'; end if;
 insert into organizations(id,name,slug,country_code,currency_code,timezone,locale,industry_template_version_id) values(org,trim(p_name),lower(trim(p_slug)),upper(p_country),upper(p_currency),p_timezone,p_locale,p_template_version);
 insert into organization_settings(organization_id,localization,workflow) values(org,jsonb_build_object('country_code',upper(p_country),'currency_code',upper(p_currency),'timezone',p_timezone,'locale',p_locale),'{}'::jsonb);
 insert into organization_modules(organization_id,module_key,enabled) values(org,'ASSETS',true),(org,'RECURRING',true);
 for role_row in select * from system_role_templates where version=1 loop
   insert into roles(organization_id,name,system_key,is_system_role) values(org,role_row.name,role_row.system_key,true) returning id into rid;
   insert into role_permissions(organization_id,role_id,permission_key,allowed) select org,rid,value,true from jsonb_array_elements_text(role_row.permissions);
   if role_row.system_key='OWNER' then owner_role:=rid; end if;
 end loop;
 insert into organization_members(organization_id,user_id,role_id,status,joined_at,display_name,email) values(org,u,owner_role,'ACTIVE',now(),uname,uemail);
 select id into plan from plan_versions where plan_key='FREE' and active order by version desc limit 1;
 insert into subscriptions(organization_id,plan_version_id,status,period_start,period_end) values(org,plan,'ACTIVE',period_start,period_end);
 insert into usage_counters(organization_id,period_start,period_end,metric_key,value,reserved) values(org,period_start,period_end,'jobs_created',0,0),(org,period_start,period_end,'storage_bytes',0,0),(org,period_start,period_end,'team_members',1,0);
 insert into tax_profiles(organization_id,name,rate_ppm,behavior,is_default) values(org,'No tax',0,'EXEMPT',true);
 return org;
end $$;

create or replace function app.accept_invitation(p_invitation uuid) returns uuid language plpgsql security definer set search_path=public,app as $$
declare u uuid:=auth.uid(); em text; uname text; inv organization_invitations%rowtype; mid uuid;
begin
 if u is null then raise exception 'authentication required'; end if;
 select email,coalesce(raw_user_meta_data->>'display_name',split_part(email,'@',1)) into em,uname from auth.users where id=u;
 select * into inv from organization_invitations where id=p_invitation for update;
 if not found or inv.status<>'PENDING' or inv.expires_at<=now() or lower(em)<>inv.normalized_email then raise exception 'ARV-TENANT-1002 invitation invalid'; end if;
 insert into organization_members(organization_id,user_id,role_id,status,invited_at,joined_at,display_name,email) values(inv.organization_id,u,inv.intended_role_id,'ACTIVE',inv.invited_at,now(),uname,em)
 on conflict(organization_id,user_id) do update set role_id=excluded.role_id,status='ACTIVE',joined_at=now(),display_name=excluded.display_name,email=excluded.email returning id into mid;
 update organization_invitations set status='ACCEPTED',accepted_at=now() where id=inv.id;
 return mid;
end $$;

create or replace view customer_list_v with(security_invoker=true) as
select c.id,c.organization_id,c.name,c.type,c.raw_phone,c.normalized_phone,c.whatsapp_phone,c.email,c.source,c.status,c.assigned_sales_id,m.display_name assigned_sales,
 (select max(j.updated_at) from jobs j where j.organization_id=c.organization_id and j.customer_id=c.id) last_job_at,
 c.updated_at,c.archived_at,c.version
from customers c left join organization_members m on m.organization_id=c.organization_id and m.id=c.assigned_sales_id;

create or replace view lead_list_v with(security_invoker=true) as
select l.id,l.organization_id,l.customer_id,c.name customer,c.normalized_phone phone,l.title service,l.status,l.temperature,l.source,l.assigned_sales_id,m.display_name sales,l.estimated_value_minor,l.currency_code,l.next_follow_up_at,l.created_at,l.updated_at,l.version
from leads l join customers c on c.organization_id=l.organization_id and c.id=l.customer_id left join organization_members m on m.organization_id=l.organization_id and m.id=l.assigned_sales_id where l.archived_at is null;

create or replace view quote_list_v with(security_invoker=true) as
select q.id,q.organization_id,q.quote_number,c.name customer,q.total_minor,q.currency_code,q.currency_exponent,q.status,q.expires_at,q.created_at,q.updated_at,q.version,m.display_name sales
from quotes q join customers c on c.organization_id=q.organization_id and c.id=q.customer_id left join organization_members m on m.organization_id=q.organization_id and m.id=q.owner_member_id where q.archived_at is null;

create or replace view job_list_v with(security_invoker=true) as
select j.id,j.organization_id,j.job_number,c.name customer,j.title service,j.status,j.priority,j.estimated_amount_minor,j.currency_code,j.updated_at,j.version,
 (select min(v.scheduled_start) from visits v where v.organization_id=j.organization_id and v.job_id=j.id and v.status not in('CANCELLED','NO_SHOW') and v.scheduled_end>=now()) next_visit,
 (select string_agg(distinct coalesce(m.display_name,m.email,'Member'),', ' order by coalesce(m.display_name,m.email,'Member')) from visits v join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null join organization_members m on m.organization_id=a.organization_id and m.id=a.member_id where v.organization_id=j.organization_id and v.job_id=j.id and v.status not in('CANCELLED','NO_SHOW')) assigned_team
from jobs j join customers c on c.organization_id=j.organization_id and c.id=j.customer_id where j.archived_at is null;

create or replace view visit_list_v with(security_invoker=true) as
select v.id,v.organization_id,v.job_id,j.job_number,j.title service,c.id customer_id,c.name customer,v.status,v.scheduled_start,v.scheduled_end,v.timezone,v.actual_departed_at,v.actual_arrived_at,v.actual_started_at,v.actual_completed_at,v.address_snapshot,v.version,
 (select string_agg(coalesce(m.display_name,m.email,'Member'),', ') from visit_assignments a join organization_members m on m.organization_id=a.organization_id and m.id=a.member_id where a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null) assigned_team
from visits v join jobs j on j.organization_id=v.organization_id and j.id=v.job_id join customers c on c.organization_id=j.organization_id and c.id=j.customer_id;

create or replace view invoice_list_v with(security_invoker=true) as
select i.id,i.organization_id,i.invoice_number,c.name customer,i.total_minor,i.paid_minor,i.outstanding_minor,i.currency_code,i.currency_exponent,i.due_at,i.status,i.created_at,i.updated_at,i.version
from invoices i join customers c on c.organization_id=i.organization_id and c.id=i.customer_id where i.archived_at is null;

create or replace view payment_list_v with(security_invoker=true) as
select p.id,p.organization_id,p.invoice_id,i.invoice_number,c.name customer,p.amount_minor,p.currency_code,p.method,p.reference,p.paid_at,p.status,coalesce(m.display_name,m.email) received_by
from payments p join invoices i on i.organization_id=p.organization_id and i.id=p.invoice_id join customers c on c.organization_id=i.organization_id and c.id=i.customer_id left join organization_members m on m.organization_id=p.organization_id and m.id=p.received_by;

create or replace view followup_list_v with(security_invoker=true) as
select f.id,f.organization_id,f.customer_id,c.name customer,c.normalized_phone phone,f.reason,f.due_at,f.timezone,f.status,f.assigned_to,coalesce(m.display_name,m.email) assignee,f.lead_id,f.quote_id,f.job_id,f.invoice_id,f.version,f.completed_at
from follow_ups f join customers c on c.organization_id=f.organization_id and c.id=f.customer_id left join organization_members m on m.organization_id=f.organization_id and m.id=f.assigned_to where f.archived_at is null;

create or replace view asset_list_v with(security_invoker=true) as
select a.id,a.organization_id,a.customer_id,c.name customer,a.asset_type,a.name,a.brand,a.model,a.serial_number,a.installed_at,a.warranty_until,a.status,a.updated_at,a.version
from assets a join customers c on c.organization_id=a.organization_id and c.id=a.customer_id where a.archived_at is null;

create or replace view recurring_list_v with(security_invoker=true) as
select r.id,r.organization_id,r.customer_id,c.name customer,r.recurrence_type,r.interval_value,r.local_time,r.timezone,r.starts_on,r.ends_on,r.next_occurrence_at,r.active,r.version,
 (select count(*) from recurring_occurrences o where o.organization_id=r.organization_id and o.recurring_rule_id=r.id and o.status in('FAILED_RETRYABLE','FAILED_FINAL')) failures
from recurring_rules r join customers c on c.organization_id=r.organization_id and c.id=r.customer_id;

create or replace view team_list_v with(security_invoker=true) as
select m.id,m.organization_id,m.display_name,m.email,m.status,m.joined_at,m.version,r.system_key role,r.name role_name,
 (select string_agg(s.name,', ' order by s.name) from member_skills s where s.organization_id=m.organization_id and s.member_id=m.id and s.active) skills,
 (select count(*) from visit_assignments a join visits v on v.organization_id=a.organization_id and v.id=a.visit_id where a.organization_id=m.organization_id and a.member_id=m.id and a.removed_at is null and v.status in('SCHEDULED','EN_ROUTE','ARRIVED','IN_PROGRESS')) active_jobs
from organization_members m join roles r on r.organization_id=m.organization_id and r.id=m.role_id;


