set search_path=public,app;

create or replace function app.create_lead(p_org uuid,p_customer uuid,p_title text,p_description text,p_temperature text,p_source text,p_assigned uuid,p_estimated bigint,p_currency text,p_next_followup timestamptz,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'lead.create'); lid uuid:=gen_random_uuid(); h text; replay jsonb; begin h:=encode(digest(jsonb_build_array(p_customer,p_title,p_description,p_temperature,p_source,p_assigned,p_estimated,p_currency,p_next_followup)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'lead.create',p_key,h); if replay is not null then return (replay->>'lead_id')::uuid; end if; if not app.can_view_customer(p_org,p_customer) then raise exception 'ARV-PERM-1001 customer scope denied'; end if; insert into leads(id,organization_id,customer_id,title,description,temperature,source,assigned_sales_id,estimated_value_minor,currency_code,next_follow_up_at) values(lid,p_org,p_customer,p_title,p_description,coalesce(p_temperature,'WARM'),p_source,coalesce(p_assigned,actor),p_estimated,p_currency,p_next_followup); insert into lead_status_history(organization_id,lead_id,from_status,to_status,changed_by,idempotency_key) values(p_org,lid,null,'NEW',actor,p_key); perform app.activity(p_org,actor,'LEAD',lid,'lead.created','Lead created'); perform app.emit_event(p_org,actor,'lead.created','LEAD',lid,'{}',p_key); perform app.idempotency_commit(p_org,actor,'lead.create',p_key,h,jsonb_build_object('lead_id',lid)); return lid; end $$;

create or replace function app.create_followup(p_org uuid,p_customer uuid,p_reason text,p_due timestamptz,p_timezone text,p_assigned uuid,p_lead uuid,p_quote uuid,p_job uuid,p_invoice uuid,p_notes text,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'followup.create'); fid uuid:=gen_random_uuid(); h text; replay jsonb; begin h:=encode(digest(jsonb_build_array(p_customer,p_reason,p_due,p_timezone,p_assigned,p_lead,p_quote,p_job,p_invoice,p_notes)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'followup.create',p_key,h); if replay is not null then return (replay->>'follow_up_id')::uuid; end if; insert into follow_ups(id,organization_id,customer_id,reason,due_at,timezone,assigned_to,lead_id,quote_id,job_id,invoice_id,notes) values(fid,p_org,p_customer,p_reason,p_due,p_timezone,coalesce(p_assigned,actor),p_lead,p_quote,p_job,p_invoice,p_notes); perform app.activity(p_org,actor,'CUSTOMER',p_customer,'followup.created','Follow-up created',jsonb_build_object('follow_up_id',fid)); perform app.emit_event(p_org,actor,'followup.created','CUSTOMER',p_customer,jsonb_build_object('follow_up_id',fid),p_key); perform app.idempotency_commit(p_org,actor,'followup.create',p_key,h,jsonb_build_object('follow_up_id',fid)); return fid; end $$;

create or replace function app.create_asset(p_org uuid,p_customer uuid,p_type text,p_name text,p_brand text,p_model text,p_serial text,p_installed date,p_warranty date,p_notes text,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'asset.manage'); aid uuid:=gen_random_uuid(); h text; replay jsonb; begin h:=encode(digest(jsonb_build_array(p_customer,p_type,p_name,p_brand,p_model,p_serial,p_installed,p_warranty,p_notes)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'asset.create',p_key,h); if replay is not null then return (replay->>'asset_id')::uuid; end if; insert into assets(id,organization_id,customer_id,asset_type,name,brand,model,serial_number,installed_at,warranty_until,notes) values(aid,p_org,p_customer,p_type,p_name,p_brand,p_model,p_serial,p_installed,p_warranty,p_notes); perform app.activity(p_org,actor,'ASSET',aid,'asset.created','Asset created'); perform app.emit_event(p_org,actor,'asset.created','ASSET',aid,'{}',p_key); perform app.idempotency_commit(p_org,actor,'asset.create',p_key,h,jsonb_build_object('asset_id',aid)); return aid; end $$;

create or replace function app.create_recurring_rule(p_org uuid,p_customer uuid,p_asset uuid,p_type text,p_interval int,p_local_time time,p_timezone text,p_starts date,p_ends date,p_template jsonb,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'recurring.manage'); rid uuid:=gen_random_uuid(); h text; replay jsonb; begin if not app.feature_enabled(p_org,'feature.recurring_basic') then raise exception 'ARV-USAGE-6001 recurring not entitled'; end if; h:=encode(digest(jsonb_build_array(p_customer,p_asset,p_type,p_interval,p_local_time,p_timezone,p_starts,p_ends,p_template)::text,'sha256'),'hex'); replay:=app.idempotency_existing(p_org,actor,'recurring.create',p_key,h); if replay is not null then return (replay->>'rule_id')::uuid; end if; insert into recurring_rules(id,organization_id,customer_id,asset_id,recurrence_type,interval_value,local_time,timezone,starts_on,ends_on,template_data) values(rid,p_org,p_customer,p_asset,p_type,p_interval,p_local_time,p_timezone,p_starts,p_ends,coalesce(p_template,'{}')); perform app.activity(p_org,actor,'CUSTOMER',p_customer,'recurring.created','Recurring service rule created',jsonb_build_object('rule_id',rid)); perform app.idempotency_commit(p_org,actor,'recurring.create',p_key,h,jsonb_build_object('rule_id',rid)); return rid; end $$;

create or replace function app.update_recurring_rule(p_org uuid,p_rule uuid,p_expected_version int,p_type text,p_interval int,p_local_time time,p_timezone text,p_starts date,p_ends date,p_template jsonb,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'recurring.manage'); r recurring_rules%rowtype; begin select * into r from recurring_rules where organization_id=p_org and id=p_rule for update; if not found or r.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale recurring rule'; end if; update recurring_rules set recurrence_type=p_type,interval_value=p_interval,local_time=p_local_time,timezone=p_timezone,starts_on=p_starts,ends_on=p_ends,template_data=p_template,next_occurrence_at=null where organization_id=p_org and id=p_rule; update recurring_occurrences set status='CANCELLED',reason='RULE_CHANGED' where organization_id=p_org and recurring_rule_id=p_rule and status='PENDING'; perform app.audit(p_org,actor,'recurring.rule_changed','CUSTOMER',r.customer_id,to_jsonb(r),jsonb_build_object('version',r.version+1)); return jsonb_build_object('rule_id',p_rule,'version',r.version+1); end $$;
create or replace function app.skip_recurring_occurrence(p_org uuid,p_occ uuid,p_reason text,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'recurring.manage'); o recurring_occurrences%rowtype; begin if coalesce(trim(p_reason),'')='' then raise exception 'reason required'; end if; select * into o from recurring_occurrences where organization_id=p_org and id=p_occ for update; if not found or o.status<>'PENDING' then raise exception 'ARV-STATE-1001 only pending occurrence can be skipped'; end if; update recurring_occurrences set status='SKIPPED',reason=p_reason where organization_id=p_org and id=p_occ; perform app.emit_event(p_org,actor,'recurring.occurrence_skipped','JOB',coalesce(o.generated_job_id,p_occ),jsonb_build_object('occurrence_id',p_occ),p_key); return jsonb_build_object('occurrence_id',p_occ,'status','SKIPPED'); end $$;
create or replace function app.deactivate_recurring_rule(p_org uuid,p_rule uuid,p_reason text,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'recurring.manage'); r recurring_rules%rowtype; begin select * into r from recurring_rules where organization_id=p_org and id=p_rule for update; if not found then raise exception 'rule not found'; end if; update recurring_rules set active=false where organization_id=p_org and id=p_rule; update recurring_occurrences set status='CANCELLED',reason=coalesce(p_reason,'RULE_DEACTIVATED') where organization_id=p_org and recurring_rule_id=p_rule and status='PENDING'; perform app.activity(p_org,actor,'CUSTOMER',r.customer_id,'recurring.deactivated','Recurring rule deactivated'); return jsonb_build_object('rule_id',p_rule,'active',false); end $$;

create or replace function app.invite_member(p_org uuid,p_email text,p_role uuid,p_key text) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'member.invite'); lim bigint; current_count int; admin_lim bigint; role_key text; iid uuid; begin perform pg_advisory_xact_lock(hashtextextended(p_org::text,11)); lim:=app.limit_value(p_org,'limit.team_members_total'); select count(*) into current_count from organization_members where organization_id=p_org and status='ACTIVE'; current_count:=current_count+(select count(*) from organization_invitations where organization_id=p_org and status='PENDING' and expires_at>now()); if current_count>=lim then raise exception 'ARV-USAGE-6001 team member limit reached'; end if; select system_key into role_key from roles where organization_id=p_org and id=p_role; if role_key is null then raise exception 'invalid role'; end if; if role_key='OWNER' then raise exception 'Owner transfer requires dedicated ownership flow'; end if; if role_key='ADMIN' then admin_lim:=app.limit_value(p_org,'limit.admin_members_total'); if (select count(*) from organization_members m join roles r on r.organization_id=m.organization_id and r.id=m.role_id where m.organization_id=p_org and m.status='ACTIVE' and r.system_key='ADMIN')+(select count(*) from organization_invitations i join roles r on r.organization_id=i.organization_id and r.id=i.intended_role_id where i.organization_id=p_org and i.status='PENDING' and i.expires_at>now() and r.system_key='ADMIN')>=admin_lim then raise exception 'ARV-USAGE-6001 Admin member limit reached'; end if; end if; insert into organization_invitations(organization_id,email,intended_role_id,inviter_member_id,expires_at,status) values(p_org,lower(trim(p_email)),p_role,actor,now()+interval '7 days','PENDING') returning id into iid; perform app.audit(p_org,actor,'member.invited','CUSTOMER',iid,null,jsonb_build_object('email',lower(trim(p_email)),'role',role_key)); return iid; end $$;

create or replace function app.update_member(p_org uuid,p_member uuid,p_role uuid,p_status text,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'member.update'); m organization_members%rowtype; old_role text; new_role text; begin select * into m from organization_members where organization_id=p_org and id=p_member for update; if not found then raise exception 'member not found'; end if; if p_role is distinct from m.role_id then if not app.has_permission(p_org,'role.assign') then raise exception 'ARV-PERM-1001 role assign denied'; end if; end if; if p_status='DISABLED' and not app.has_permission(p_org,'member.disable') then raise exception 'ARV-PERM-1001 disable denied'; end if; select system_key into old_role from roles where organization_id=p_org and id=m.role_id; select system_key into new_role from roles where organization_id=p_org and id=p_role; update organization_members set role_id=p_role,status=p_status,disabled_at=case when p_status='DISABLED' then now() else null end where organization_id=p_org and id=p_member; perform app.audit(p_org,actor,'member.updated','CUSTOMER',p_member,jsonb_build_object('role',old_role,'status',m.status),jsonb_build_object('role',new_role,'status',p_status)); return jsonb_build_object('member_id',p_member,'role',new_role,'status',p_status); end $$;

create or replace function app.update_quote_draft(p_org uuid,p_quote uuid,p_expected_version int,p_expires timestamptz,p_terms text,p_document_discount bigint,p_items jsonb,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'quote.update_draft'); q quotes%rowtype; item jsonb; begin select * into q from quotes where organization_id=p_org and id=p_quote for update; if not found or q.status<>'DRAFT' or q.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 quote draft version conflict'; end if; delete from quote_items where organization_id=p_org and quote_id=p_quote; update quotes set expires_at=p_expires,terms_snapshot=p_terms,document_discount_minor=coalesce(p_document_discount,0) where organization_id=p_org and id=p_quote; for item in select * from jsonb_array_elements(p_items) loop insert into quote_items(organization_id,quote_id,name_snapshot,description_snapshot,unit_snapshot,quantity,unit_price_minor,line_discount_minor,tax_rate_ppm,tax_behavior,sort_order) values(p_org,p_quote,item->>'name',item->>'description',item->>'unit',coalesce((item->>'quantity')::numeric,1),coalesce((item->>'unit_price_minor')::bigint,0),coalesce((item->>'line_discount_minor')::bigint,0),coalesce((item->>'tax_rate_ppm')::int,0),coalesce(item->>'tax_behavior','EXEMPT'),coalesce((item->>'sort_order')::int,1)); end loop; perform app.recompute_quote(p_org,p_quote); return jsonb_build_object('quote_id',p_quote,'version',q.version+1); end $$;

create or replace function app.update_invoice_draft(p_org uuid,p_invoice uuid,p_expected_version int,p_due timestamptz,p_terms text,p_document_discount bigint,p_items jsonb,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$ declare actor uuid:=app.require_permission(p_org,'invoice.update_draft'); i invoices%rowtype; item jsonb; begin select * into i from invoices where organization_id=p_org and id=p_invoice for update; if not found or i.status<>'DRAFT' or i.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 invoice draft version conflict'; end if; delete from invoice_items where organization_id=p_org and invoice_id=p_invoice; update invoices set due_at=p_due,terms_snapshot=p_terms,document_discount_minor=coalesce(p_document_discount,0) where organization_id=p_org and id=p_invoice; for item in select * from jsonb_array_elements(p_items) loop insert into invoice_items(organization_id,invoice_id,name_snapshot,description_snapshot,quantity,unit_snapshot,unit_price_minor,line_discount_minor,tax_rate_ppm,tax_behavior,sort_order) values(p_org,p_invoice,item->>'name',item->>'description',coalesce((item->>'quantity')::numeric,1),item->>'unit',coalesce((item->>'unit_price_minor')::bigint,0),coalesce((item->>'line_discount_minor')::bigint,0),coalesce((item->>'tax_rate_ppm')::int,0),coalesce(item->>'tax_behavior','EXEMPT'),coalesce((item->>'sort_order')::int,1)); end loop; perform app.recompute_invoice(p_org,p_invoice); return jsonb_build_object('invoice_id',p_invoice,'version',i.version+1); end $$;

create or replace function app.job_action(p_org uuid,p_job uuid,p_action text,p_reason text,p_expected_version int,p_key text) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare perm text; actor uuid; j jobs%rowtype; to_state text; begin perm:=case p_action when 'HOLD' then 'job.update' when 'RESUME' then 'job.update' when 'CANCEL' then 'job.cancel' when 'CANCEL_PRIVILEGED' then 'job.cancel_privileged' else null end; actor:=app.require_permission(p_org,perm); select * into j from jobs where organization_id=p_org and id=p_job for update; if not found or j.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Job'; end if; if p_action in ('CANCEL','CANCEL_PRIVILEGED','HOLD') and coalesce(trim(p_reason),'')='' then raise exception 'reason required'; end if; to_state:=case p_action when 'HOLD' then 'ON_HOLD' when 'RESUME' then case when exists(select 1 from visits where organization_id=p_org and job_id=p_job and status='IN_PROGRESS') then 'IN_PROGRESS' else 'SCHEDULED' end else 'CANCELLED' end; if p_action='HOLD' and j.status not in('SCHEDULED','IN_PROGRESS') then raise exception 'ARV-STATE-1001 hold denied'; elsif p_action='RESUME' and j.status<>'ON_HOLD' then raise exception 'ARV-STATE-1001 resume denied'; elsif p_action='CANCEL' and j.status not in('DRAFT','CONFIRMED','SCHEDULED','ON_HOLD') then raise exception 'ARV-STATE-1001 cancel denied'; elsif p_action='CANCEL_PRIVILEGED' and j.status<>'IN_PROGRESS' then raise exception 'ARV-STATE-1001 privileged cancel only in progress'; end if; update jobs set status=to_state,cancelled_at=case when to_state='CANCELLED' then now() else cancelled_at end,cancellation_reason=case when to_state='CANCELLED' then p_reason else cancellation_reason end where organization_id=p_org and id=p_job; if to_state='CANCELLED' then update visits set status='CANCELLED' where organization_id=p_org and job_id=p_job and status='SCHEDULED'; end if; insert into document_state_history(organization_id,entity_type,entity_id,from_state,to_state,actor_member_id,reason,entity_version,idempotency_key) values(p_org,'JOB',p_job,j.status,to_state,actor,p_reason,j.version,p_key); perform app.activity(p_org,actor,'JOB',p_job,'job.'||lower(to_state),'Job '||lower(to_state)); perform app.emit_event(p_org,actor,case when to_state='CANCELLED' then 'job.cancelled' when to_state='ON_HOLD' then 'job.on_hold' else 'job.resumed' end,'JOB',p_job,'{}',p_key); return jsonb_build_object('job_id',p_job,'status',to_state); end $$;


-- ===== preserved implementation content from historical 0006_arvena_p0_release_fixes.sql =====

-- Release hardening: view fields, polymorphic tenant targets, grants and mixed template RLS.
set search_path=public,app;

-- Polymorphic records must resolve to a tenant-owned entity. Expand the typed catalog used by
-- audit/activity/outbox-facing commands; path strings are never treated as authorization.
create or replace function app.entity_belongs_to_org(p_org uuid,p_type text,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$
begin
  case upper(p_type)
    when 'ORGANIZATION' then return p_org=p_id and exists(select 1 from organizations where id=p_org);
    when 'MEMBER' then return exists(select 1 from organization_members where organization_id=p_org and id=p_id);
    when 'INVITATION' then return exists(select 1 from organization_invitations where organization_id=p_org and id=p_id);
    when 'CUSTOMER' then return exists(select 1 from customers where organization_id=p_org and id=p_id);
    when 'LEAD' then return exists(select 1 from leads where organization_id=p_org and id=p_id);
    when 'QUOTE' then return exists(select 1 from quotes where organization_id=p_org and id=p_id);
    when 'JOB' then return exists(select 1 from jobs where organization_id=p_org and id=p_id);
    when 'VISIT' then return exists(select 1 from visits where organization_id=p_org and id=p_id);
    when 'INVOICE' then return exists(select 1 from invoices where organization_id=p_org and id=p_id);
    when 'PAYMENT' then return exists(select 1 from payments where organization_id=p_org and id=p_id);
    when 'FOLLOW_UP' then return exists(select 1 from follow_ups where organization_id=p_org and id=p_id);
    when 'MEDIA' then return exists(select 1 from media where organization_id=p_org and id=p_id);
    when 'ASSET' then return exists(select 1 from assets where organization_id=p_org and id=p_id);
    when 'RECURRING_RULE' then return exists(select 1 from recurring_rules where organization_id=p_org and id=p_id);
    when 'RECURRING_OCCURRENCE' then return exists(select 1 from recurring_occurrences where organization_id=p_org and id=p_id);
    when 'IMPORT' then return exists(select 1 from import_jobs where organization_id=p_org and id=p_id);
    when 'EXPORT' then return exists(select 1 from export_jobs where organization_id=p_org and id=p_id);
    else return false;
  end case;
end $$;

create or replace function app.can_access_entity(p_org uuid,p_type text,p_id uuid) returns boolean language plpgsql stable security definer set search_path=public,app as $$ begin
 case upper(p_type)
 when 'ORGANIZATION' then return app.current_member_id(p_org) is not null and p_org=p_id;
 when 'MEMBER' then return app.has_permission(p_org,'member.view') and exists(select 1 from organization_members where organization_id=p_org and id=p_id);
 when 'CUSTOMER' then return app.can_view_customer(p_org,p_id);
 when 'LEAD' then return app.can_view_lead(p_org,p_id);
 when 'QUOTE' then return app.can_view_quote(p_org,p_id);
 when 'JOB' then return app.can_view_job(p_org,p_id);
 when 'VISIT' then return app.can_view_visit(p_org,p_id);
 when 'INVOICE' then return app.can_view_invoice(p_org,p_id);
 when 'PAYMENT' then return exists(select 1 from payments p where p.organization_id=p_org and p.id=p_id and app.has_permission(p_org,'payment.view') and app.can_view_invoice(p_org,p.invoice_id));
 when 'FOLLOW_UP' then return app.can_view_followup(p_org,p_id);
 when 'ASSET' then return app.can_view_asset(p_org,p_id);
 when 'RECURRING_RULE' then return exists(select 1 from recurring_rules r where r.organization_id=p_org and r.id=p_id and app.has_permission(p_org,'recurring.view') and app.can_view_customer(p_org,r.customer_id));
 else return false; end case; end $$;

-- Views intentionally expose foreign keys used for drill-through; underlying security-invoker views retain RLS.
drop view if exists quote_list_v;
drop view if exists job_list_v;
drop view if exists invoice_list_v;
create or replace view quote_list_v with(security_invoker=true) as
select q.id,q.organization_id,q.customer_id,q.lead_id,q.owner_member_id,q.quote_number,c.name customer,q.total_minor,q.currency_code,q.currency_exponent,q.status,q.expires_at,q.issued_at,q.accepted_at,q.created_at,q.updated_at,q.version,m.display_name sales
from quotes q join customers c on c.organization_id=q.organization_id and c.id=q.customer_id left join organization_members m on m.organization_id=q.organization_id and m.id=q.owner_member_id where q.archived_at is null;

create or replace view job_list_v with(security_invoker=true) as
select j.id,j.organization_id,j.customer_id,j.lead_id,j.quote_id,j.primary_address_id,j.job_number,c.name customer,j.title service,j.status,j.priority,j.estimated_amount_minor,j.currency_code,j.created_at,j.updated_at,j.version,
 (select min(v.scheduled_start) from visits v where v.organization_id=j.organization_id and v.job_id=j.id and v.status not in('CANCELLED','NO_SHOW') and v.scheduled_end>=now()) next_visit,
 (select string_agg(distinct coalesce(m.display_name,m.email,'Member'),', ' order by coalesce(m.display_name,m.email,'Member')) from visits v join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null join organization_members m on m.organization_id=a.organization_id and m.id=a.member_id where v.organization_id=j.organization_id and v.job_id=j.id and v.status not in('CANCELLED','NO_SHOW')) assigned_team
from jobs j join customers c on c.organization_id=j.organization_id and c.id=j.customer_id where j.archived_at is null;

create or replace view invoice_list_v with(security_invoker=true) as
select i.id,i.organization_id,i.customer_id,i.job_id,i.quote_id,i.invoice_number,c.name customer,i.total_minor,i.paid_minor,i.outstanding_minor,i.currency_code,i.currency_exponent,i.due_at,i.status,i.issued_at,i.paid_at,i.created_at,i.updated_at,i.version
from invoices i join customers c on c.organization_id=i.organization_id and c.id=i.customer_id where i.archived_at is null;

-- Global-or-tenant checklist definitions: global templates are read-only to clients; tenant templates are scoped.
alter table checklist_templates enable row level security;
alter table checklist_template_items enable row level security;
drop policy if exists checklist_templates_select on checklist_templates;
create policy checklist_templates_select on checklist_templates for select using(organization_id is null or app.current_member_id(organization_id) is not null);
drop policy if exists checklist_templates_manage on checklist_templates;
create policy checklist_templates_manage on checklist_templates for all using(organization_id is not null and app.has_permission(organization_id,'settings.workflow')) with check(organization_id is not null and app.has_permission(organization_id,'settings.workflow'));
drop policy if exists checklist_template_items_select on checklist_template_items;
create policy checklist_template_items_select on checklist_template_items for select using(exists(select 1 from checklist_templates t where t.id=checklist_template_id and (t.organization_id is null or app.current_member_id(t.organization_id) is not null)));
drop policy if exists checklist_template_items_manage on checklist_template_items;
create policy checklist_template_items_manage on checklist_template_items for all using(exists(select 1 from checklist_templates t where t.id=checklist_template_id and t.organization_id is not null and app.has_permission(t.organization_id,'settings.workflow'))) with check(exists(select 1 from checklist_templates t where t.id=checklist_template_id and t.organization_id is not null and app.has_permission(t.organization_id,'settings.workflow')));

-- Supabase exposed-schema privileges. RLS remains the authorization boundary.
grant usage on schema public,app to authenticated;
grant select on currency_definitions,plan_versions,plan_entitlements,industry_templates,industry_template_versions,system_role_templates to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
revoke insert,update,delete on payments,payment_reversals,document_state_history,activities,audit_logs,idempotency_receipts,client_action_receipts,event_outbox,queue_jobs from authenticated;
revoke insert,update,delete on quotes,invoices,visits,lead_status_history,follow_up_history from authenticated;
-- broad function grants intentionally removed; final explicit least-privilege grants are applied below.

-- Safe read-only exposure for generated list views.
grant select on customer_list_v,lead_list_v,quote_list_v,job_list_v,visit_list_v,invoice_list_v,payment_list_v,followup_list_v,asset_list_v,recurring_list_v,team_list_v,effective_member_permissions to authenticated;


-- ===== preserved implementation content from historical 0009_arvena_p0_import_export_and_command_hardening.sql =====

-- ARVENA P0 import/export + command hardening.
-- Historical migrations 0001-0008 are intentionally preserved.
set search_path=public,app;

-- Import/export are valid polymorphic media parents, but access still requires
-- the corresponding P0 permission and the row to belong to the active tenant.
create or replace function app.can_access_entity(p_org uuid,p_type text,p_id uuid)
returns boolean language plpgsql stable security definer set search_path=public,app as $$
begin
 case upper(p_type)
 when 'CUSTOMER' then return app.can_view_customer(p_org,p_id);
 when 'LEAD' then return app.can_view_lead(p_org,p_id);
 when 'QUOTE' then return app.can_view_quote(p_org,p_id);
 when 'JOB' then return app.can_view_job(p_org,p_id);
 when 'VISIT' then return app.can_view_visit(p_org,p_id);
 when 'INVOICE' then return app.can_view_invoice(p_org,p_id);
 when 'ASSET' then return app.can_view_asset(p_org,p_id);
 when 'IMPORT' then return exists(
   select 1 from import_jobs j where j.organization_id=p_org and j.id=p_id and
   ((j.kind='CUSTOMERS' and app.has_permission(p_org,'import.customer')) or
    (j.kind='ASSETS_BASIC' and app.has_permission(p_org,'import.asset_basic')))
 );
 when 'EXPORT' then return app.has_permission(p_org,'export.basic') and exists(
   select 1 from export_jobs e where e.organization_id=p_org and e.id=p_id
 );
 else return false;
 end case;
end $$;

-- Re-stage safely while an import is not committed. Upload/retry must not create
-- duplicate logical rows for the same source row.
create or replace function app.stage_import_row(
 p_org uuid,p_job uuid,p_row_number int,p_normalized jsonb,p_errors jsonb,p_duplicate uuid,p_decision text default null
) returns uuid language plpgsql security definer set search_path=public,app as $$
declare j import_jobs%rowtype; rid uuid;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 perform app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if j.status in ('COMMITTING','COMPLETED') then raise exception 'ARV-IMPORT-7002 import is no longer stageable'; end if;
 insert into import_rows(organization_id,import_job_id,source_row,normalized_payload,validation_errors,duplicate_customer_id,duplicate_decision)
 values(p_org,p_job,p_row_number,coalesce(p_normalized,'{}'::jsonb),coalesce(p_errors,'[]'::jsonb),p_duplicate,p_decision)
 on conflict(organization_id,import_job_id,source_row) do update set
   normalized_payload=excluded.normalized_payload,
   validation_errors=excluded.validation_errors,
   duplicate_customer_id=excluded.duplicate_customer_id,
   duplicate_decision=excluded.duplicate_decision,
   updated_at=now()
 where import_rows.commit_state='PENDING'
 returning id into rid;
 if rid is null then
   select id into rid from import_rows where organization_id=p_org and import_job_id=p_job and source_row=p_row_number;
 end if;
 return rid;
end $$;

create or replace function app.update_import_mapping(p_org uuid,p_job uuid,p_mapping jsonb,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; j import_jobs%rowtype; h text; replay jsonb;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 actor:=app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if j.status in ('COMMITTING','COMPLETED') then raise exception 'ARV-IMPORT-7002 import is no longer editable'; end if;
 h:=encode(digest(jsonb_build_array(p_job,coalesce(p_mapping,'{}'::jsonb))::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'import.mapping',p_key,h); if replay is not null then return replay; end if;
 update import_jobs set mapping=coalesce(mapping,'{}'::jsonb)||jsonb_build_object('field_map',coalesce(p_mapping,'{}'::jsonb)),status='MAPPED',updated_at=now() where organization_id=p_org and id=p_job;
 replay:=jsonb_build_object('import_job_id',p_job,'status','MAPPED');
 perform app.idempotency_commit(p_org,actor,'import.mapping',p_key,h,replay);
 return replay;
end $$;

create or replace function app.update_import_row_validation(
 p_org uuid,p_job uuid,p_row_number int,p_normalized jsonb,p_errors jsonb,p_duplicate uuid
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare j import_jobs%rowtype;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 perform app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 update import_rows set normalized_payload=coalesce(p_normalized,'{}'::jsonb),validation_errors=coalesce(p_errors,'[]'::jsonb),duplicate_customer_id=p_duplicate,
   duplicate_decision=case when p_duplicate is null then null else duplicate_decision end,updated_at=now()
 where organization_id=p_org and import_job_id=p_job and source_row=p_row_number and commit_state='PENDING';
 if not found then raise exception 'ARV-IMPORT-7003 import row unavailable'; end if;
 return jsonb_build_object('row',p_row_number,'validated',jsonb_array_length(coalesce(p_errors,'[]'::jsonb))=0);
end $$;

create or replace function app.set_import_duplicate_decision(p_org uuid,p_job uuid,p_row uuid,p_decision text,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; j import_jobs%rowtype; r import_rows%rowtype; h text; replay jsonb;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 actor:=app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if p_decision not in ('USE_EXISTING','CREATE_OVERRIDE','SKIP') then raise exception 'ARV-IMPORT-7004 invalid duplicate decision'; end if;
 select * into r from import_rows where organization_id=p_org and import_job_id=p_job and id=p_row for update;
 if not found or r.duplicate_customer_id is null then raise exception 'ARV-IMPORT-7004 row is not a duplicate'; end if;
 if p_decision='CREATE_OVERRIDE' and not app.has_permission(p_org,'customer.duplicate_override') then raise exception 'ARV-PERM-1001 duplicate override denied'; end if;
 h:=encode(digest(jsonb_build_array(p_job,p_row,p_decision)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'import.duplicate_decision',p_key,h); if replay is not null then return replay; end if;
 update import_rows set duplicate_decision=p_decision,updated_at=now() where organization_id=p_org and id=p_row;
 replay:=jsonb_build_object('row_id',p_row,'decision',p_decision);
 perform app.idempotency_commit(p_org,actor,'import.duplicate_decision',p_key,h,replay);
 return replay;
end $$;

-- Source files/results are system artifacts in a private bucket. They are not
-- exposed by object path and do not consume the customer's durable evidence quota.
create or replace function app.attach_import_source(
 p_org uuid,p_job uuid,p_storage_key text,p_mime text,p_checksum text,p_size bigint,p_key text
) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid; j import_jobs%rowtype; mid uuid; h text; replay jsonb;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 actor:=app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if p_size<=0 or p_size>52428800 then raise exception 'ARV-IMPORT-7005 import source exceeds 50 MB'; end if;
 if p_mime not in ('text/csv','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-excel') then raise exception 'ARV-IMPORT-7005 import MIME not allowed'; end if;
 h:=encode(digest(jsonb_build_array(p_job,p_storage_key,p_checksum,p_size)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'import.source',p_key,h);
 if replay is not null then return (replay->>'media_id')::uuid; end if;
 if j.source_media_id is not null then return j.source_media_id; end if;
 insert into media(organization_id,parent_type,parent_id,category,storage_key,mime_type,checksum,size_bytes,upload_status,quota_reserved_bytes,attempts,uploaded_by)
 values(p_org,'IMPORT',p_job,'IMPORT_SOURCE',p_storage_key,p_mime,p_checksum,p_size,'UPLOADED',0,1,actor) returning id into mid;
 update import_jobs set source_media_id=mid,updated_at=now() where organization_id=p_org and id=p_job;
 replay:=jsonb_build_object('media_id',mid,'import_job_id',p_job);
 perform app.idempotency_commit(p_org,actor,'import.source',p_key,h,replay);
 return mid;
end $$;

create or replace function app.set_import_status(p_org uuid,p_job uuid,p_status text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare j import_jobs%rowtype;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 perform app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if p_status not in ('UPLOADED','MAPPED','VALIDATED','COMMITTING','COMPLETED','FAILED') then raise exception 'ARV-IMPORT-7006 invalid import status'; end if;
 update import_jobs set status=p_status,updated_at=now(),
   valid_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and jsonb_array_length(validation_errors)=0 and duplicate_customer_id is null),
   duplicate_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and duplicate_customer_id is not null),
   error_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and jsonb_array_length(validation_errors)>0),
   committed_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and commit_state='COMMITTED')
 where organization_id=p_org and id=p_job;
 return jsonb_build_object('import_job_id',p_job,'status',p_status);
end $$;

create or replace function app.commit_import_job(p_org uuid,p_job uuid,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; j import_jobs%rowtype; r import_rows%rowtype; h text; replay jsonb; result jsonb; target uuid; created jsonb; err text;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 actor:=app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 h:=encode(digest(jsonb_build_array(p_job,j.mapping,j.schema_version)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'import.commit',p_key,h); if replay is not null then return replay; end if;
 if j.status='COMPLETED' then
   replay:=jsonb_build_object('import_job_id',p_job,'status','COMPLETED','committed_count',j.committed_count,'error_count',j.error_count);
   perform app.idempotency_commit(p_org,actor,'import.commit',p_key,h,replay); return replay;
 end if;
 if exists(select 1 from import_rows where organization_id=p_org and import_job_id=p_job and duplicate_customer_id is not null and duplicate_decision is null and jsonb_array_length(validation_errors)=0) then
   raise exception 'ARV-IMPORT-7007 duplicate decisions are required before commit';
 end if;
 update import_jobs set status='COMMITTING',updated_at=now() where organization_id=p_org and id=p_job;

 for r in select * from import_rows where organization_id=p_org and import_job_id=p_job order by source_row for update loop
   if r.commit_state in ('COMMITTED','SKIPPED') then continue; end if;
   if jsonb_array_length(r.validation_errors)>0 then
     update import_rows set commit_state='ERROR',updated_at=now() where organization_id=p_org and id=r.id;
     continue;
   end if;
   if r.duplicate_customer_id is not null and r.duplicate_decision='SKIP' then
     update import_rows set commit_state='SKIPPED',target_record_id=r.duplicate_customer_id,updated_at=now() where organization_id=p_org and id=r.id;
     continue;
   elsif r.duplicate_customer_id is not null and r.duplicate_decision='USE_EXISTING' then
     update import_rows set commit_state='COMMITTED',target_record_id=r.duplicate_customer_id,updated_at=now() where organization_id=p_org and id=r.id;
     continue;
   end if;

   begin
     if j.kind='CUSTOMERS' then
       created:=app.create_customer(
         p_org,
         coalesce(r.normalized_payload->>'type','PERSON'),
         r.normalized_payload->>'name',
         r.normalized_payload->>'raw_phone',
         r.normalized_payload->>'normalized_phone',
         r.normalized_payload->>'whatsapp_phone',
         r.normalized_payload->>'alternate_phone',
         r.normalized_payload->>'email',
         r.normalized_payload->>'source',
         nullif(r.normalized_payload->>'assigned_sales_id','')::uuid,
         case when r.duplicate_decision='CREATE_OVERRIDE' then r.duplicate_customer_id else null end,
         case when r.duplicate_decision='CREATE_OVERRIDE' then 'Import duplicate override row '||r.source_row::text else null end,
         'import:'||p_job::text||':row:'||r.source_row::text
       );
       if coalesce((created->>'duplicate')::boolean,false) then
         update import_rows set commit_state='ERROR',validation_errors=validation_errors||jsonb_build_array('Duplicate appeared after validation; review and retry.'),updated_at=now() where organization_id=p_org and id=r.id;
         continue;
       end if;
       target:=(created->>'customer_id')::uuid;
       if coalesce(r.normalized_payload->>'line1','')<>'' and not exists(select 1 from customer_addresses where organization_id=p_org and customer_id=target and is_primary) then
         insert into customer_addresses(organization_id,customer_id,label,line1,city,region,postal_code,country_code,formatted_address,is_primary)
         values(p_org,target,'Utama',r.normalized_payload->>'line1',nullif(r.normalized_payload->>'city',''),nullif(r.normalized_payload->>'region',''),nullif(r.normalized_payload->>'postal_code',''),coalesce(nullif(r.normalized_payload->>'country_code',''),'ID'),r.normalized_payload->>'formatted_address',true);
       end if;
     else
       target:=app.create_asset(
         p_org,
         (r.normalized_payload->>'customer_id')::uuid,
         r.normalized_payload->>'asset_type',
         r.normalized_payload->>'name',
         r.normalized_payload->>'brand',
         r.normalized_payload->>'model',
         r.normalized_payload->>'serial_number',
         nullif(r.normalized_payload->>'installed_at','')::date,
         nullif(r.normalized_payload->>'warranty_until','')::date,
         r.normalized_payload->>'notes',
         'import:'||p_job::text||':row:'||r.source_row::text
       );
     end if;
     update import_rows set commit_state='COMMITTED',target_record_id=target,updated_at=now() where organization_id=p_org and id=r.id;
   exception when others then
     err:=sqlerrm;
     update import_rows set commit_state='ERROR',validation_errors=validation_errors||jsonb_build_array(left(err,500)),updated_at=now() where organization_id=p_org and id=r.id;
   end;
 end loop;

 update import_jobs set status='COMPLETED',updated_at=now(),
   valid_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and jsonb_array_length(validation_errors)=0 and duplicate_customer_id is null),
   duplicate_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and duplicate_customer_id is not null),
   error_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and commit_state='ERROR'),
   committed_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and commit_state='COMMITTED')
 where organization_id=p_org and id=p_job returning jsonb_build_object('import_job_id',id,'status',status,'committed_count',committed_count,'error_count',error_count,'duplicate_count',duplicate_count) into result;
 perform app.activity(p_org,actor,'IMPORT',p_job,'import.completed','Import completed',result);
 perform app.emit_event(p_org,actor,'import.completed','IMPORT',p_job,result,'import:'||p_job::text);
 perform app.idempotency_commit(p_org,actor,'import.commit',p_key,h,result);
 return result;
end $$;

-- Export request idempotency verifies that a reused command key carries the same dataset/filter.
create or replace function app.create_export_job(p_org uuid,p_dataset text,p_filter jsonb,p_key text)
returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'export.basic'); eid uuid; existing export_jobs%rowtype; h text; replay jsonb;
begin
 if p_dataset not in ('CUSTOMERS','JOBS','INVOICES','PAYMENTS') then raise exception 'ARV-EXPORT-7101 dataset unavailable'; end if;
 h:=encode(digest(jsonb_build_array(p_dataset,coalesce(p_filter,'{}'::jsonb))::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'export.create',p_key,h); if replay is not null then return (replay->>'export_job_id')::uuid; end if;
 insert into export_jobs(organization_id,actor_member_id,dataset,state,filter,command_key,expires_at)
 values(p_org,actor,p_dataset,'PENDING',coalesce(p_filter,'{}'::jsonb),p_key,now()+interval '24 hours') returning id into eid;
 replay:=jsonb_build_object('export_job_id',eid,'state','PENDING');
 perform app.idempotency_commit(p_org,actor,'export.create',p_key,h,replay);
 return eid;
end $$;

create or replace function app.register_export_result(
 p_org uuid,p_export uuid,p_storage_key text,p_size bigint,p_checksum text,p_key text
) returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'export.basic'); e export_jobs%rowtype; mid uuid; h text; replay jsonb;
begin
 select * into e from export_jobs where organization_id=p_org and id=p_export for update;
 if not found then raise exception 'ARV-EXPORT-7102 export unavailable'; end if;
 h:=encode(digest(jsonb_build_array(p_export,p_storage_key,p_size,p_checksum)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'export.result',p_key,h); if replay is not null then return (replay->>'media_id')::uuid; end if;
 if e.state='READY' and e.result_media_id is not null then return e.result_media_id; end if;
 if e.state not in ('PENDING','FAILED') then raise exception 'ARV-EXPORT-7103 export state does not accept a result'; end if;
 insert into media(organization_id,parent_type,parent_id,category,storage_key,mime_type,checksum,size_bytes,upload_status,quota_reserved_bytes,attempts,uploaded_by)
 values(p_org,'EXPORT',p_export,'EXPORT_RESULT',p_storage_key,'text/csv',p_checksum,p_size,'UPLOADED',0,1,actor) returning id into mid;
 update export_jobs set state='READY',result_media_id=mid,expires_at=now()+interval '24 hours',updated_at=now() where organization_id=p_org and id=p_export;
 replay:=jsonb_build_object('export_job_id',p_export,'media_id',mid,'state','READY');
 perform app.activity(p_org,actor,'EXPORT',p_export,'export.ready','Export is ready');
 perform app.idempotency_commit(p_org,actor,'export.result',p_key,h,replay);
 return mid;
end $$;

create or replace function app.fail_export_job(p_org uuid,p_export uuid,p_error text,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'export.basic');
begin
 update export_jobs set state='FAILED',updated_at=now(),filter=filter||jsonb_build_object('last_error',left(coalesce(p_error,'unknown'),500))
 where organization_id=p_org and id=p_export and state='PENDING';
 perform app.activity(p_org,actor,'EXPORT',p_export,'export.failed','Export failed',jsonb_build_object('error',left(coalesce(p_error,'unknown'),200)));
 return jsonb_build_object('export_job_id',p_export,'state','FAILED');
end $$;

create or replace function app.expire_exports(p_org uuid default null)
returns integer language plpgsql security definer set search_path=public,app as $$
declare n integer;
begin
 if p_org is not null then perform app.require_permission(p_org,'export.basic'); end if;
 update export_jobs set state='EXPIRED',updated_at=now() where state='READY' and expires_at<=now() and (p_org is null or organization_id=p_org);
 get diagnostics n=row_count; return n;
end $$;

-- Application-field mutations go through transactional RPCs so version, activity,
-- audit/outbox behavior is not dependent on direct table updates.
create or replace function app.update_lead_fields(
 p_org uuid,p_lead uuid,p_expected_version int,p_title text,p_description text,p_temperature text,p_source text,p_assigned uuid,p_estimated bigint,p_next_followup timestamptz,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'lead.update'); l leads%rowtype; h text; replay jsonb;
begin
 h:=encode(digest(jsonb_build_array(p_lead,p_expected_version,p_title,p_description,p_temperature,p_source,p_assigned,p_estimated,p_next_followup)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'lead.update_fields',p_key,h); if replay is not null then return replay; end if;
 select * into l from leads where organization_id=p_org and id=p_lead and archived_at is null for update;
 if not found or l.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Lead'; end if;
 if l.status in ('WON') then raise exception 'ARV-STATE-1001 terminal Lead cannot be edited'; end if;
 if p_assigned is not null and not exists(select 1 from organization_members where organization_id=p_org and id=p_assigned and status='ACTIVE') then raise exception 'ARV-TENANT-1003 invalid Sales assignment'; end if;
 update leads set title=trim(p_title),description=p_description,temperature=p_temperature,source=p_source,assigned_sales_id=p_assigned,estimated_value_minor=p_estimated,next_follow_up_at=p_next_followup where organization_id=p_org and id=p_lead;
 replay:=jsonb_build_object('lead_id',p_lead,'version',p_expected_version+1);
 perform app.activity(p_org,actor,'LEAD',p_lead,'lead.updated','Lead updated');
 perform app.emit_event(p_org,actor,'lead.updated','LEAD',p_lead,'{}'::jsonb,p_key);
 perform app.idempotency_commit(p_org,actor,'lead.update_fields',p_key,h,replay); return replay;
end $$;

create or replace function app.update_job_fields(
 p_org uuid,p_job uuid,p_expected_version int,p_title text,p_description text,p_priority text,p_estimated bigint,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'job.update'); j jobs%rowtype; h text; replay jsonb;
begin
 h:=encode(digest(jsonb_build_array(p_job,p_expected_version,p_title,p_description,p_priority,p_estimated)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'job.update_fields',p_key,h); if replay is not null then return replay; end if;
 select * into j from jobs where organization_id=p_org and id=p_job and archived_at is null for update;
 if not found or j.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Job'; end if;
 if j.status in ('COMPLETED','CANCELLED') then raise exception 'ARV-STATE-1001 terminal Job cannot be edited'; end if;
 update jobs set title=trim(p_title),description=p_description,priority=p_priority,estimated_amount_minor=p_estimated where organization_id=p_org and id=p_job;
 replay:=jsonb_build_object('job_id',p_job,'version',p_expected_version+1);
 perform app.activity(p_org,actor,'JOB',p_job,'job.updated','Job updated');
 perform app.emit_event(p_org,actor,'job.updated','JOB',p_job,'{}'::jsonb,p_key);
 perform app.idempotency_commit(p_org,actor,'job.update_fields',p_key,h,replay); return replay;
end $$;

create or replace function app.update_asset_fields(
 p_org uuid,p_asset uuid,p_expected_version int,p_type text,p_name text,p_brand text,p_model text,p_serial text,p_installed date,p_warranty date,p_notes text,p_status text,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'asset.manage'); a assets%rowtype; h text; replay jsonb;
begin
 h:=encode(digest(jsonb_build_array(p_asset,p_expected_version,p_type,p_name,p_brand,p_model,p_serial,p_installed,p_warranty,p_notes,p_status)::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'asset.update_fields',p_key,h); if replay is not null then return replay; end if;
 select * into a from assets where organization_id=p_org and id=p_asset for update;
 if not found or a.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Asset'; end if;
 update assets set asset_type=p_type,name=trim(p_name),brand=p_brand,model=p_model,serial_number=p_serial,installed_at=p_installed,warranty_until=p_warranty,notes=p_notes,status=p_status,
   archived_at=case when p_status='ARCHIVED' then coalesce(archived_at,now()) else archived_at end
 where organization_id=p_org and id=p_asset;
 replay:=jsonb_build_object('asset_id',p_asset,'version',p_expected_version+1,'status',p_status);
 perform app.activity(p_org,actor,'ASSET',p_asset,'asset.updated','Asset updated');
 perform app.emit_event(p_org,actor,'asset.updated','ASSET',p_asset,'{}'::jsonb,p_key);
 perform app.idempotency_commit(p_org,actor,'asset.update_fields',p_key,h,replay); return replay;
end $$;

create or replace function app.update_member_profile(
 p_org uuid,p_member uuid,p_role uuid,p_status text,p_skills jsonb,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'member.update'); result jsonb; skill text; h text; replay jsonb;
begin
 h:=encode(digest(jsonb_build_array(p_member,p_role,p_status,coalesce(p_skills,'[]'::jsonb))::text,'sha256'),'hex');
 replay:=app.idempotency_existing(p_org,actor,'member.update_profile',p_key,h); if replay is not null then return replay; end if;
 result:=app.update_member(p_org,p_member,p_role,p_status,p_key||':member');
 delete from member_skills where organization_id=p_org and member_id=p_member;
 for skill in select value from jsonb_array_elements_text(coalesce(p_skills,'[]'::jsonb)) loop
   if trim(skill)<>'' then insert into member_skills(organization_id,member_id,skill_key,label) values(p_org,p_member,lower(regexp_replace(trim(skill),'[^a-zA-Z0-9]+','_','g')),trim(skill)) on conflict(organization_id,member_id,skill_key) do update set label=excluded.label; end if;
 end loop;
 perform app.idempotency_commit(p_org,actor,'member.update_profile',p_key,h,result); return result;
end $$;

