-- Tenant-wide duplicate/lookup helpers intentionally return only UUIDs and are
-- callable only by authorized import operators, avoiding scoped-list blind spots.
create or replace function app.find_customer_duplicate_for_import(p_org uuid,p_normalized_phone text)
returns uuid language plpgsql stable security definer set search_path=public,app as $$
declare cid uuid;
begin
 if not (app.has_permission(p_org,'import.customer') or app.has_permission(p_org,'import.asset_basic')) then raise exception 'ARV-PERM-1001 import permission required'; end if;
 if p_normalized_phone is null or trim(p_normalized_phone)='' then return null; end if;
 select id into cid from customers where organization_id=p_org and normalized_phone=p_normalized_phone and archived_at is null order by created_at limit 1;
 return cid;
end $$;

create or replace function app.resolve_customer_for_asset_import(p_org uuid,p_customer uuid,p_normalized_phone text)
returns uuid language plpgsql stable security definer set search_path=public,app as $$
declare cid uuid;
begin
 perform app.require_permission(p_org,'import.asset_basic');
 if p_customer is not null then select id into cid from customers where organization_id=p_org and id=p_customer and archived_at is null; end if;
 if cid is null and p_normalized_phone is not null then select id into cid from customers where organization_id=p_org and normalized_phone=p_normalized_phone and archived_at is null order by created_at limit 1; end if;
 return cid;
end $$;

