create or replace function app.stage_import_rows(p_org uuid,p_job uuid,p_rows jsonb)
returns integer language plpgsql security definer set search_path=public,app as $$
declare j import_jobs%rowtype; x jsonb; n integer:=0; rn integer;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 perform app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if jsonb_array_length(coalesce(p_rows,'[]'::jsonb))>5000 then raise exception 'ARV-IMPORT-7009 P0 import batch limit is 5000 rows'; end if;
 for x in select * from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) loop
   rn:=(x->>'source_row')::int;
   insert into import_rows(organization_id,import_job_id,source_row,normalized_payload,validation_errors)
   values(p_org,p_job,rn,jsonb_build_object('_raw',coalesce(x->'raw','{}'::jsonb)),'[]'::jsonb)
   on conflict(organization_id,import_job_id,source_row) do update set normalized_payload=excluded.normalized_payload,validation_errors='[]'::jsonb,duplicate_customer_id=null,duplicate_decision=null,updated_at=now()
   where import_rows.commit_state='PENDING';
   n:=n+1;
 end loop;
 return n;
end $$;

create or replace function app.apply_import_validation_batch(p_org uuid,p_job uuid,p_rows jsonb)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare j import_jobs%rowtype; x jsonb; rn integer; payload jsonb; errors jsonb; dup uuid; cid uuid; count_rows integer:=0;
begin
 select * into j from import_jobs where organization_id=p_org and id=p_job for update;
 if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
 perform app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
 if j.status in ('COMMITTING','COMPLETED') then raise exception 'ARV-IMPORT-7002 import is no longer editable'; end if;
 for x in select * from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) loop
   rn:=(x->>'source_row')::int; payload:=coalesce(x->'payload','{}'::jsonb); errors:=coalesce(x->'errors','[]'::jsonb); dup:=null;
   if j.kind='CUSTOMERS' then
     if coalesce(payload->>'normalized_phone','')<>'' then
       select id into dup from customers where organization_id=p_org and normalized_phone=payload->>'normalized_phone' and archived_at is null order by created_at limit 1;
     end if;
   else
     cid:=null;
     if coalesce(payload->>'customer_id','')<>'' then select id into cid from customers where organization_id=p_org and id=(payload->>'customer_id')::uuid and archived_at is null; end if;
     if cid is null and coalesce(payload->>'customer_phone','')<>'' then select id into cid from customers where organization_id=p_org and normalized_phone=payload->>'customer_phone' and archived_at is null order by created_at limit 1; end if;
     if cid is null then errors:=errors||jsonb_build_array('Customer could not be resolved in this organization'); else payload:=jsonb_set(payload,'{customer_id}',to_jsonb(cid::text),true); end if;
   end if;
   update import_rows set normalized_payload=payload,validation_errors=errors,duplicate_customer_id=dup,duplicate_decision=case when dup is null then null else duplicate_decision end,updated_at=now()
   where organization_id=p_org and import_job_id=p_job and source_row=rn and commit_state='PENDING';
   count_rows:=count_rows+1;
 end loop;
 update import_jobs set status='VALIDATED',updated_at=now(),
   valid_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and jsonb_array_length(validation_errors)=0 and duplicate_customer_id is null),
   duplicate_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and duplicate_customer_id is not null),
   error_count=(select count(*) from import_rows where organization_id=p_org and import_job_id=p_job and jsonb_array_length(validation_errors)>0)
 where organization_id=p_org and id=p_job;
 return jsonb_build_object('import_job_id',p_job,'validated_rows',count_rows);
end $$;

revoke all on function app.stage_import_rows(uuid,uuid,jsonb),app.apply_import_validation_batch(uuid,uuid,jsonb) from public,anon;
grant execute on function app.stage_import_rows(uuid,uuid,jsonb),app.apply_import_validation_batch(uuid,uuid,jsonb) to authenticated;

create or replace function app.create_customer_with_address(
 p_org uuid,p_type text,p_name text,p_raw_phone text,p_normalized_phone text,p_whatsapp text,p_alt text,p_email text,p_source text,p_assigned_sales uuid,p_override_customer uuid,p_override_reason text,
 p_address_label text,p_line1 text,p_city text,p_region text,p_postal text,p_country text,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare result jsonb; cid uuid;
begin
 result:=app.create_customer(p_org,p_type,p_name,p_raw_phone,p_normalized_phone,p_whatsapp,p_alt,p_email,p_source,p_assigned_sales,p_override_customer,p_override_reason,p_key);
 if coalesce((result->>'duplicate')::boolean,false) then return result; end if;
 cid:=(result->>'customer_id')::uuid;
 if coalesce(trim(p_line1),'')<>'' and not exists(select 1 from customer_addresses where organization_id=p_org and customer_id=cid and is_primary) then
   insert into customer_addresses(organization_id,customer_id,label,line1,city,region,postal_code,country_code,formatted_address,is_primary)
   values(p_org,cid,coalesce(nullif(trim(p_address_label),''),'Utama'),trim(p_line1),nullif(trim(p_city),''),nullif(trim(p_region),''),nullif(trim(p_postal),''),coalesce(nullif(upper(trim(p_country)),''),'ID'),concat_ws(', ',trim(p_line1),nullif(trim(p_city),''),nullif(trim(p_region),'')),true);
 end if;
 return result;
end $$;
revoke all on function app.create_customer_with_address(uuid,text,text,text,text,text,text,text,text,uuid,uuid,text,text,text,text,text,text,text,text) from public,anon;
grant execute on function app.create_customer_with_address(uuid,text,text,text,text,text,text,text,text,uuid,uuid,text,text,text,text,text,text,text,text) to authenticated;


-- ===== preserved implementation content from historical 0010_arvena_p0_reporting_and_idempotency_hardening.sql =====

-- ARVENA P0 reporting semantics + remaining command idempotency hardening.
-- Historical migrations 0001-0008 remain unchanged.
set search_path=public,app;

-- An unresolved scheduling conflict is an overlapping pair of active Visits that
-- share an active assigned member and is not covered by an explicit override for
-- the current version of either Visit. The view runs with invoker security so
-- the same RLS/scope predicates as the underlying Visits/assignments apply.
create or replace view public.active_schedule_conflicts_v with (security_invoker=true) as
select distinct
  v1.organization_id,
  v1.id as visit_id,
  v2.id as conflicting_visit_id,
  a1.member_id,
  v1.job_id,
  v2.job_id as conflicting_job_id,
  v1.scheduled_start,
  v1.scheduled_end,
  v2.scheduled_start as conflicting_start,
  v2.scheduled_end as conflicting_end,
  v1.version as visit_version,
  v2.version as conflicting_visit_version
from public.visits v1
join public.visit_assignments a1
  on a1.organization_id=v1.organization_id and a1.visit_id=v1.id and a1.removed_at is null
join public.visit_assignments a2
  on a2.organization_id=a1.organization_id and a2.member_id=a1.member_id and a2.removed_at is null and a2.visit_id<>a1.visit_id
join public.visits v2
  on v2.organization_id=a2.organization_id and v2.id=a2.visit_id
where v1.id < v2.id
  and v1.status not in ('COMPLETED','CANCELLED','NO_SHOW')
  and v2.status not in ('COMPLETED','CANCELLED','NO_SHOW')
  and v1.scheduled_start < v2.scheduled_end
  and v2.scheduled_start < v1.scheduled_end
  and not exists (
    select 1 from public.schedule_conflict_overrides o
    where o.organization_id=v1.organization_id
      and (
        (o.visit_id=v1.id and o.conflicting_visit_id=v2.id and o.visit_version=v1.version)
        or
        (o.visit_id=v2.id and o.conflicting_visit_id=v1.id and o.visit_version=v2.version)
      )
  );

grant select on public.active_schedule_conflicts_v to authenticated;

-- Notification preference changes are state-changing commands and therefore get
-- the same request-hash/idempotency contract as other retryable P0 actions.
create or replace function app.upsert_notification_preference(
  p_org uuid,p_channel text,p_type text,p_enabled boolean,p_timezone text,p_quiet_start time,p_quiet_end time,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'notification.preference_manage'); h text; replay jsonb;
begin
  if p_channel not in ('IN_APP','EMAIL') then raise exception 'ARV-NOTIFY-7301 channel not available in P0'; end if;
  if trim(coalesce(p_type,''))='' then raise exception 'ARV-NOTIFY-7302 notification type required'; end if;
  h:=encode(digest(jsonb_build_array(p_channel,p_type,p_enabled,p_timezone,p_quiet_start,p_quiet_end)::text,'sha256'),'hex');
  replay:=app.idempotency_existing(p_org,actor,'notification.preference',p_key,h); if replay is not null then return replay; end if;
  insert into public.notification_preferences(organization_id,member_id,channel,notification_type,enabled,timezone,quiet_start,quiet_end)
  values(p_org,actor,p_channel,p_type,p_enabled,p_timezone,p_quiet_start,p_quiet_end)
  on conflict(organization_id,member_id,channel,notification_type) do update set
    enabled=excluded.enabled,timezone=excluded.timezone,quiet_start=excluded.quiet_start,quiet_end=excluded.quiet_end,updated_at=now();
  replay:=jsonb_build_object('member_id',actor,'channel',p_channel,'notification_type',p_type,'enabled',p_enabled);
  perform app.activity(p_org,actor,'MEMBER',actor,'notification.preference_updated','Notification preference updated');
  perform app.idempotency_commit(p_org,actor,'notification.preference',p_key,h,replay);
  return replay;
end $$;

drop function if exists app.upsert_notification_preference(uuid,text,text,boolean,text,time,time);
revoke all on function app.upsert_notification_preference(uuid,text,text,boolean,text,time,time,text) from public,anon;
grant execute on function app.upsert_notification_preference(uuid,text,text,boolean,text,time,time,text) to authenticated;

-- Export expiry remains callable only by trusted service execution. This helper
-- exposes a tenant-authorized on-demand check without granting the global worker.
create or replace function app.refresh_export_expiry(p_org uuid,p_export uuid)
returns text language plpgsql security definer set search_path=public,app as $$
declare e public.export_jobs%rowtype;
begin
  perform app.require_permission(p_org,'export.basic');
  select * into e from public.export_jobs where organization_id=p_org and id=p_export for update;
  if not found then raise exception 'ARV-EXPORT-7102 export unavailable'; end if;
  if e.state='READY' and e.expires_at<=now() then
    update public.export_jobs set state='EXPIRED',updated_at=now() where organization_id=p_org and id=p_export;
    return 'EXPIRED';
  end if;
  return e.state;
end $$;
revoke all on function app.refresh_export_expiry(uuid,uuid) from public,anon;
grant execute on function app.refresh_export_expiry(uuid,uuid) to authenticated;

create or replace function app.fail_import_job(p_org uuid,p_job uuid,p_error text,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid; j public.import_jobs%rowtype; h text; replay jsonb;
begin
  select * into j from public.import_jobs where organization_id=p_org and id=p_job for update;
  if not found then raise exception 'ARV-IMPORT-7001 import job unavailable'; end if;
  actor:=app.require_permission(p_org,case j.kind when 'CUSTOMERS' then 'import.customer' else 'import.asset_basic' end);
  h:=encode(digest(jsonb_build_array(p_job,left(coalesce(p_error,'unknown'),500))::text,'sha256'),'hex');
  replay:=app.idempotency_existing(p_org,actor,'import.fail',p_key,h); if replay is not null then return replay; end if;
  if j.status not in ('COMPLETED','COMMITTING') then
    update public.import_jobs set status='FAILED',mapping=coalesce(mapping,'{}'::jsonb)||jsonb_build_object('last_error',left(coalesce(p_error,'unknown'),500)),updated_at=now()
    where organization_id=p_org and id=p_job;
  end if;
  replay:=jsonb_build_object('import_job_id',p_job,'status',(select status from public.import_jobs where organization_id=p_org and id=p_job));
  perform app.activity(p_org,actor,'IMPORT',p_job,'import.failed','Import failed',jsonb_build_object('error',left(coalesce(p_error,'unknown'),200)));
  perform app.idempotency_commit(p_org,actor,'import.fail',p_key,h,replay);
  return replay;
end $$;
revoke all on function app.fail_import_job(uuid,uuid,text,text) from public,anon;
grant execute on function app.fail_import_job(uuid,uuid,text,text) to authenticated;


-- ===== preserved implementation content from historical 0012_arvena_p0_active_org_worker_security.sql =====

-- ARVENA P0 additive security hardening.
-- Historical migrations remain unchanged. This migration binds one active organization to each authenticated request context,
-- removes Worker access to full Customer/Job rows, exposes a minimized execution context, and hardens final-Owner deletion.
set search_path=public,app;

alter table public.user_profiles add column if not exists active_organization_id uuid references public.organizations(id) on delete set null;

create or replace function app.active_organization_id() returns uuid
language sql stable security definer set search_path=public,app as $$
  select up.active_organization_id
  from user_profiles up
  join organization_members m on m.organization_id=up.active_organization_id and m.user_id=up.user_id and m.status='ACTIVE'
  where up.user_id=auth.uid()
  limit 1
$$;

create or replace function app.set_active_organization(p_org uuid) returns uuid
language plpgsql security definer set search_path=public,app as $$
declare u uuid:=auth.uid();
begin
  if u is null then raise exception 'ARV-AUTH-1001 authentication required'; end if;
  if not exists(select 1 from organization_members where organization_id=p_org and user_id=u and status='ACTIVE') then
    raise exception 'ARV-TENANT-1002 active membership required';
  end if;
  insert into user_profiles(user_id,active_organization_id) values(u,p_org)
  on conflict(user_id) do update set active_organization_id=excluded.active_organization_id,updated_at=now();
  return p_org;
end $$;

create or replace function app.list_my_organizations()
returns table(organization_id uuid,name text,slug text,timezone text,currency_code text,is_active boolean)
language sql stable security definer set search_path=public,app as $$
  select o.id,o.name,o.slug,o.timezone,o.currency_code,(o.id=up.active_organization_id)
  from organization_members m
  join organizations o on o.id=m.organization_id and o.status='ACTIVE'
  left join user_profiles up on up.user_id=m.user_id
  where m.user_id=auth.uid() and m.status='ACTIVE'
  order by (o.id=up.active_organization_id) desc,o.name
$$;

create or replace function app.current_member_id(p_org uuid) returns uuid
language sql stable security definer set search_path=public,app as $$
  select m.id
  from organization_members m
  where m.organization_id=p_org
    and p_org=app.active_organization_id()
    and m.user_id=auth.uid()
    and m.status='ACTIVE'
  limit 1
$$;

create or replace function app.current_role_key(p_org uuid) returns text
language sql stable security definer set search_path=public,app as $$
  select r.system_key
  from organization_members m
  join roles r on r.organization_id=m.organization_id and r.id=m.role_id
  where m.id=app.current_member_id(p_org)
  limit 1
$$;

create or replace function app.has_permission(p_org uuid,p_key text) returns boolean
language sql stable security definer set search_path=public,app as $$
  with me as (select id,role_id from organization_members where id=app.current_member_id(p_org)),
  base as (select rp.allowed from role_permissions rp join me on me.role_id=rp.role_id where rp.organization_id=p_org and rp.permission_key=p_key),
  ov as (select effect from member_permission_overrides o join me on me.id=o.member_id where o.organization_id=p_org and o.permission_key=p_key and o.archived_at is null and (o.expires_at is null or o.expires_at>now()) limit 1)
  select case when (select effect from ov)='DENY' then false when (select effect from ov)='ALLOW' then true else coalesce((select allowed from base),false) end
$$;

-- Workers must not read full Customer or Job base rows. Assigned execution context is exposed through a purpose-built function below.
create or replace function app.can_view_customer(p_org uuid,p_customer uuid) returns boolean
language plpgsql stable security definer set search_path=public,app as $$
declare role_key text:=app.current_role_key(p_org); me uuid:=app.current_member_id(p_org);
begin
 if me is null then return false; end if;
 if role_key='WORKER' then return false; end if;
 if role_key in ('OWNER','ADMIN') then return app.has_permission(p_org,'customer.view'); end if;
 if role_key='SALES' then return app.has_permission(p_org,'customer.view') and exists(select 1 from customers c where c.organization_id=p_org and c.id=p_customer and c.assigned_sales_id=me); end if;
 if role_key='SUPERVISOR' then return app.has_permission(p_org,'customer.view') and exists(
   select 1 from jobs j join visits v on v.organization_id=j.organization_id and v.job_id=j.id join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null
   where j.organization_id=p_org and j.customer_id=p_customer and (a.member_id=me or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=me and s.member_id=a.member_id))
 ); end if;
 if role_key='FINANCE' then return app.has_permission(p_org,'customer.view') and exists(select 1 from invoices i where i.organization_id=p_org and i.customer_id=p_customer); end if;
 return false;
end $$;

create or replace function app.can_view_job(p_org uuid,p_job uuid) returns boolean
language plpgsql stable security definer set search_path=public,app as $$
declare role_key text:=app.current_role_key(p_org); me uuid:=app.current_member_id(p_org);
begin
 if me is null or not app.has_permission(p_org,'job.view') then return false; end if;
 if role_key='WORKER' then return false; end if;
 if role_key in ('OWNER','ADMIN') then return true; end if;
 if role_key='SALES' then return exists(select 1 from jobs j join customers c on c.organization_id=j.organization_id and c.id=j.customer_id where j.organization_id=p_org and j.id=p_job and c.assigned_sales_id=me); end if;
 if role_key='SUPERVISOR' then return exists(select 1 from visits v join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null where v.organization_id=p_org and v.job_id=p_job and (a.member_id=me or exists(select 1 from member_team_scope s where s.organization_id=p_org and s.supervisor_member_id=me and s.member_id=a.member_id))); end if;
 return false;
end $$;

create or replace function app.worker_visit_context(p_org uuid,p_visit uuid default null)
returns table(
  visit_id uuid,job_id uuid,job_number text,job_title text,job_description text,priority text,
  visit_status text,scheduled_start timestamptz,scheduled_end timestamptz,timezone text,
  customer_name text,customer_phone text,address_snapshot jsonb,completion_notes text,visit_version integer
)
language sql stable security definer set search_path=public,app as $$
  select v.id,j.id,j.job_number,j.title,j.description,j.priority,v.status,v.scheduled_start,v.scheduled_end,v.timezone,
         c.name,coalesce(c.whatsapp_phone,c.normalized_phone,c.raw_phone),v.address_snapshot,v.completion_notes,v.version
  from visits v
  join jobs j on j.organization_id=v.organization_id and j.id=v.job_id
  join customers c on c.organization_id=j.organization_id and c.id=j.customer_id
  join visit_assignments a on a.organization_id=v.organization_id and a.visit_id=v.id and a.removed_at is null
  where v.organization_id=p_org
    and p_org=app.active_organization_id()
    and a.member_id=app.current_member_id(p_org)
    and app.current_role_key(p_org)='WORKER'
    and app.has_permission(p_org,'visit.view')
    and (p_visit is null or v.id=p_visit)
$$;

-- Allow assigned Worker checklist reads without granting full Job visibility.
drop policy if exists job_checklists_select on job_checklists;
create policy job_checklists_select on job_checklists for select using(
  app.can_view_job(organization_id,job_id)
  or (
    app.current_role_key(organization_id)='WORKER'
    and visit_id is not null
    and app.can_view_visit(organization_id,visit_id)
  )
);

drop policy if exists checklist_responses_select on checklist_responses;
create policy checklist_responses_select on checklist_responses for select using(
  exists(select 1 from job_checklists jc where jc.organization_id=checklist_responses.organization_id and jc.id=job_checklist_id and (
    app.can_view_job(jc.organization_id,jc.job_id)
    or (app.current_role_key(jc.organization_id)='WORKER' and jc.visit_id is not null and app.can_view_visit(jc.organization_id,jc.visit_id))
  ))
);

-- Final Owner invariant must survive both UPDATE and DELETE, including concurrent requests.
create or replace function app.guard_final_owner() returns trigger
language plpgsql security definer set search_path=public,app as $$
declare old_key text; new_key text; active_owners int; losing_owner boolean:=false;
begin
  select system_key into old_key from roles where organization_id=old.organization_id and id=old.role_id;
  if tg_op='DELETE' then
    losing_owner := old.status='ACTIVE' and old_key='OWNER';
  else
    select system_key into new_key from roles where organization_id=new.organization_id and id=new.role_id;
    losing_owner := old.status='ACTIVE' and old_key='OWNER' and (new.status<>'ACTIVE' or new_key<>'OWNER');
  end if;
  if losing_owner then
    perform pg_advisory_xact_lock(hashtextextended(old.organization_id::text,0));
    select count(*) into active_owners from organization_members m join roles r on r.organization_id=m.organization_id and r.id=m.role_id
      where m.organization_id=old.organization_id and m.status='ACTIVE' and r.system_key='OWNER' and m.id<>old.id;
    if active_owners<1 then raise exception 'ARV-TENANT-1003 final active Owner cannot be removed, disabled or demoted'; end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;

drop trigger if exists trg_final_owner on public.organization_members;
create trigger trg_final_owner before update or delete on public.organization_members for each row execute function app.guard_final_owner();

revoke all on function app.active_organization_id() from public,anon;
revoke all on function app.set_active_organization(uuid) from public,anon;
revoke all on function app.list_my_organizations() from public,anon;
revoke all on function app.worker_visit_context(uuid,uuid) from public,anon;
grant execute on function app.active_organization_id(),app.set_active_organization(uuid),app.list_my_organizations(),app.worker_visit_context(uuid,uuid) to authenticated;



-- ===== canonical P0 command-contract completion (direct definitions; no fake historical renames) =====
set search_path=public,app;

create or replace function app.command_hash(p_payload jsonb) returns text
language sql immutable set search_path=public,app as $$
  select encode(digest(coalesce(p_payload,'null'::jsonb)::text,'sha256'),'hex')
$$;

create or replace function app.command_lock(p_org uuid,p_scope text,p_key text) returns void
language plpgsql security definer set search_path=public,app as $$
begin
  if coalesce(trim(p_key),'')='' then raise exception 'ARV-CONFLICT-1001 idempotency key required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text||':'||p_scope||':'||p_key,17));
end $$;

create or replace function app.create_note(p_org uuid,p_entity_type text,p_entity_id uuid,p_body text,p_visibility text,p_key text) returns uuid
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'note.create'); h text; replay jsonb; nid uuid:=gen_random_uuid();
begin
  if coalesce(trim(p_body),'')='' then raise exception 'ARV-VALIDATION-1001 note body required'; end if;
  if not app.can_access_entity(p_org,p_entity_type,p_entity_id) then raise exception 'ARV-PERM-1001 entity scope denied'; end if;
  h:=app.command_hash(jsonb_build_array(p_entity_type,p_entity_id,p_body,p_visibility));
  perform app.command_lock(p_org,'note.create',p_key);
  replay:=app.idempotency_existing(p_org,actor,'note.create',p_key,h);
  if replay is not null then return (replay->>'note_id')::uuid; end if;
  insert into notes(id,organization_id,entity_type,entity_id,body,visibility,author_id)
  values(nid,p_org,upper(p_entity_type),p_entity_id,p_body,coalesce(upper(p_visibility),'OPERATIONAL'),actor);
  perform app.activity(p_org,actor,upper(p_entity_type),p_entity_id,'note.created','Note added',jsonb_build_object('note_id',nid));
  perform app.emit_event(p_org,actor,'note.created',upper(p_entity_type),p_entity_id,jsonb_build_object('note_id',nid),p_key);
  perform app.idempotency_commit(p_org,actor,'note.create',p_key,h,jsonb_build_object('note_id',nid));
  return nid;
end $$;

create or replace function app.respond_checklist(p_org uuid,p_checklist uuid,p_item_key text,p_value jsonb,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'checklist.respond_assigned'); jc job_checklists%rowtype; h text; replay jsonb; required_count int; completed_count int;
begin
  select * into jc from job_checklists where organization_id=p_org and id=p_checklist for update;
  if not found then raise exception 'ARV-VISIT-4001 checklist not found'; end if;
  if not (app.can_view_job(p_org,jc.job_id) or (jc.visit_id is not null and app.can_view_visit(p_org,jc.visit_id))) then raise exception 'ARV-PERM-1001 checklist scope denied'; end if;
  h:=app.command_hash(jsonb_build_array(p_checklist,p_item_key,p_value)); perform app.command_lock(p_org,'checklist.respond',p_key);
  replay:=app.idempotency_existing(p_org,actor,'checklist.respond',p_key,h); if replay is not null then return replay; end if;
  if not exists(select 1 from jsonb_array_elements(coalesce(jc.template_snapshot->'items','[]'::jsonb)) item where item->>'item_key'=p_item_key) then
    raise exception 'ARV-VALIDATION-1001 unknown checklist item';
  end if;
  insert into checklist_responses(organization_id,job_checklist_id,template_item_key,value,completed_by)
  values(p_org,p_checklist,p_item_key,coalesce(p_value,'null'::jsonb),actor)
  on conflict(organization_id,job_checklist_id,template_item_key) do update set value=excluded.value,completed_by=excluded.completed_by,completed_at=now(),updated_at=now();
  select count(*) into required_count from jsonb_array_elements(coalesce(jc.template_snapshot->'items','[]'::jsonb)) item where coalesce((item->>'required')::boolean,false);
  select count(*) into completed_count from checklist_responses cr where cr.organization_id=p_org and cr.job_checklist_id=p_checklist and exists(select 1 from jsonb_array_elements(coalesce(jc.template_snapshot->'items','[]'::jsonb)) item where item->>'item_key'=cr.template_item_key and coalesce((item->>'required')::boolean,false));
  update job_checklists set status=case when required_count=0 or completed_count>=required_count then 'COMPLETE' else 'IN_PROGRESS' end where organization_id=p_org and id=p_checklist;
  perform app.activity(p_org,actor,'JOB',jc.job_id,'checklist.responded','Checklist response saved',jsonb_build_object('checklist_id',p_checklist,'item_key',p_item_key));
  perform app.idempotency_commit(p_org,actor,'checklist.respond',p_key,h,jsonb_build_object('checklist_id',p_checklist,'item_key',p_item_key));
  return jsonb_build_object('checklist_id',p_checklist,'item_key',p_item_key,'status',case when required_count=0 or completed_count>=required_count then 'COMPLETE' else 'IN_PROGRESS' end);
end $$;

create or replace function app.fail_media(p_org uuid,p_media uuid,p_error text,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'media.retry'); m media%rowtype; h text; replay jsonb;
begin
  h:=app.command_hash(jsonb_build_array(p_media,p_error)); perform app.command_lock(p_org,'media.fail',p_key);
  replay:=app.idempotency_existing(p_org,actor,'media.fail',p_key,h); if replay is not null then return replay; end if;
  select * into m from media where organization_id=p_org and id=p_media for update; if not found then raise exception 'ARV-MEDIA-5001 media not found'; end if;
  if m.upload_status='UPLOADED' then return jsonb_build_object('media_id',p_media,'status','UPLOADED'); end if;
  update media set upload_status='FAILED',error_code=left(coalesce(p_error,'UPLOAD_FAILED'),120),attempts=attempts+1,quota_reserved_bytes=0 where organization_id=p_org and id=p_media;
  update usage_counters set reserved=greatest(0,reserved-m.quota_reserved_bytes),version=version+1 where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now();
  perform app.idempotency_commit(p_org,actor,'media.fail',p_key,h,jsonb_build_object('media_id',p_media,'status','FAILED'));
  return jsonb_build_object('media_id',p_media,'status','FAILED');
end $$;

create or replace function app.retry_media(p_org uuid,p_media uuid,p_expected_checksum text,p_size bigint,p_mime text,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'media.retry'); m media%rowtype; h text; replay jsonb; lim bigint; used bigint;
begin
  h:=app.command_hash(jsonb_build_array(p_media,p_expected_checksum,p_size,p_mime)); perform app.command_lock(p_org,'media.retry',p_key);
  replay:=app.idempotency_existing(p_org,actor,'media.retry',p_key,h); if replay is not null then return replay; end if;
  select * into m from media where organization_id=p_org and id=p_media for update; if not found or m.upload_status<>'FAILED' then raise exception 'ARV-STATE-1001 failed media required'; end if;
  if p_expected_checksum is distinct from m.checksum then raise exception 'ARV-MEDIA-5001 checksum replacement requires new media record'; end if;
  if p_size<>m.size_bytes or p_mime<>m.mime_type then raise exception 'ARV-MEDIA-5001 size/MIME mismatch'; end if;
  lim:=app.limit_value(p_org,'limit.storage_bytes'); select coalesce(value+reserved,0) into used from usage_counters where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now() for update;
  if used+p_size>lim then raise exception 'ARV-USAGE-6001 storage limit reached'; end if;
  update usage_counters set reserved=reserved+p_size,version=version+1 where organization_id=p_org and metric_key='storage_bytes' and period_start<=now() and period_end>now();
  update media set upload_status='UPLOADING',quota_reserved_bytes=p_size,error_code=null,attempts=attempts+1 where organization_id=p_org and id=p_media;
  perform app.idempotency_commit(p_org,actor,'media.retry',p_key,h,jsonb_build_object('media_id',p_media,'status','UPLOADING'));
  return jsonb_build_object('media_id',p_media,'status','UPLOADING');
end $$;

create or replace function app.update_organization_business(p_org uuid,p_name text,p_business_address jsonb,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'organization.manage'); h text; replay jsonb;
begin h:=app.command_hash(jsonb_build_array(p_name,p_business_address)); perform app.command_lock(p_org,'settings.business',p_key); replay:=app.idempotency_existing(p_org,actor,'settings.business',p_key,h); if replay is not null then return replay; end if;
 update organizations set name=p_name where id=p_org; update organization_settings set business_address=coalesce(p_business_address,'{}') where organization_id=p_org; perform app.audit(p_org,actor,'settings.business','ORGANIZATION',p_org,null,jsonb_build_object('name',p_name)); perform app.idempotency_commit(p_org,actor,'settings.business',p_key,h,jsonb_build_object('organization_id',p_org)); return jsonb_build_object('organization_id',p_org); end $$;

create or replace function app.update_localization(p_org uuid,p_country text,p_currency text,p_timezone text,p_locale text,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'settings.localization'); h text; replay jsonb;
begin h:=app.command_hash(jsonb_build_array(p_country,p_currency,p_timezone,p_locale)); perform app.command_lock(p_org,'settings.localization',p_key); replay:=app.idempotency_existing(p_org,actor,'settings.localization',p_key,h); if replay is not null then return replay; end if;
 if not exists(select 1 from currency_definitions where currency_code=p_currency and active) then raise exception 'ARV-VALIDATION-1001 unsupported currency'; end if;
 update organizations set country_code=upper(p_country),currency_code=upper(p_currency),timezone=p_timezone,locale=p_locale where id=p_org; perform app.audit(p_org,actor,'settings.localization','ORGANIZATION',p_org,null,jsonb_build_object('country',p_country,'currency',p_currency,'timezone',p_timezone,'locale',p_locale)); perform app.idempotency_commit(p_org,actor,'settings.localization',p_key,h,jsonb_build_object('organization_id',p_org)); return jsonb_build_object('organization_id',p_org); end $$;

create or replace function app.update_workflow_settings(p_org uuid,p_workflow jsonb,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'settings.workflow'); h text; replay jsonb;
begin h:=app.command_hash(coalesce(p_workflow,'{}')); perform app.command_lock(p_org,'settings.workflow',p_key); replay:=app.idempotency_existing(p_org,actor,'settings.workflow',p_key,h); if replay is not null then return replay; end if;
 update organization_settings set workflow=coalesce(p_workflow,'{}') where organization_id=p_org; perform app.audit(p_org,actor,'settings.workflow','ORGANIZATION',p_org,null,p_workflow); perform app.idempotency_commit(p_org,actor,'settings.workflow',p_key,h,jsonb_build_object('organization_id',p_org)); return jsonb_build_object('organization_id',p_org); end $$;

create or replace function app.update_tax_profile(p_org uuid,p_name text,p_rate_ppm int,p_behavior text,p_key text) returns uuid
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'settings.tax'); h text; replay jsonb; tid uuid;
begin h:=app.command_hash(jsonb_build_array(p_name,p_rate_ppm,p_behavior)); perform app.command_lock(p_org,'settings.tax',p_key); replay:=app.idempotency_existing(p_org,actor,'settings.tax',p_key,h); if replay is not null then return (replay->>'tax_profile_id')::uuid; end if;
 if p_rate_ppm<0 or p_rate_ppm>1000000 or p_behavior not in('EXCLUSIVE','INCLUSIVE','EXEMPT') then raise exception 'ARV-VALIDATION-1001 invalid tax profile'; end if;
 update tax_profiles set active=false where organization_id=p_org and active; insert into tax_profiles(organization_id,name,rate_ppm,tax_behavior,active,version) values(p_org,p_name,p_rate_ppm,p_behavior,true,1) returning id into tid;
 perform app.audit(p_org,actor,'settings.tax','ORGANIZATION',p_org,null,jsonb_build_object('tax_profile_id',tid,'rate_ppm',p_rate_ppm)); perform app.idempotency_commit(p_org,actor,'settings.tax',p_key,h,jsonb_build_object('tax_profile_id',tid)); return tid; end $$;

create or replace function app.set_role_permission(p_org uuid,p_role uuid,p_permission text,p_allowed boolean,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'role.assign'); h text; replay jsonb;
begin h:=app.command_hash(jsonb_build_array(p_role,p_permission,p_allowed)); perform app.command_lock(p_org,'role.permission',p_key); replay:=app.idempotency_existing(p_org,actor,'role.permission',p_key,h); if replay is not null then return replay; end if;
 if not exists(select 1 from roles where organization_id=p_org and id=p_role) then raise exception 'ARV-TENANT-1003 role mismatch'; end if;
 insert into role_permissions(organization_id,role_id,permission_key,allowed) values(p_org,p_role,p_permission,p_allowed) on conflict(organization_id,role_id,permission_key) do update set allowed=excluded.allowed;
 perform app.audit(p_org,actor,'role.permission','ORGANIZATION',p_org,null,jsonb_build_object('role_id',p_role,'permission',p_permission,'allowed',p_allowed)); perform app.idempotency_commit(p_org,actor,'role.permission',p_key,h,jsonb_build_object('role_id',p_role,'permission',p_permission,'allowed',p_allowed)); return jsonb_build_object('role_id',p_role,'permission',p_permission,'allowed',p_allowed); end $$;

create or replace function app.set_industry_template(p_org uuid,p_template_version uuid,p_key text) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'organization.manage'); h text; replay jsonb;
begin h:=app.command_hash(jsonb_build_array(p_template_version)); perform app.command_lock(p_org,'organization.template',p_key); replay:=app.idempotency_existing(p_org,actor,'organization.template',p_key,h); if replay is not null then return replay; end if;
 if not exists(select 1 from industry_template_versions where id=p_template_version) then raise exception 'ARV-VALIDATION-1001 template version missing'; end if;
 update organizations set industry_template_version_id=p_template_version where id=p_org; perform app.idempotency_commit(p_org,actor,'organization.template',p_key,h,jsonb_build_object('organization_id',p_org,'template_version_id',p_template_version)); return jsonb_build_object('organization_id',p_org,'template_version_id',p_template_version); end $$;

-- Server-authoritative offline action batch processor. Each client action is retained even on conflict/rejection.
create or replace function app.process_client_actions(p_org uuid,p_device_id text,p_actions jsonb) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_member(p_org); item jsonb; existing client_action_receipts%rowtype; result jsonb; outcome text; err text; out jsonb:='[]'::jsonb; cid uuid; seq bigint; et text; eid uuid; act text; expected int; ph text; localts timestamptz; deps jsonb;
begin
 if jsonb_typeof(p_actions)<>'array' then raise exception 'ARV-OFFLINE-7001 actions must be array'; end if;
 for item in select * from jsonb_array_elements(p_actions) loop
   cid:=(item->>'client_action_id')::uuid; seq:=(item->>'sequence')::bigint; et:=upper(item->>'entity_type'); eid:=(item->>'entity_id')::uuid; act:=upper(item->>'action'); expected:=nullif(item->>'expected_version','')::int; ph:=coalesce(item->>'payload_hash',app.command_hash(item->'payload')); localts:=nullif(item->>'local_occurred_at','')::timestamptz; deps:=coalesce(item->'dependencies','[]'::jsonb);
   select * into existing from client_action_receipts where organization_id=p_org and member_id=actor and device_id=p_device_id and client_action_id=cid;
   if found then
     if existing.payload_hash<>ph then raise exception 'ARV-CONFLICT-1001 offline action payload mismatch'; end if;
     out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'result','DUPLICATE','response',existing.response)); continue;
   end if;
   outcome:='REJECTED'; result:=null; err:=null;
   begin
     if et='VISIT' and act in('DEPART','ARRIVE','START','FINISH','CANCEL','NO_SHOW') then
       result:=app.visit_action(p_org,eid,act,expected,item->>'reason',cid::text); outcome:='APPLIED';
     elsif et='CHECKLIST' and act='RESPOND' then
       result:=app.respond_checklist(p_org,eid,item->>'item_key',item->'payload',cid::text); outcome:='APPLIED';
     elsif act='NOTE' then
       result:=jsonb_build_object('note_id',app.create_note(p_org,et,eid,coalesce(item->'payload'->>'body',''),coalesce(item->'payload'->>'visibility','WORKER'),cid::text)); outcome:='APPLIED';
     else err:='ARV-OFFLINE-7002 unsupported action'; outcome:='REJECTED'; end if;
   exception when serialization_failure or deadlock_detected then outcome:='RETRYABLE'; err:=sqlerrm;
             when others then if sqlerrm like '%ARV-CONFLICT-%' then outcome:='CONFLICT'; elsif sqlerrm like '%permission%' or sqlerrm like '%ARV-PERM-%' or sqlerrm like '%ARV-TENANT-%' then outcome:='REJECTED'; else outcome:='REJECTED'; end if; err:=sqlerrm;
   end;
   insert into client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
   values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,result,left(err,120));
   out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'result',outcome,'response',result,'error',err));
 end loop;
 return out;
end $$;

