-- ===== final P0 application-surface hardening =====
-- Expand trusted polymorphic validation to operational identity/settings targets used by audit/activity.
create or replace function app.entity_belongs_to_org(p_org uuid,p_type text,p_id uuid) returns boolean
language plpgsql stable security definer set search_path=public,app as $$
begin
  case upper(p_type)
    when 'ORGANIZATION' then return p_id=p_org and exists(select 1 from organizations where id=p_org);
    when 'MEMBER' then return exists(select 1 from organization_members where organization_id=p_org and id=p_id);
    when 'INVITATION' then return exists(select 1 from organization_invitations where organization_id=p_org and id=p_id);
    when 'CUSTOMER' then return exists(select 1 from customers where organization_id=p_org and id=p_id);
    when 'LEAD' then return exists(select 1 from leads where organization_id=p_org and id=p_id);
    when 'QUOTE' then return exists(select 1 from quotes where organization_id=p_org and id=p_id);
    when 'JOB' then return exists(select 1 from jobs where organization_id=p_org and id=p_id);
    when 'VISIT' then return exists(select 1 from visits where organization_id=p_org and id=p_id);
    when 'INVOICE' then return exists(select 1 from invoices where organization_id=p_org and id=p_id);
    when 'ASSET' then return exists(select 1 from assets where organization_id=p_org and id=p_id);
    when 'IMPORT' then return exists(select 1 from import_jobs where organization_id=p_org and id=p_id);
    when 'EXPORT' then return exists(select 1 from export_jobs where organization_id=p_org and id=p_id);
    else return false;
  end case;
end $$;

create or replace function app.update_customer(
 p_org uuid,p_customer uuid,p_expected_version int,p_type text,p_name text,p_raw_phone text,p_normalized_phone text,p_whatsapp text,p_alt text,p_email text,p_source text,p_assigned_sales uuid,p_override_customer uuid,p_override_reason text,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'customer.update'); c customers%rowtype; duplicate_id uuid; h text; replay jsonb; result jsonb;
begin
 h:=app.command_hash(jsonb_build_array(p_customer,p_expected_version,p_type,p_name,p_raw_phone,p_normalized_phone,p_whatsapp,p_alt,p_email,p_source,p_assigned_sales,p_override_customer,p_override_reason));
 perform app.command_lock(p_org,'customer.update:'||p_customer::text,p_key);
 replay:=app.idempotency_existing(p_org,actor,'customer.update',p_key,h); if replay is not null then return replay; end if;
 select * into c from customers where organization_id=p_org and id=p_customer and archived_at is null for update;
 if not found then raise exception 'ARV-CUSTOMER-2001 customer unavailable'; end if;
 if c.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Customer'; end if;
 if upper(coalesce(p_type,'')) not in ('PERSON','COMPANY') or trim(coalesce(p_name,''))='' then raise exception 'ARV-VALIDATION-1001 invalid customer identity'; end if;
 if p_assigned_sales is not null and not exists(select 1 from organization_members where organization_id=p_org and id=p_assigned_sales and status='ACTIVE') then raise exception 'ARV-TENANT-1003 invalid Sales assignment'; end if;
 if p_normalized_phone is not null then
   select id into duplicate_id from customers where organization_id=p_org and normalized_phone=p_normalized_phone and archived_at is null and id<>p_customer order by created_at limit 1;
 end if;
 if duplicate_id is not null then
   if p_override_customer is distinct from duplicate_id or coalesce(trim(p_override_reason),'')='' or not app.has_permission(p_org,'customer.duplicate_override') then
     raise exception 'ARV-CUSTOMER-2002 possible duplicate customer %',duplicate_id;
   end if;
 end if;
 update customers set type=upper(p_type),name=trim(p_name),raw_phone=p_raw_phone,normalized_phone=p_normalized_phone,whatsapp_phone=p_whatsapp,alternate_phone=p_alt,email=nullif(trim(coalesce(p_email,'')),''),source=p_source,assigned_sales_id=p_assigned_sales,
   duplicate_of_customer_id=case when duplicate_id is not null then duplicate_id else null end,
   duplicate_override_reason=case when duplicate_id is not null then p_override_reason else null end,
   duplicate_override_by=case when duplicate_id is not null then actor else null end,updated_by=actor
 where organization_id=p_org and id=p_customer;
 result:=jsonb_build_object('customer_id',p_customer,'version',p_expected_version+1,'duplicate_of_customer_id',duplicate_id);
 perform app.activity(p_org,actor,'CUSTOMER',p_customer,'customer.updated','Customer updated');
 perform app.audit(p_org,actor,'customer.updated','CUSTOMER',p_customer,to_jsonb(c)-'metadata',jsonb_build_object('name',trim(p_name),'type',upper(p_type),'normalized_phone',p_normalized_phone,'source',p_source));
 perform app.emit_event(p_org,actor,'customer.updated','CUSTOMER',p_customer,'{}'::jsonb,p_key);
 perform app.idempotency_commit(p_org,actor,'customer.update',p_key,h,result); return result;
end $$;

create or replace function app.archive_customer(p_org uuid,p_customer uuid,p_expected_version int,p_reason text,p_key text)
returns jsonb language plpgsql security definer set search_path=public,app as $$
declare actor uuid:=app.require_permission(p_org,'customer.archive'); c customers%rowtype; h text; replay jsonb; result jsonb;
begin
 h:=app.command_hash(jsonb_build_array(p_customer,p_expected_version,p_reason)); perform app.command_lock(p_org,'customer.archive:'||p_customer::text,p_key);
 replay:=app.idempotency_existing(p_org,actor,'customer.archive',p_key,h); if replay is not null then return replay; end if;
 select * into c from customers where organization_id=p_org and id=p_customer for update;
 if not found or c.version<>p_expected_version then raise exception 'ARV-CONFLICT-1001 stale Customer'; end if;
 if coalesce(trim(p_reason),'')='' then raise exception 'ARV-VALIDATION-1001 archive reason required'; end if;
 update customers set status='ARCHIVED',archived_at=coalesce(archived_at,now()),updated_by=actor where organization_id=p_org and id=p_customer;
 result:=jsonb_build_object('customer_id',p_customer,'status','ARCHIVED','version',p_expected_version+1);
 perform app.activity(p_org,actor,'CUSTOMER',p_customer,'customer.archived','Customer archived',jsonb_build_object('reason',p_reason));
 perform app.audit(p_org,actor,'customer.archived','CUSTOMER',p_customer,jsonb_build_object('status',c.status),jsonb_build_object('status','ARCHIVED','reason',p_reason));
 perform app.idempotency_commit(p_org,actor,'customer.archive',p_key,h,result); return result;
end $$;

create or replace function app.create_import_job(p_org uuid,p_kind text,p_key text)
returns uuid language plpgsql security definer set search_path=public,app as $$
declare actor uuid; iid uuid; kind text:=upper(p_kind); h text; replay jsonb;
begin
 if kind='CUSTOMERS' then actor:=app.require_permission(p_org,'import.customer'); elsif kind='ASSETS_BASIC' then actor:=app.require_permission(p_org,'import.asset_basic'); else raise exception 'ARV-IMPORT-7001 unsupported import kind'; end if;
 h:=app.command_hash(jsonb_build_array(kind)); perform app.command_lock(p_org,'import.create',p_key); replay:=app.idempotency_existing(p_org,actor,'import.create',p_key,h); if replay is not null then return (replay->>'import_job_id')::uuid; end if;
 insert into import_jobs(organization_id,actor_member_id,kind,status,command_key) values(p_org,actor,kind,'UPLOADED',p_key) returning id into iid;
 perform app.idempotency_commit(p_org,actor,'import.create',p_key,h,jsonb_build_object('import_job_id',iid)); return iid;
end $$;

create or replace function app.navigation_context(p_org uuid) returns jsonb language plpgsql stable security definer set search_path=public,app as $$
declare mid uuid:=app.require_member(p_org); role_key text:=app.current_role_key(p_org); perms jsonb; modules jsonb; plan text; usage jsonb;
begin
 select coalesce(jsonb_agg(permission_key order by permission_key),'[]'::jsonb) into perms from effective_member_permissions where organization_id=p_org and member_id=mid and allowed;
 select coalesce(jsonb_object_agg(module_key,enabled),'{}'::jsonb) into modules from organization_modules where organization_id=p_org;
 select pv.plan_key into plan from subscriptions s join plan_versions pv on pv.id=s.plan_version_id where s.organization_id=p_org and s.status in('TRIALING','ACTIVE','PAST_DUE') order by s.created_at desc limit 1;
 select coalesce(jsonb_object_agg(metric_key,jsonb_build_object('value',value,'reserved',reserved)),'{}'::jsonb) into usage from usage_counters where organization_id=p_org and period_start<=now() and period_end>now();
 return jsonb_build_object('member_id',mid,'role',role_key,'permissions',perms,'modules',modules,'plan',plan,'usage',usage);
end $$;

revoke all on function app.update_customer(uuid,uuid,int,text,text,text,text,text,text,text,text,uuid,uuid,text,text),app.archive_customer(uuid,uuid,int,text,text),app.create_import_job(uuid,text,text),app.navigation_context(uuid) from public,anon;
grant execute on function app.update_customer(uuid,uuid,int,text,text,text,text,text,text,text,text,uuid,uuid,text,text),app.archive_customer(uuid,uuid,int,text,text),app.create_import_job(uuid,text,text),app.navigation_context(uuid) to authenticated;

-- First allocation must return sequence value 1 on an empty document sequence.
create or replace function app.next_document_number(p_org uuid,p_type text) returns text language plpgsql security definer set search_path=public,app as $$
declare tz text; year_key text; v bigint; prefix text;
begin
 select timezone into tz from organizations where id=p_org; if tz is null then raise exception 'ARV-TENANT-1002 organization unavailable'; end if;
 year_key:=to_char(now() at time zone tz,'YYYY'); prefix:=case p_type when 'JOB' then 'JOB' when 'QUOTE' then 'QTE' when 'INVOICE' then 'INV' else 'DOC' end;
 insert into document_sequences(organization_id,document_type,period_key,next_value) values(p_org,p_type,year_key,2)
 on conflict(organization_id,document_type,period_key) do update set next_value=document_sequences.next_value+1
 returning next_value-1 into v;
 return prefix||'-'||year_key||'-'||lpad(v::text,6,'0');
end $$;


