-- Server-authoritative recurrence date validation. This helper is internal/service-only.
create or replace function app.recurring_date_matches_rule(p_org uuid,p_rule uuid,p_local_date date)
returns boolean language plpgsql stable security definer set search_path=public,app as $$
declare r public.recurring_rules%rowtype; month_delta int; year_delta int; week_delta int; iso_dow int;
begin
  select * into r from public.recurring_rules where organization_id=p_org and id=p_rule;
  if not found or p_local_date<r.starts_on or (r.ends_on is not null and p_local_date>r.ends_on) then return false; end if;
  case r.recurrence_type
    when 'DAILY' then return ((p_local_date-r.starts_on) % r.interval_value)=0;
    when 'CUSTOM_DAYS' then return ((p_local_date-r.starts_on) % r.interval_value)=0;
    when 'WEEKLY' then
      week_delta:=floor((p_local_date-r.starts_on)/7.0)::int;
      if week_delta<0 or (week_delta % r.interval_value)<>0 then return false; end if;
      iso_dow:=extract(isodow from p_local_date)::int;
      if jsonb_typeof(r.weekday_config)='array' and jsonb_array_length(r.weekday_config)>0 then
        return exists(select 1 from jsonb_array_elements_text(r.weekday_config) x(v) where x.v::int=iso_dow);
      end if;
      return iso_dow=extract(isodow from r.starts_on)::int;
    when 'MONTHLY' then
      month_delta:=(extract(year from p_local_date)::int-extract(year from r.starts_on)::int)*12 + extract(month from p_local_date)::int-extract(month from r.starts_on)::int;
      return month_delta>=0 and (month_delta % r.interval_value)=0 and extract(day from p_local_date)::int=extract(day from r.starts_on)::int;
    when 'YEARLY' then
      year_delta:=extract(year from p_local_date)::int-extract(year from r.starts_on)::int;
      return year_delta>=0 and (year_delta % r.interval_value)=0 and extract(month from p_local_date)=extract(month from r.starts_on) and extract(day from p_local_date)=extract(day from r.starts_on);
    else return false;
  end case;
end $$;

-- Resolve a local recurrence on the server. It searches real timezone transitions so a gap is shifted
-- to the first valid local minute and an overlap chooses the earlier UTC instant.
create or replace function app.resolve_recurring_local_time(p_timezone text,p_local_date date,p_local_time time)
returns table(resolved_at timestamptz,resolved_offset_minutes int,dst_resolution text,resolved_local timestamp)
language plpgsql stable security definer set search_path=public,app as $$
declare intended timestamp:=p_local_date+p_local_time; candidate_local timestamp:=intended; default_utc timestamptz; hits int; chosen timestamptz; i int;
begin
  if not exists(select 1 from pg_timezone_names where name=p_timezone) then raise exception 'ARV-RECUR-7601 invalid timezone'; end if;
  -- Find the earliest valid local minute at/after intended. At most a three-hour civil-time gap is tolerated.
  for i in 0..180 loop
    candidate_local:=intended+make_interval(mins=>i);
    default_utc:=candidate_local at time zone p_timezone;
    if (default_utc at time zone p_timezone)=candidate_local then exit; end if;
    if i=180 then raise exception 'ARV-RECUR-7602 unable to resolve local time'; end if;
  end loop;
  select count(*),min(g) into hits,chosen
    from generate_series(default_utc-interval '3 hours',default_utc+interval '3 hours',interval '1 minute') g
    where (g at time zone p_timezone)=candidate_local;
  if chosen is null then raise exception 'ARV-RECUR-7602 unable to resolve local time'; end if;
  resolved_at:=chosen;
  resolved_local:=candidate_local;
  resolved_offset_minutes:=round(extract(epoch from (candidate_local-(chosen at time zone 'UTC')))/60)::int;
  dst_resolution:=case when candidate_local<>intended then 'DST_GAP_SHIFTED' when hits>1 then 'DST_OVERLAP_EARLIER_OFFSET' else 'EXACT' end;
  return next;
end $$;

-- Supersede the caller-resolved recurrence overload. Canonical resolution is now performed entirely by trusted code.
drop function if exists app.generate_recurring_occurrence(uuid,uuid,date,time,timestamptz,int,text,int,jsonb,text);
create or replace function app.generate_recurring_occurrence(
  p_org uuid,p_rule uuid,p_local_date date,p_generation_reference timestamptz,p_key text
) returns jsonb language plpgsql security definer set search_path=public,app as $$
declare r public.recurring_rules%rowtype; rr record; occ uuid; jid uuid; vid uuid; actor uuid:=null; identity_key text; duration_minutes int; snapshot jsonb;
begin
  if p_generation_reference is null then p_generation_reference:=now(); end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text||':'||p_rule::text||':'||p_local_date::text,7603));
  select * into r from public.recurring_rules where organization_id=p_org and id=p_rule for update;
  if not found or not r.active or not app.feature_enabled(p_org,'feature.recurring_basic') then raise exception 'ARV-STATE-1001 recurring rule invalid'; end if;
  if not app.recurring_date_matches_rule(p_org,p_rule,p_local_date) then raise exception 'ARV-RECUR-7603 date does not match current rule'; end if;
  select * into rr from app.resolve_recurring_local_time(r.timezone,p_local_date,r.local_time);
  if rr.resolved_at > p_generation_reference + interval '60 days' then raise exception 'ARV-RECUR-7604 occurrence beyond rolling horizon'; end if;
  snapshot:=jsonb_build_object(
    'rule_id',r.id,'rule_version',r.version,'customer_id',r.customer_id,'service_catalog_id',r.service_catalog_id,'asset_id',r.asset_id,
    'recurrence_type',r.recurrence_type,'interval_value',r.interval_value,'weekday_config',r.weekday_config,'local_time',r.local_time,
    'timezone',r.timezone,'starts_on',r.starts_on,'ends_on',r.ends_on,'template_data',r.template_data
  );
  identity_key:='recurring:'||p_rule::text||':'||p_local_date::text||':v'||r.version::text;
  select id,generated_job_id into occ,jid from public.recurring_occurrences
    where organization_id=p_org and recurring_rule_id=p_rule and intended_local_date=p_local_date and intended_local_time=r.local_time and rule_version=r.version
    order by created_at limit 1 for update;
  if occ is not null then return jsonb_build_object('occurrence_id',occ,'job_id',jid,'duplicate',true,'resolved_at',rr.resolved_at,'dst_resolution',rr.dst_resolution); end if;
  insert into public.recurring_occurrences(organization_id,recurring_rule_id,intended_local_date,intended_local_time,timezone,resolved_occurrence_at,resolved_offset_minutes,dst_resolution,rule_version,rule_snapshot,status,lease_owner,lease_expires_at)
  values(p_org,p_rule,p_local_date,r.local_time,r.timezone,rr.resolved_at,rr.resolved_offset_minutes,rr.dst_resolution,r.version,snapshot,'GENERATING','db-generator',now()+interval '5 minutes')
  returning id into occ;
  jid:=gen_random_uuid();
  perform app.consume_job_limit(p_org,identity_key,jid::text);
  insert into public.jobs(id,organization_id,job_number,customer_id,title,description,status,priority,currency_code)
  select jid,p_org,app.next_document_number(p_org,'JOB'),r.customer_id,coalesce(r.template_data->>'title','Recurring service'),r.template_data->>'description','CONFIRMED',coalesce(r.template_data->>'priority','NORMAL'),o.currency_code from public.organizations o where o.id=p_org;
  duration_minutes:=nullif(r.template_data->>'visit_duration_minutes','')::int;
  if duration_minutes is not null then
    vid:=gen_random_uuid();
    insert into public.visits(id,organization_id,job_id,scheduled_start,scheduled_end,scheduled_local_start,scheduled_local_end,timezone,address_snapshot)
    values(vid,p_org,jid,rr.resolved_at,rr.resolved_at+make_interval(mins=>duration_minutes),rr.resolved_local,(rr.resolved_at+make_interval(mins=>duration_minutes)) at time zone r.timezone,r.timezone,coalesce(r.template_data->'address_snapshot','{}'));
    update public.jobs set status='SCHEDULED',scheduled_start=rr.resolved_at,scheduled_end=rr.resolved_at+make_interval(mins=>duration_minutes) where organization_id=p_org and id=jid;
  end if;
  update public.recurring_occurrences set status='GENERATED',generated_job_id=jid,lease_owner=null,lease_expires_at=null,attempts=attempts+1 where organization_id=p_org and id=occ;
  update public.recurring_rules set next_occurrence_at=null where organization_id=p_org and id=p_rule;
  perform app.activity(p_org,actor,'JOB',jid,'recurring.occurrence_generated','Recurring Job generated',jsonb_build_object('occurrence_id',occ,'rule_version',r.version,'dst_resolution',rr.dst_resolution));
  perform app.emit_event(p_org,actor,'recurring.occurrence_generated','JOB',jid,jsonb_build_object('occurrence_id',occ,'visit_id',vid,'rule_version',r.version),identity_key);
  perform app.emit_event(p_org,actor,'job.created','JOB',jid,jsonb_build_object('recurring_occurrence_id',occ),identity_key||':job');
  return jsonb_build_object('occurrence_id',occ,'job_id',jid,'visit_id',vid,'duplicate',false,'resolved_at',rr.resolved_at,'resolved_offset_minutes',rr.resolved_offset_minutes,'dst_resolution',rr.dst_resolution,'rule_version',r.version);
end $$;

-- Strict offline sequencing/dependency processor. Each action is an independent subtransaction; conflict/rejection data is retained.
create or replace function app.process_client_actions(p_org uuid,p_device_id text,p_actions jsonb) returns jsonb
language plpgsql security definer set search_path=public,app as $$
declare
  actor uuid:=app.require_member(p_org); item jsonb; existing public.client_action_receipts%rowtype; slot public.client_action_sequence_slots%rowtype;
  result jsonb; outcome text; err text; out jsonb:='[]'::jsonb; cid uuid; seq bigint; et text; eid uuid; act text; expected int; ph text; supplied_ph text; localts timestamptz; deps jsonb; dep jsonb; dep_id uuid;
  ds public.client_device_sequences%rowtype; expected_seq bigint; prior_result text;
begin
  if coalesce(trim(p_device_id),'')='' then raise exception 'ARV-OFFLINE-7001 device_id required'; end if;
  if jsonb_typeof(p_actions)<>'array' then raise exception 'ARV-OFFLINE-7001 actions must be array'; end if;
  insert into public.client_device_sequences(organization_id,member_id,device_id,last_accepted_sequence) values(p_org,actor,p_device_id,0) on conflict do nothing;
  select * into ds from public.client_device_sequences where organization_id=p_org and member_id=actor and device_id=p_device_id for update;

  for item in select * from jsonb_array_elements(p_actions) loop
    cid:=(item->>'client_action_id')::uuid; seq:=(item->>'sequence')::bigint; et:=upper(item->>'entity_type'); eid:=(item->>'entity_id')::uuid; act:=upper(item->>'action'); expected:=nullif(item->>'expected_version','')::int;
    supplied_ph:=nullif(item->>'payload_hash',''); ph:=app.command_hash(item-'payload_hash'); localts:=nullif(item->>'local_occurred_at','')::timestamptz; deps:=coalesce(item->'dependencies','[]'::jsonb);
    -- Never trust a caller-declared hash: the database hashes the normalized JSONB envelope itself.
    if supplied_ph is not null and supplied_ph<>ph then
      if exists(select 1 from public.client_action_receipts where organization_id=p_org and member_id=actor and device_id=p_device_id and client_action_id=cid) then
        outcome:='CONFLICT'; err:='ARV-CONFLICT-1001 offline action payload hash mismatch';
      else
        outcome:='REJECTED'; err:='ARV-OFFLINE-7009 payload hash mismatch';
      end if;
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      if not exists(select 1 from public.client_action_receipts where organization_id=p_org and member_id=actor and device_id=p_device_id and client_action_id=cid) then
        insert into public.client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
        values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,null,err);
      end if;
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue;
    end if;
    if seq<=0 then outcome:='REJECTED'; err:='ARV-OFFLINE-7003 sequence must be positive';
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue; end if;

    select * into existing from public.client_action_receipts where organization_id=p_org and member_id=actor and device_id=p_device_id and client_action_id=cid;
    if found and existing.result<>'RETRYABLE' then
      if existing.payload_hash<>ph or existing.sequence<>seq then
        outcome:='CONFLICT'; err:='ARV-CONFLICT-1001 offline action identity/hash mismatch';
        insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
        out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result','CONFLICT','prior_result',existing.result,'error',err));
      else
        insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,'DUPLICATE',null,item);
        out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result','DUPLICATE','prior_result',existing.result,'response',existing.response,'error',existing.error_code));
      end if;
      continue;
    elsif found and (existing.payload_hash<>ph or existing.sequence<>seq) then
      outcome:='CONFLICT'; err:='ARV-CONFLICT-1001 offline retry identity/hash mismatch';
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue;
    end if;

    expected_seq:=ds.last_accepted_sequence+1;
    if seq<expected_seq and not found then
      outcome:='CONFLICT'; err:='ARV-OFFLINE-7004 sequence already passed without matching receipt';
      insert into public.client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
      values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,null,err);
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue;
    elsif seq>expected_seq then
      outcome:='CONFLICT'; err:='ARV-OFFLINE-7005 sequence gap: expected '||expected_seq::text;
      insert into public.client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
      values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,null,err)
      on conflict(organization_id,member_id,device_id,client_action_id) do nothing;
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue;
    end if;

    insert into public.client_action_sequence_slots(organization_id,member_id,device_id,sequence,client_action_id,payload_hash)
      values(p_org,actor,p_device_id,seq,cid,ph) on conflict(organization_id,member_id,device_id,sequence) do nothing;
    select * into slot from public.client_action_sequence_slots where organization_id=p_org and member_id=actor and device_id=p_device_id and sequence=seq for update;
    if slot.client_action_id<>cid or slot.payload_hash<>ph then
      outcome:='CONFLICT'; err:='ARV-OFFLINE-7006 sequence bound to a different action identity';
      if not exists(select 1 from public.client_action_receipts where organization_id=p_org and member_id=actor and device_id=p_device_id and client_action_id=cid) then
        insert into public.client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
        values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,null,err);
      end if;
      insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,err,item);
      out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'error',err)); continue;
    end if;

    if jsonb_typeof(deps)<>'array' then outcome:='REJECTED'; err:='ARV-OFFLINE-7007 dependencies must be an array';
    else
      outcome:=null; err:=null;
      for dep in select distinct value from jsonb_array_elements(deps) loop
        begin dep_id:=coalesce(nullif(dep->>'client_action_id',''),trim(both '"' from dep::text))::uuid; exception when others then dep_id:=null; end;
        if dep_id is null or not exists(select 1 from public.client_action_receipts d where d.organization_id=p_org and d.member_id=actor and d.device_id=p_device_id and d.client_action_id=dep_id and d.result in('APPLIED','DUPLICATE')) then
          outcome:='CONFLICT'; err:='ARV-OFFLINE-7008 unresolved dependency'; exit;
        end if;
      end loop;
    end if;

    if outcome is null then
      outcome:='REJECTED'; result:=null; err:=null;
      begin
        if et='VISIT' and act in('DEPART','ARRIVE','START','FINISH','CANCEL','NO_SHOW') then result:=app.visit_action(p_org,eid,act,expected,item->>'reason',cid::text); outcome:='APPLIED';
        elsif et='CHECKLIST' and act='RESPOND' then result:=app.respond_checklist(p_org,eid,item->>'item_key',item->'payload',cid::text); outcome:='APPLIED';
        elsif act='NOTE' then result:=jsonb_build_object('note_id',app.create_note(p_org,et,eid,coalesce(item->'payload'->>'body',''),coalesce(item->'payload'->>'visibility','WORKER'),cid::text)); outcome:='APPLIED';
        else err:='ARV-OFFLINE-7002 unsupported action'; outcome:='REJECTED'; end if;
      exception when serialization_failure or deadlock_detected then outcome:='RETRYABLE'; err:='ARV-OFFLINE-7010 '||sqlerrm;
                when others then if sqlerrm like '%ARV-CONFLICT-%' or sqlerrm like '%ARV-STATE-%' or sqlerrm like '%ARV-VISIT-%' then outcome:='CONFLICT'; elsif sqlerrm like '%permission%' or sqlerrm like '%ARV-PERM-%' or sqlerrm like '%ARV-TENANT-%' then outcome:='REJECTED'; else outcome:='REJECTED'; end if; err:=sqlerrm;
      end;
    end if;

    if existing.id is not null and existing.result='RETRYABLE' then
      update public.client_action_receipts set result=outcome,response=result,error_code=left(err,240),updated_at=now(),dependencies=deps,expected_version=expected where id=existing.id;
    else
      insert into public.client_action_receipts(organization_id,member_id,device_id,client_action_id,sequence,entity_type,entity_id,action,expected_version,payload_version,payload_hash,local_occurred_at,dependencies,result,response,error_code)
      values(p_org,actor,p_device_id,cid,seq,et,eid,act,expected,coalesce((item->>'payload_version')::int,1),ph,localts,deps,outcome,result,left(err,240));
    end if;
    insert into public.client_action_attempts(organization_id,member_id,device_id,client_action_id,sequence,payload_hash,outcome,error_code,raw_action) values(p_org,actor,p_device_id,cid,seq,ph,outcome,left(err,240),item);
    -- A sequence slot is consumed once the server has durably accepted a terminal outcome.
    -- RETRYABLE remains unresolved and therefore blocks the next sequence until the identical action is retried.
    if outcome in('APPLIED','CONFLICT','REJECTED') then
      update public.client_device_sequences set last_accepted_sequence=seq,updated_at=now() where organization_id=p_org and member_id=actor and device_id=p_device_id;
      ds.last_accepted_sequence:=seq;
    end if;
    out:=out||jsonb_build_array(jsonb_build_object('client_action_id',cid,'sequence',seq,'result',outcome,'response',result,'error',err));
  end loop;
  return out;
end $$;

-- The obsolete three-argument fail_media overload bypassed idempotency and is removed from the canonical surface.
drop function if exists app.fail_media(uuid,uuid,text);

-- Final P0 function privilege lockdown. PostgreSQL grants EXECUTE to PUBLIC by default, so reset the entire app schema first.
revoke execute on all functions in schema app from public,anon,authenticated;
revoke all on schema app from public,anon;
revoke create on schema app from public,anon,authenticated;
revoke create on schema public from public,anon,authenticated;
grant usage on schema app to authenticated,service_role;
alter default privileges in schema app revoke execute on functions from public;

