 app.create_job(uuid,uuid,uuid,text,text,text,uuid,text,bigint,jsonb,text),app.update_job_fields(uuid,uuid,int,text,text,text,bigint,text),app.confirm_job(uuid,uuid,int,text),app.job_action(uuid,uuid,text,text,int,text),app.complete_job(uuid,uuid,int,text),
